-- Festival Hub · TourAPI 전국 축제(정보형) v2 · 홈페이지 포함 · 재실행 안전
-- 생성 기준일 20260821 · 진행중/향후 236건 · 출처 한국관광공사 TourAPI(KorService2)
do $$
declare adm uuid := (select id from public.profiles where role='admin' order by created_at limit 1);
begin
  if adm is null then raise exception '관리자 프로필이 없습니다'; end if;
  delete from public.events where source = 'TourAPI';
  insert into public.events
    (id, owner_id, name, category, organizer, start_date, end_date, region, address,
     visitors, capacity, fee, fee_rate, deadline, electric, water, gas, parking,
     description, contact, phone, status, kind, review_status, source, homepage, ext_id, lat, lng, geocoded_at)
  values
    (gen_random_uuid(), adm, '가든 나이트 마켓', '축제', '가든 나이트 마켓', '2026-07-29', '2026-08-29', '울산', '울산광역시 남구 대공원로 94 (옥동)', null, null, 0, 0, null, false, false, false, false, '가든 나이트 마켓은 여름 시즌을 맞이하여 도심 속 공원에서 개최되는 야시장이다. 10개의 판매부스, 5개의 체험부스, 10개의 먹거리부스 및 16개의 푸드트럭으로 구성되어 있어 시민과 관광객들에게 다양한 경험을 제공한다. 아이와 방문한 참가자들을 위해 놀이시설, 숲체험 등이 준비되어 있고, 다채로운 버스킹 공연이 한 여름밤의 감성을 더한다. 무더운 여름 속에서 활기찬 야시장은 야간 테마 관광지로서 참가자들에게 신선하고 색다른 경험을 제공한다.', null, '052-255-1823', 'open', 'info', 'approved', 'TourAPI', 'http://ulsanstorynightmarket.com/', '4090201', 35.5310582726, 129.2938457635, now()),
    (gen_random_uuid(), adm, '가야테마파크 빛 축제 빛을 향한 항해', '축제', '가야테마파크 빛 축제 빛을 향한 항해', '2026-08-14', '2026-08-23', '경남', '경상남도 김해시 가야테마길 161 (어방동)', null, null, 0, 0, null, false, false, false, false, '2천 년 전 허왕후가 인도 아유타국에서 가야로 향했던 바닷길이 찬란한 빛으로 되살아난다. 2026년 8월 14일부터 23일까지 김해가야테마파크에서 열리는 제3회 김해 빛 축제 ‘빛을 향한 항해’는 출항·항해·가야와의 만남으로 이어지는 이야기를 빛 조형물, 일루미네이션, 미디어아트와 포토존으로 선보인다. 푸른 바다와 밤하늘을 닮은 빛의 길을 따라 걸으며 가야와 인도의 특별한 인연을 만날 수 있다. 주말과 공휴일에는 로컬먹거리존과 지역 창작자 아트마켓, 재즈·퓨전국악·어쿠스틱 야외공연이 더해진다. 8월 15일 개막행사에서는 오고무, K-POP 트론 퍼포먼스와 3천여 발의 멀티미디어 불꽃쇼가 밤하늘을 수놓는다. 축제는 휴무 없이 오후 5시 20분부터 10시까지 운영되며 입장 마감은 오후 9시, 입장료는 1인 2,000원이다. 빛과 역사, 공연, 먹거리, 예술이 어우러진 김해의 특별한 여름밤을 만날 수 있다.', null, '055-340-7900~1', 'open', 'info', 'approved', 'TourAPI', 'https://gtp.ghct.or.kr/home/main', '4098571', 35.2516381404, 128.8937552774, now()),
    (gen_random_uuid(), adm, '감악산 꽃별 여행', '축제', '감악산 꽃별 여행', '2026-09-18', '2026-10-11', '경남', '경상남도 거창군 신원면 연수사길 452', null, null, 0, 0, null, false, false, false, false, '제6회 감악산 꽃별여행은 2026년 9월 18일부터 10월 11일까지 거창군 신원면 감악산 정상 별바람언덕 일원에서 열리는 가을 대표 축제다. 올해 주제는 ‘나를 위한 보라색 쉼표 하나’로, 가을의 정취와 감악산의 자연 풍광을 배경으로 다양한 공연과 체험, 먹거리가 어우러진다. 축제는 9월 18일 개장행사로 본격 시작되며, 식전 공연과 개장 퍼포먼스, 구절초 단지 탐방이 진행된다. 축제 기간에는 버스킹 공연, 노을빛 언덕 음악회, 거창악우회 축하공연, 어린이를 위한 마술쇼 등 다양한 무대가 관람객을 맞이한다. 체험 프로그램도 풍성하다. 행사장 곳곳에 설치된 포토존과 스탬프 투어, SNS 인증 이벤트 등을 통해 기념품을 받을 수 있다. 별바람언덕에는 편지를 써서 내년 행사 전에 받아볼 수 있는 느린 우체통이 설치되며 많은 볼거리를 제공한다. 먹거리 또한 축제의 큰 즐거움이다. 지역 농가와 업체들이 참여하는 꽃별마켓에서는 거창 특산품과 가공품을 만날 수 있다. 또한 남상면·신원면 부녀회가 운영하는 먹거리 장터에서는 비빔밥, 국밥, 전, 두부김치 등 푸짐한 음식을 저렴한 가격에 맛볼 수 있으며, 푸드트럭존에서는 커피, 식혜, 핫도그 등 간편한 먹거리도 즐길 수 있', null, '055-940-8227', 'open', 'info', 'approved', 'TourAPI', 'https://starwindhill.com/', '2746930', 35.5896217023, 127.9175083031, now()),
    (gen_random_uuid(), adm, '강남페스티벌', '축제', '강남페스티벌', '2026-10-02', '2026-10-05', '서울', '서울특별시 강남구 도산대로 320 (논현동)', null, null, 0, 0, null, false, false, false, false, '10월 2일부터 10월 5일까지 도심 전역을 무대로 펼쳐지는 최대 규모의 도시형 축제 ‘2026 강남페스티벌’​이 개최된다. 개막을 알리는 화려한 거리 퍼레이드를 시작으로, K-POP 콘서트, 온 가족이 함께 즐기는 패밀리 콘서트, K-패션과 퍼포먼스가 결합된 패션·뷰티페스타, 다양한 미식을 경험할 수 있는 비어·푸드페스타까지 강남 전역이 하나의 거대한 축제 공간이 되어 국내외 관광객에게 밤하늘을 수놓는 빛과 음악, 거리 곳곳에서 펼쳐지는 공연과 체험, 그리고 문화와 미식이 어우러지는 특별한 시간을 선사 할 것이다. 도시의 에너지와 한류 콘텐츠가 결합된 글로벌 K-컬처 페스티벌, 강남페스티벌은 강남의 매력을 세계에 알리는 대표 문화관광 행사이다.', null, '02-3423-5543', 'open', 'info', 'approved', 'TourAPI', 'https://www.visitgangnam.net/festival', '737479', 37.5221428648, 127.0369343307, now()),
    (gen_random_uuid(), adm, '강동선사문화축제', '축제', '강동선사문화축제', '2026-10-16', '2026-10-18', '서울', '서울특별시 강동구 올림픽로 875 (암사동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*올해로 제30회를 맞이한 강동선사문화축제는 서울시 축제 중 유일하게 선사시대를 테마로 열리는 축제로, 선사유적지의 역사적 가치를 알리는 동시에, 선사인들의 삶의 모습을 체험할 수 있는 다채로운 프로그램들을 자랑한다. 올해는 서울 암사동 유적 발견 100주년을 기념하여 ‘6000년의 숨결, 100년의 빛, 30년의 울림’이라는 주제로 ‘물, 불, 흙, 바람’ 4원소를 주제로 한 별개의 공간으로 구성된다. 각 공간은 소재의 특징에 맞는 연출과 다양한 전시·체험 및 야간 프로그램들, 맛있는 먹거리들, 그리고 다채로운 공연들로 축제의 3일을 가득 채워 관람객들에게 과거와 현재를 넘나드는 특별한 즐거움들을 선사할 예정이다.', null, '02-3425-5240', 'open', 'info', 'approved', 'TourAPI', 'http://www.gdsunsa.com', '1307813', 37.55906143476573, 127.13060065465167, now()),
    (gen_random_uuid(), adm, '강릉커피축제', '축제', '강릉커피축제', '2026-10-21', '2026-10-25', '강원', '강원특별자치도 강릉시 창해로14번길 20-1 (견소동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 지방자치단체 중 최초로 개최된 커피축제로 매해 30만명이 넘는 관람객과 커피 업계 종사자 뿐만 아니라 커피 애호가들을 커피도시 강릉으로 불러 모으는 강릉 대표 축제이다. 이제 커피는 단순히 먹거리가 아닌 문화로 자리 잡았다. GCF는 커피문화를 이끄는 리더로서 그 역할을 하고 있다.', null, '033-647-6802', 'open', 'info', 'approved', 'TourAPI', 'https://www.coffeefestival.net/', '825295', 37.7726104945, 128.9473094259, now()),
    (gen_random_uuid(), adm, '거제맥주축제', '축제', '거제맥주축제', '2026-09-11', '2026-09-12', '경남', '경상남도 거제시 장승로 138 (장승포동)', null, null, 0, 0, null, false, false, false, false, '2026 거제맥주축제는 아름다운 장승포항 밤바다를 배경으로 시원한 생맥주와 다채로운 공연을 함께 즐길 수 있는 거제의 대표 가을 축제이다. 무제한 생맥주와 지역 먹거리, 푸드트럭이 어우러진 미식 공간은 물론, EDM·K-POP·7080 등 다양한 장르의 공연과 시민 참여 이벤트로 남녀노소 모두가 함께 즐길 수 있는 특별한 시간을 선사한다. 또한 관광 홍보부스와 포토존, 지역 막걸리 전시·시음 체험, 베리어프리존 운영, 다회용기 사용 등 ESG 가치를 반영한 친환경·포용형 축제로, 누구나 안전하고 편안하게 즐길 수 있는 거제의 새로운 야간 관광 콘텐츠를 선보인다.', null, '055-639-8193', 'open', 'info', 'approved', 'TourAPI', 'http://www.geojefesta.com/', '2614762', 34.8663308815, 128.7245993248, now()),
    (gen_random_uuid(), adm, '경남고성공룡세계엑스포', '축제', '경남고성공룡세계엑스포', '2026-09-22', '2026-11-01', '경남', '경상남도 고성군 당항만로 1116', null, null, 0, 0, null, false, false, false, false, '경남고성공룡세계엑스포는 대한민국 경상남도 고성군 회화면 당항포관광지에서 개최되는 공룡을 주제로 한 축제이다. 고성군은 세계 3대 공룡발자국 화석 원산지로 널리 알려진 지역으로 여러 지역에서 발견된 크고 작은 공룡화석의 가치를 알리고 관광산업을 알리기 위하여 2006년부터 개최되어 왔다. 행사장인 당항포관광지는 공룡테마존과 이순신테마존으로 구성되어 있며, 해안산책로, 등산로, 공룡 발자국 탐방로 등의 야외 테마 공원을 갖추고 있다. 행사의 주최는 경상남도 고성군이며, 2026년 현재 (재)고성문화관광재단에서 경남고성공룡세계엑스포를 운영하고 있다. 2026년 엑스포는 10회째, 20주년을 맞았으며 ''공룡과 떠나는 신나는 모험''을 주제로 개최된다. 또한, 매회 다양한 전시·체험 프로그램과 공연을 통해 국내 대표 공룡 테마 축제로 자리매김하고 있다.', null, '055-670-7400', 'open', 'info', 'approved', 'TourAPI', 'www.gngsctf.or.kr', '141105', 35.0533072967, 128.3915143393, now()),
    (gen_random_uuid(), adm, '경복궁 별빛야행', '축제', '경복궁 별빛야행', '2026-09-02', '2026-10-24', '서울', '서울특별시 종로구 사직로 161 (세종로)', null, null, 0, 0, null, false, false, false, false, '경복궁 별빛야행은 경복궁의 북측 권역을 탐방하며 궁중음식과 전통문화를 체험하는 야간 탐방 프로그램이다. 전문 해설과 함께 궁궐 곳곳을 이동하며 조선시대 왕실의 생활과 경복궁에 얽힌 역사적 이야기를 살펴보고, 궁궐의 부엌인 외소주방에서는 조선시대 궁중 수라상을 현대적으로 재해석한 특별한 12첩 반상을 ''도슭'' 형태로 만나볼 수 있다. 올해는 고종의 서재인 집옥재에서 왕의 이야기를 담은 특별 창극을 선보여 공간의 역사와 공연이 어우러진 색다른 경험을 제공하며, 이어 향원지에 담긴 별빛을 바라보며, 경복궁의 고요한 경관 속에서 낮과는 다른 정취를 즐길 수 있다. 궁중음식에 담긴 조선 왕실의 식문화와 역사적 공간, 아름다운 야경과 전통문화가 어우러진 경복궁의 별빛야행에서 특별하고 따뜻한 궁궐의 밤을 만나볼 수 있다.', null, '1522-2295', 'open', 'info', 'approved', 'TourAPI', 'https://www.kh.or.kr/short/g6cX', '2648460', 37.5760307000, 126.9767218661, now()),
    (gen_random_uuid(), adm, '경북영주 풍기인삼축제', '축제', '경북영주 풍기인삼축제', '2026-10-03', '2026-10-11', '경북', '경상북도 영주시 풍기읍 성내리', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*인삼은 기력 회복과 면연력 증진에 도움이 되는 한국의 대표적인 보양식품이다. 인삼의 영양분이 가장 많은 시기인 10월 한국에서 손꼽히는 인삼 산지 중 하나인 영주에서 풍기인삼축제가 열린다. 건강을 상징하는 인삼을 테마로 하는 축제답게 건강관련 전시와 체험 위주로 진행된다. 영양만점 풍기인삼으로 만든 인삼요리를 맛볼수 있으며 인삼깎기, 인삼병주 만들기, 황금인삼을 찾아라! 등 풍기인삼과 관련된 재미있는 체험도 할 수 있다. 또한 지역 인삼 농민들이 정성껏 수확한 수삼과 홍삼, 인삼으로 만든 가공식품도 저렴하게 구입할 수 있다.', null, '054-635-0020', 'open', 'info', 'approved', 'TourAPI', 'http://pgginsengfestival.co.kr', '506766', 36.868718, 128.521518, now()),
    (gen_random_uuid(), adm, '경산 갓바위소원성취축제', '축제', '경산 갓바위소원성취축제', '2026-09-19', '2026-09-20', '경북', '경상북도 경산시 와촌면 대한리', null, null, 0, 0, null, false, false, false, false, '''제25회 경산갓바위소원성취축제’는 보물 ‘경산 팔공산 관봉석조여래좌상(갓바위)’의 오랜 기도와 소원 성취 전통을 담은 축제이다. ‘천년 소원 성지, 경산 갓바위 르네상스’라는 슬로건 아래 전통문화와 현대 공연이 어우러지는 참여형 문화축제로, 오는 9월 19일부터 20일까지 2일간 갓바위 제3공영주차장 일대에서 개최된다. 9월 19일에는 락밴드·각설이 공연, 법문, 소리명상, 음성공양 등이 어우러지는 야단법석 법회를 시작으로, 개막식에서는 화합의 소원 비빔밥 공양 퍼포먼스와 함께 국악인 남상일, 가수 라디&정인이 다채로운 울림을 전하는 힐링음악회가 열린다. 9월 20일에는 경산시립교향악단과 바리톤 김동규, 소프라노 강혜정, 경산시립합창단이 협연하여 품격 있는 산사음악회를 선사한다. 행사장에서는 사찰런, 홍승스님의 사찰음식 시연, 나만의 소원등 달기 등 시민과 관광객이 직접 참여하고 힐링할 수 있는 체험 프로그램이 진행된다. 지역 대표 특산물인 ''와촌 자두''를 비롯한 경산 농특산물 판매 부스와 먹거리 장터가 마련되어 풍성한 먹거리와 즐길 거리 속에서 모두의 소원 성취를 기원하는 경산시의 대표 축제이다', null, '053-819-0334', 'open', 'info', 'approved', 'TourAPI', 'https://gsctf.or.kr/user/performance/view?idx=102', '140897', 35.9850010000, 128.7495400000, now()),
    (gen_random_uuid(), adm, '계룡軍문화축제', '축제', '계룡軍문화축제', '2026-10-01', '2026-10-05', '충남', '충청남도 계룡시 신도안면 정장리', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* "계룡의 꿈, 세계로 비상하는 K-軍문화!" 계룡軍문화축제가 9.17.(수) ~ 9.21.(일)까지 계룡대 활주로 및 시내 일원에서 펼쳐진다. 대한민국 명품 축제인 2025계룡軍문화축제는 개막 축하공연, 락 트로트, K-POP 등 장르별 軍문화 페스타 콘서트, 군악의장 초청 공연, 로드 퍼레이드 등 다채호운 공연 프로그램 및 익스트림 특별체험관 등 각종 체험 부대 행사로 軍문화의 위상을 높이고, 전세대가 함께 즐길 수 있는 다양한 콘텐츠를 선보일 예정이다. 특히 금년도는 ''웰니스라이프 특별전시관''을 함께 운영해 군문화와 라이프스타일이 융합된 새로운 축제 콘텐츠를 선보일 예정이다.', null, '042-840-2621~4', 'open', 'info', 'approved', 'TourAPI', 'www.gcfct.org', '2992940', 36.3067687000, 127.2371112000, now()),
    (gen_random_uuid(), adm, '계촌 휴 페스티벌', '축제', '계촌 휴 페스티벌', '2026-09-12', '2026-09-13', '강원', '강원특별자치도 평창군 방림면 계촌리', null, null, 0, 0, null, false, false, false, false, '계촌 휴[休] 북&뮤직 페스티벌은 클래식 음악으로 오랜 시간 예술의 가치를 이어온 계촌마을에서 새롭게 선보이는 휴식 문화 축제이다. 빠르게 흘러가는 일상 속에서 잊고 지낸 ‘쉼’의 의미를 다시 발견할 수 있도록, 책(Book), 음악(Music), 자연(Nature)이 어우러진 특별한 경험을 할 수 있다. 푸른 자연을 품은 계촌에서는 클래식 공연과 북 프로그램, 체험 콘텐츠, 로컬 다이닝, 참여형 워크숍이 마을 곳곳에서 진행된다. 비닐하우스는 작은 콘서트홀이 되고, 공원은 책과 음악이 만나는 공간이 되며, 자연 속 식탁은 지역의 맛과 이야기를 나눌 수 있다. 관람객은 단순히 공연을 관람하는 것을 넘어 자연과 예술 속에 머물며 자신만의 속도로 하루를 채워가는 온전한 휴식을 경험할 수 있다. 계촌 휴[休] 북&뮤직 페스티벌은 지역 주민과 예술가, 방문객이 함께 만들어가는 계촌클래식예술마을 조성사업의 비전을 담은 축제이다.', null, '02-966-6561', 'open', 'info', 'approved', 'TourAPI', 'https://gchf.kr/', '3520743', 37.4521910000, 128.3023520000, now()),
    (gen_random_uuid(), adm, '고령 국가유산야행', '축제', '고령 국가유산야행', '2026-09-04', '2026-09-06', '경북', '경상북도 고령군 대가야읍 대가야로 1216', null, null, 0, 0, null, false, false, false, false, '국가유산과 함께 고령의 밤을 즐기는 2026 고령 국가유산 야행이 다가오는 2026년 9월 4일부터 6일까지 대가야역사테마관광지에서 개최된다. 대가야(大佳夜) : 아름다운 밤을 주제로 개최되는 2026 고령 국가유산 야행은 밤을 밝히는 다양한 불과 빛을 활용한 프로그램으로 구성될 예정이다. 2026 고령 국가유산 야행은 우륵지에서 열리는 낙화놀이를 필두로 불을 소재로 한 공연과 명사 초청 토크콘서트, 역사문화체험 등 국가유산을 오감으로 즐기는 다양한 프로그램이 준비되어 있다. 뿐만아니라, 고령군 내에서 소비한 당일 영수증 인증 시 기념품을 제공하는 소비 활성화 프로그램이 시행되어 행사장을 넘어 고령군 전역과 함께 즐기는 축제의 장이 마련된다.', null, '054-955-0554', 'open', 'info', 'approved', 'TourAPI', 'http://www.yahaeng.or.kr/', '4091713', 35.7192916000, 128.2605623000, now()),
    (gen_random_uuid(), adm, '고성명태축제', '축제', '고성명태축제', '2026-10-02', '2026-10-05', '강원', '강원특별자치도 고성군 거진읍 해오름해변길 125', null, null, 0, 0, null, false, false, false, false, '고성명태축제는 강원특별자치도 고성군의 역사·문화 자산인 명태문화를 현대적으로 재해석하는 지역 문화축제이다. 2026년에는 거진읍 11리 해변을 배경으로 ‘명태의 발견’, ‘주민의 발견’, ‘바다의 발견’이라는 세 가지 영역을 운영한다. 명태미식존과 셰프 라이브쿠킹, 셀프요리 체험, 명태 공예·놀이 등 명태를 먹고 만들고 즐기는 프로그램을 마련한다. 지역 주민과 예술인, 군 장병, 청소년이 공연과 마을방송국, 음식점 및 소품 판매에 직접 참여하며, 맨손활어잡기와 바다놀이터, 사일런스 DJ 등 해변 체험도 함께 즐길 수 있다. 분산형 무대와 상시 프로그램, 셔틀 운영을 통해 방문객이 어느 시간대에 찾아도 머물며 즐길 수 있는 체류형 축제장을 조성한다.', null, '033-681-0121', 'open', 'info', 'approved', 'TourAPI', null, '421977', 38.4395315630, 128.4542520129, now()),
    (gen_random_uuid(), adm, '고양행주한우 숯불구이축제', '축제', '고양행주한우 숯불구이축제', '2026-10-31', '2026-11-01', '경기', '경기도 고양시 덕양구 원당로 16 (주교동)', null, null, 0, 0, null, false, false, false, false, '행주한우 숯불구이 축제는 고양특례시를 대표하는 명품 한우 브랜드 ‘행주한우’의 우수성을 널리 알리고 시민과 함께 즐거움을 나누기 위해 마련된 지역 축제이다. 철저한 품질관리로 생산된 안전하고 건강한 축산물을 직접 맛볼 수 있으며, 숯불 위에서 구워낸 행주한우의 깊은 풍미를 통해 특별한 미식 경험을 선사하는 행사이다. 또한 지역 농가와 소비자가 함께 소통하며 화합과 풍요로움을 나누는 뜻깊은 축제이다.', null, '031-960-3034,3050', 'open', 'info', 'approved', 'TourAPI', 'http://gyfestival.kr/', '3383613', 37.654669772497314, 126.83276387204035, now()),
    (gen_random_uuid(), adm, '고양호수예술축제', '축제', '고양호수예술축제', '2026-09-18', '2026-09-20', '경기', '경기도 고양시 일산동구 호수로 595 (장항동)', null, null, 0, 0, null, false, false, false, false, '일상 속 공간이 특별한 예술의 리듬으로 채워지는 순간이 2026 고양호수예술축제에서 펼쳐진다. 서커스, 마술, 공중 퍼포먼스 등 장르의 경계를 넘나드는 다채로운 거리예술 공연 100여회와, 누구나 함께 즐기는 체험 프로그램이 찾아온다. 일산호수공원 곳곳에서 펼쳐지는 생동감 넘치는 공연은 관객과 예술가가 함께 호흡하며 소통하는 특별한 경험을 선사하고, 호수의 밤을 밝히는 불꽃놀이와 야간 특별 프로그램은 잊지 못할 낭만을 선사할 것이다. 올 가을, 재미와 설렘이 경쾌하게 피어나는 2026 고양호수예술축제에서 특별한 순간을 만날 수 있다.', null, '1577-7766', 'open', 'info', 'approved', 'TourAPI', null, '1100492', 37.6552847261, 126.7689082803, now()),
    (gen_random_uuid(), adm, '고창모양성제', '축제', '고창모양성제', '2026-10-15', '2026-10-19', '전북', '전북특별자치도 고창군 고창읍 모양성로 11', null, null, 0, 0, null, false, false, false, false, '고창모양성제는 국내에서 가장 원형이 잘 보존된 모양성을 주제로 한 역사문화축제이다. 대표프로그램은 답성놀이로서 한바퀴 돌면 다릿병이 낫고, 두바퀴돌면 무병장수하며, 세 바퀴돌면 극락승천 한다는 전설을 체험형 프로그램으로 개발했다. 이 외에도, 답성놀이와 강강술래를 혼합하여 군민과 관광객이 함께 어우러진 야간답성강강술래달밤, 과거현재미래를 표현한 주민 1,000여명이 참여하는 거리 퍼레이드, 과거로의 여행을 주제로 하여 고창읍성 내부를 누비며 즐길 수 있는 리턴즈1453, 그리고 고창지역의 특산물을 활용한 먹거리와 직거래장터 등을 운영한다.', null, '063-560-2949', 'open', 'info', 'approved', 'TourAPI', 'https://www.xn--v52bo3j80dp4c.com/', '604454', 35.43314793158578, 126.70350182663505, now()),
    (gen_random_uuid(), adm, '공주 국가유산야행', '축제', '공주 국가유산야행', '2026-09-04', '2026-09-06', '충남', '충청남도 공주시 우체국길 8', null, null, 0, 0, null, false, false, false, false, '국가유산 야행은 국가유산 집적지역을 거점으로 국가유산과 지역의 특색 있는 역사문화자원을 연계 활용한 관람, 체험, 공연, 전시 등 야간 특화 프로그램이다. 공주 국가유산 야행은 공주 왕도심 일원 근대 국가유산(옛 공주읍사무소, 공주제일교회 등)을 중심으로 이루어지며, 8가지 야간 테마를 주제로 한 프로그램을 진행한다. 올해는 행사 10년 연속 개최와 1926년 간행된 ''공주시가도'' 100주년을 맞이하여, 이를 기념하고 축하하는 의미에서 ''1926 공주 낭만연회''를 부제로 진행한다. 행사장을 찾는 방문객에게 100년 전 공주 근대사를 담은 다채로운 프로그램을 선사한다.', null, '041-852-8063', 'open', 'info', 'approved', 'TourAPI', 'https://gongju-culturenight.com/', '2614763', 36.4543392909, 127.1220001033, now()),
    (gen_random_uuid(), adm, '과천공연예술축제', '축제', '과천공연예술축제', '2026-09-18', '2026-09-20', '경기', '경기도 과천시 관문로 64 (중앙동)', null, null, 0, 0, null, false, false, false, false, '1997년 세계마당극큰잔치로 시작된 과천공연예술축제는 국내 최초의 거리극 축제로 매년 9월 국내외 야외극·거리극을 중심으로 한 수준 높은 공연으로 매년 개최되며, 국내외 예술가들의 실험의 장으로써 해외공연, 국내공연, 기획공연 등 축제기간동안 풍성한 볼거리를 제공하여 일반 시민 누구나 부담없이 다양한 문화를 즐길 수 있는 축제다. 매년 10만명 이상의 관람객이 찾아오는 과천공연예술축제는 아시아를 대표하는 축제로 발전하고 시민과 함께 만들어가는 시민 주도형 예술 축제로, 2023년부터 과천공연예술축제(GPAF)로 축제명을 변경하여 광장 집중형 공연예술축제로서 시민들과 함께한다.', null, '02-2009-9735', 'open', 'info', 'approved', 'TourAPI', 'https://www.gcfest.or.kr/', '2029491', 37.4273687532, 126.9893038180, now()),
    (gen_random_uuid(), adm, '관악강감찬축제', '축제', '관악강감찬축제', '2026-10-16', '2026-10-18', '서울', '서울특별시 관악구 낙성대로 77 (봉천동)', null, null, 0, 0, null, false, false, false, false, '관악강감찬축제는 역사를 품은 도시 관악에서 귀주대첩의 영웅 강감찬 장군의 호국정신과 위업을 기리고자 개최되는 서울의 대표적인 역사문화 축제이다. 관악강감찬축제는 고려 명장 강감찬 장군의 호국정신을 기리고자 개최되는 서울의 대표적인 역사 문화축제이자, 관악구민이 함께 만들고 즐기는 관악의 대표 축제이다. 강감찬축제는 1998년부터 이어 온 관악구 대표 전통문화축제 ‘관악산 철쭉제’와 1988년부터 이어 온 추모제향 ‘낙성대 인헌제’를 통합하여, 2016년 새롭게 시작되었다. 강감찬축제는 북두칠성의 네 번째 별 문곡성이 떨어진 곳에서 강감찬 장군이 탄생하였다는 낙성대, 장군의 시호를 딴 인헌동, 장군이 송도를 오갈 때 자주 들렀다는 정자가 있는 서원동 등 장군의 얼이 서린 문화유산을 배경으로 오늘날 우리들의 모습으로 다양한 프로그램을 진행하며 그 뜻을 이어가고 있다. 10월 셋째주 ''투모로우 강감찬''이 시작된다. 2026년 10주년을 맞이하는 관악강감찬축제는 K-컬처를 품은 서울 대표 고려 역사문화축제로 콘텐츠를 확장시켜 세대를 잇고 지역을 살리는 지속 가능한 상생 축제로 새롭게 발돋움 한다.', null, '02-828-5766', 'open', 'info', 'approved', 'TourAPI', 'https://www.ggcfest.com/', '2612274', 37.4715875501, 126.9587204342, now()),
    (gen_random_uuid(), adm, '광안리 M(Marvelous) 드론 라이트쇼', '축제', '광안리 M(Marvelous) 드론 라이트쇼', '2026-01-01', '2026-12-31', '부산', '부산광역시 수영구 광안해변로 219 (광안동)', null, null, 0, 0, null, false, false, false, false, '2022년부터 개최된 광안리 M(Marvelous) 드론 라이트쇼는 "M"은 ''놀라운, 경이로운''이라는 뜻의 ''Marvelous''를 의미하는 것으로 드론이 뿜어내는 불빛이 부산의 랜드마크인 광안대교의 야경과 어우러져 광안리를 찾는 방문객들에게 경이로움과 신비로움을 선사함을 나타낸다. 매주 토요일 저녁 2회 (동절기 10월~2월, 19시·21시 / 하절기 3월~9월 20시·22시) 12분 내외로 상연되며 광안리 해변 어디서나 관람이 가능하다. 매주 1,100대의 드론으로 펼쳐지는 상설공연부터 카운트다운·설·추석 등에는 최대 3,000대 규모까지 다양한 규모의 드론쇼가 개최되고 있다. * 기상상황 등에 따라 공연 일정 변경 가능', null, '051-610-6518', 'open', 'info', 'approved', 'TourAPI', 'https://www.gwangallimdrone.co.kr/', '2786391', 35.1537727886, 129.1185199367, now()),
    (gen_random_uuid(), adm, '광주 추억의 충장축제', '축제', '광주 추억의 충장축제', '2026-10-07', '2026-10-11', '서울', '전남광주통합특별시 동구 금남로3가', null, null, 0, 0, null, false, false, false, false, '*하기 축제장 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 광주 추억의 충장축제는 전남광주통합특별시 최고의 상권인 전남광주 동구 ''충장로''에서 시작된 전남광주통합특별시 최대 규모의 광주대표 축제이다. 이 축제는 ''추억''이라는 보편적 소재를 통해 세대와 계층을 아우르는 ''국내 최초의 추억 테마 축제''로서 특별한 의미를 지닌다. 누구나 간직하고 있는 소중한 추억을 공유하며, 다양한 연령대와 배경을 가진 사람들이 하나로 어우러지는 새로운 추억을 만들어내는 추억생산의 공간을 만들어낸다. 특히 축제의 핵심 공간인 금남로와 5·18민주광장이라는 세계 민주주의 역사 속 의미 깊은 공간을 중심으로 펼쳐진다는 점에서, 단순한 지역축제를 넘어선 역사적·문화적 가치를 담고 있다. 민주화의 성지에서 열리는 축제로서 과거의 아픔을 딛고 희망찬 미래를 향한 시민들의 의지를 보여주는 상징적 의미를 지닌다. 충장축제는 그 우수성을 대외적으로 인정받아 2024년 문화체육관광부 명예 문화관광축제로 최초 지정된 이후, 2026~2027년 명예 문화관광축제로 재선정되며 4년 연속(2024년~2027년) 명예 문화관광축제 자리를 지켰다. ', null, '062-608-4672', 'open', 'info', 'approved', 'TourAPI', 'http://recollection.kr/index.php', '692682', 35.1502410000, 126.9158700000, now()),
    (gen_random_uuid(), adm, '광주김치축제', '축제', '광주김치축제', '2026-10-23', '2026-10-25', '서울', '전남광주통합특별시 서구 내방로 111 (치평동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*전남광주통합특별시는 예로부터 영산강을 중심으로 펼쳐진 평야와 산, 들, 바다가 한데 어우러져 오랫동안 자연의 혜택을 받으며 맛의 고장으로 자리 잡았다. 그중에서도 전남광주통합특별시 김치는 가장 풍요로운 맛과 정취를 담고 있어 전라도 김치, 전남광주통합특별시 김치 라는 고유명사로 알려질 정도다. 전남광주통합특별시 김치는 갖은 채소를 비롯해 멸치액젓과 찹쌀풀죽, 통깨 등 양념을 듬뿍 넣는 것이 특징이다. 신선한 재료를 골라 정성스럽게 손질하고 가장 기본적인 방법으로 담그는 것, 그리고 거기에 손맛을 더하는 것. 이것이 바로 전남광주통합특별시 김치의 특별 레시피다. 광주세계김치축제는 김치에 담긴 우리 고유의 음식문화와 전통이 만나는 시민 체험의 장이며, 대한민국 김치 대표 축제로서 모두가 함께 즐기는 축제이다. 김치관련 생산자와 소비자간의 거래와 홍보가 함께 이루어지는 알짜베기 축제라고 할 수 있다.', null, '062-613-3955~6', 'open', 'info', 'approved', 'TourAPI', 'https://kimchi.gwangju.go.kr', '604097', 35.1590033102, 126.8530264839, now()),
    (gen_random_uuid(), adm, '광주버스킹월드컵', '축제', '광주버스킹월드컵', '2026-10-07', '2026-10-11', '서울', '전남광주통합특별시 동구 금남로1가 41 금남지하상가', null, null, 0, 0, null, false, false, false, false, '광주버스킹월드컵은 광주광역시 동구 충장로 일원에서 개최되는 국제 거리공연 음악축제이다. 본 행사는 국내외 거리공연 예술가들이 참여하여 다양한 음악 공연을 선보이는 경연형 축제로 보컬, 밴드, 어쿠스틱, 퍼포먼스 등 다양한 장르의 무대를 만날 수 있다. 참가팀은 예선과 본선을 거쳐 결선에서 최종 우승팀을 가리며 전문 심사위원의 심사를 통해 수상팀을 선정한다. 광주 도심 곳곳을 무대로 개최되는 본 행사는 도시 공간을 활용한 문화예술 활성화와 거리공연 문화 확산을 도모하고 글로벌 문화교류와 관광 활성화에 기여하는 국제 문화 행사이다.', null, '062-228-9812', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.buskingworldcup.com/kor/
