    (gen_random_uuid(), adm, '국토정중앙 청춘양구 배꼽축제', '축제', '국토정중앙 청춘양구 배꼽축제', '2026-08-28', '2026-08-30', '강원', '강원특별자치도 양구군 양구읍 상리 394-21', null, null, 0, 0, null, false, false, false, false, '국토의 정중앙에 위치한 강원도 양구에서 개최되는 ''배꼽축제''는 지역의 독창적인 지리적 상징성을 바탕으로 기획된 대표적인 종합 문화예술축제이다. 올해는 특히 문화적 배꼽시점 ''배꼽 로그인''을 슬로건으로 배꼽축제를 하나의 플레이어로 입장한다. 이 축제는 무더위를 날려버리기 위한 다채로운 워터 하이브리드 프로그램을 중심으로 남녀노소 누구나 참여해 함께 웃고 즐길 수 있는 화합의 장을 제공한다. 행사장 일대에서는 흥겨운 분위기를 더하는 거리 퍼레이드와 밤하늘을 수놓는 화려한 불꽃 쇼가 진행된다. 아울러 요일별로 다채롭게 진행되는 콘서트와 특색 있는 군장병 콘서트 등 민군관이 함께 아우르는 풍성한 공연이 이어져 방문객들에게 볼거리와 즐거움을 경험할 수 있다.', null, '033-482-9174', 'open', 'info', 'approved', 'TourAPI', 'https://ygcf.or.kr/Festival/', '1018971', 38.1044366000, 127.9830546000, now()),
    (gen_random_uuid(), adm, '군산시간여행축제', '축제', '군산시간여행축제', '2026-10-02', '2026-10-05', '전북', '전북특별자치도 군산시 중앙로1가', null, null, 0, 0, null, false, false, false, false, '군산시간여행축제는 일제강점기 민중의 항거와 치열한 삶의 역사를 간직한 근대 군산을 배경으로, 군산의 과거와 현재, 그리고 미래를 잇는 특별한 시간여행을 선사하는 축제이다. 올해는 더욱 풍성한 콘텐츠와 참여형 프로그램을 통해 시민과 관광객이 함께 만들어가는 축제로 운영된다. 시민들이 직접 참여하는 근대 시기 글로벌적 콘텐츠를 집약적으로 보여주는 대규모 플래시몹 공연, 거리 가득 만세의 함성을 재현하는 우리 모두 3.5만세, 시간을 모아 기념품으로 교환하거나, 다양한 이벤트 참여, 할인권 교환 등 모아모아시간 등 풍성한 프로그램이 마련된다. 다양한 체험 프로그램, 7080 감성을 담은 추억의 놀거리와 먹거리까지 더해져 온 가족이 함께 즐길 수 있는 축제로 운영된다. 역사의 의미를 되새기며 즐거움까지 함께 누릴 수 있는 군산시간여행축제는 세대와 지역을 아우르며 누구나 공감하고 참여할 수 있는 군산의 대표축제로 방문객들에게 특별한 시간여행의 경험을 선사할 예정이다.', null, '063-454-3300', 'open', 'info', 'approved', 'TourAPI', 'https://festival.gunsan.go.kr/', '1846797', 35.9877910000, 126.7116710000, now()),
    (gen_random_uuid(), adm, '금산세계인삼축제', '축제', '금산세계인삼축제', '2026-10-02', '2026-10-11', '충남', '충청남도 금산군 금산읍 인삼광장로 30', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*1,500여년의 역사가 깃든 인삼의 본고장 충남 금산에서 개최되는 금산세계인삼축제에서는 인삼캐기체험과 홍삼팩 마사지, 홍삼족욕, 국제인삼교역전, 전통인삼문화체험 등 온 계층이 즐기는 다채로운 체험과 볼거리, 알뜰 쇼핑으로 관광객 만족도를 높여가고 있으며, 행사장 곳곳에서는 인삼과 약초를 활용한 건강 음식을 맛볼 수 있다. 1981년부터 매년 개최되어 온 금산세계인삼축제는 문화체육관광부가 선정하는 전국 최우수 축제 10회 지정의 경력과 2024년 세계축제협회(IFEA World) 아시아 특산물 축제 선정 등 명실공히 한국을 대표하는 산업형 축제로 숱한 명성을 쌓아오고 있으며, 세계인과 함께하는 글로벌 축제로 거듭나고 있다.', null, '041-750-2316', 'open', 'info', 'approved', 'TourAPI', 'www.insamfestival.co.kr', '506465', 36.1001535022, 127.5005221346, now()),
    (gen_random_uuid(), adm, '금정산성축제', '축제', '금정산성축제', '2026-10-16', '2026-10-18', '부산', '부산광역시 금정구 산성로 501-2 (금성동)', null, null, 0, 0, null, false, false, false, false, '2026년 국립공원으로 새롭게 지정된 금정산의 가치를 담은 2026 금정산성축제가 오는 10월 16일(금)부터 10월 18일(일)까지 3일간 금정산성광장 및 금정산성 일원에서 개최된다. 부산광역시 금정구의 대표 문화유산이자 대한민국 최대 규모의 산성인 금정산성과 국립공원 금정산을 바탕으로 하는 역사·문화·예술축제로, 매년 금정산성 축성을 기념하기 위해 개최된다. 1996년 금정예술제를 시작으로 이어져 온 금정산성축제는 올해 국립공원 금정산의 생태·자연과 금정산성의 역사·문화가 어우러진 다양한 프로그램을 통해 금정의 새로운 매력을 선보인다.', null, '051-715-6884', 'open', 'info', 'approved', 'TourAPI', 'https://www.gjfac.org/', '1275743', 35.2452812589, 129.0570297348, now()),
    (gen_random_uuid(), adm, '금천시흥행궁문화제', '축제', '금천시흥행궁문화제', '2026-10-04', '2026-10-04', '서울', '서울특별시 금천구 은행나무로 44 (시흥동)', null, null, 0, 0, null, false, false, false, false, '''금천시흥행궁문화제''는 금천구의 역사적 정체성과 문화예술적 의미를 담은 금천구 대표 역사문화축제이다. [2026 금천시흥행궁문화제]는 왕의 행렬을 기다리는 주민들의 들뜬 마음을 표현한 1부 ''행행잔치''를 시작으로, 2부에서는 정조대왕이 아버지 사도세자의 능에 참배하러 가는 행차의 모습을 서울시와 연계해 ''정조대왕 능행차 행렬'' 선보인다. 마지막 3부에서는 정조의 애민정신에 부합하는 ''모두가 함께 즐기는 국악''으로 구성될 ‘금천시흥행궁문화제’만의 특화콘텐츠 ''시흥행궁night''까지 다채로운 프로그램으로 주민들이 모두 함께 즐길 수 있는 축제이다.', null, '070-4114-6352', 'open', 'info', 'approved', 'TourAPI', null, '4099989', 37.4506976783, 126.9074454056, now()),
    (gen_random_uuid(), adm, '금천하모니축제', '축제', '금천하모니축제', '2026-10-17', '2026-10-17', '서울', '서울특별시 금천구 시흥대로73길 70 (시흥동)', null, null, 0, 0, null, false, false, false, false, '금천하모니축제는 2003년부터 시작해 20년 넘게 매해 열리는 금천구 대표 축제이다. 올해는 ''울림의 하모니, 마음을 잇는 멜로디''라는 슬로건을 가지고 ''음악''을 소재로 주민들이 쉬고 즐기고 화합하는 축제의 장을 마련하고자 한다. 금천구청을 중심으로 금나래중앙공원, 구청 앞 광장 등을 축제 장소로 활용하여 주민들이 직접 목소리를 모아 아름다운 멜로디를 만드는 시민참여 쇼콰이어 ''싱 포 하모니''부터 신나는 음악 공연, 다채로운 체험 부스, 감성 가득한 플리마켓, 그리고 맛있는 푸드트럭까지 주민들이 즐기고 참여할수 있는 콘텐츠로 구성될 예정이다.', null, '070-4118-3420', 'open', 'info', 'approved', 'TourAPI', null, '2761411', 37.4564406598, 126.8955073340, now()),
    (gen_random_uuid(), adm, '기장군반려동물문화축제', '축제', '기장군반려동물문화축제', '2026-09-19', '2026-09-19', '부산', '부산광역시 기장군 정관읍 구연3로 27', null, null, 0, 0, null, false, false, false, false, '2026 기장군 반려동물문화축제는 반려동물과 보호자, 그리고 지역 주민이 함께 어우러지는 소통과 화합의 축제이다. 올해로 세 번째를 맞이하는 이번 축제는 ‘반려동물과 함께하는 행복한 공존’​을 주제로 더욱 풍성하고 다채로운 프로그램을 마련해 반려인과 비반려인이 함께 즐기며 올바른 반려문화를 배우고 공감할 수 있는 특별한 시간을 선사한다. 특히 올해는 반려동물과 보호자가 함께 걷고 교감하는 ‘반려동물 동반 걷기대회’​를 비롯해, 전국의 재능 있는 댕냥이들이 한자리에 모여 숨겨진 끼와 재주를 마음껏 펼치는 ‘K-Pet 갓 텔런트’ 등 새롭고 흥미로운 펫 프로그램을 선보인다. 이와 함께 다양한 체험·교육·참여 프로그램을 통해 반려동물과 함께하는 즐거움은 물론, 생명 존중과 책임 있는 반려문화의 의미도 함께 나눌 예정이다. 축제가 열리는 기장군은 사람과 동물이 함께 행복한 지역사회를 만들기 위해 반려동물 문화 확산과 동물복지 증진을 위한 다양한 노력을 이어가고 있다. 이번 축제 역시 반려동물과 보호자가 함께 참여하고 즐길 수 있는 프로그램을 통해 성숙한 반려문화 정착과 지역사회 구성원 간의 소통과 공존을 목표로 한다.', null, '010-3880-4966', 'open', 'info', 'approved', 'TourAPI', null, '3493864', 35.3221879870, 129.1818960826, now()),
    (gen_random_uuid(), adm, '김제지평선축제', '축제', '김제지평선축제', '2026-10-01', '2026-10-05', '전북', '전북특별자치도 김제시 부량면 벽골제로 442', null, null, 0, 0, null, false, false, false, false, '*하기 축제장 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 문화체육관광부가 지정한 대한민국 명예대표 문화관광축제중 유일하게 전통농경문화를 주제로 개최하는 김제지평선축제는 우리나라 최고(最古)· 최대(最大) 수리시설인 벽골제를 중심으로 펼쳐진다. 드넓은 황금 들판과 지평선을 배경으로 개최되는 전국 최초 대통령배 전국 농악경연대회를 비롯한 다양한 볼거리와 아궁이 쌀밥 짓기, 메뚜기 잡기, 벼 베기, 탈곡 체험 등 각종 농경문화를 직접 체험할 수 있는 프로그램이 마련되어 있다. 이와 함께 벽골제 전설을 바탕으로 한 쌍룡놀이와 풍년을 기원하는 입석 줄다리기 등 전통 민속행사도 현장에서 직접 참여할 수 있어 축제의 즐거움을 더한다.', null, '063-540-3172', 'open', 'info', 'approved', 'TourAPI', 'http://festival.gimje.go.kr/', '574285', 35.7540218787, 126.8522718951, now()),
    (gen_random_uuid(), adm, '김천김밥축제', '축제', '김천김밥축제', '2026-10-23', '2026-10-25', '경북', '경상북도 김천시 대항면 황악로 1189-52', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*김천김밥축제는 경상북도 김천시에서 개최되는 지역 문화관광 축제이다. 김천의 대표적인 특산품이 김밥은 아니지만, ‘김밥천국 김천’이라는 지역의 상징적 이미지를 기반으로 기획된 행사이다. 축제는 김천 시민과 관광객이 함께 즐길 수 있도록 김밥을 소재로 한 체험, 전시, 공연, 놀이 콘텐츠를 중심으로 운영된다. 김밥을 직접 만들고 맛보는 체험 프로그램이 마련되며, 다양한 세대가 참여할 수 있는 공연과 체험존이 조성된다.', null, '053-965-0910', 'open', 'info', 'approved', 'TourAPI', 'http://gimbapcity.kr/main/main.html', '3377995', 36.102930074676955, 127.99484429506171, now()),
    (gen_random_uuid(), adm, '김해 국가유산야행', '축제', '김해 국가유산야행', '2026-10-16', '2026-10-18', '경남', '경상남도 김해시 가락로93번길 26', null, null, 0, 0, null, false, false, false, false, '김해국가유산야행은 가야의 숨결이 살아있는 대성동고분군, 수로왕릉, 수릉원 일원을 무대로 펼쳐지는 야간 체류형 문화축제로, 야경·공연·체험·먹거리로 ‘빛과 역사를’ 함께 즐기는 행사이다. 가야의 숨결이 닿아 있는 문화유산에서 역사 이야기를 따라 걷는 밤길과 더불어 익숙한 길을 걷는 즐거움을 함께 경험할 수 있다. ‘밤’을 주제로 한 8야(夜) 프로그램(야경·야로·야사·야화·야설·야식·야숙·야시)을 통해 방문객들은 김해의 찬란한 가야 역사와 문화유산을 색다르게 만나볼 수 있다. 각 프로그램은 공연, 전시, 체험, 먹거리, 야간 경관 등 다채로운 콘텐츠로 구성되어 있으며, 국가유산에 담긴 의미와 가치를 자연스럽게 느끼고 김해만의 역사·문화적 정체성을 직접 경험할 수 있는 특별한 시간을 제공한다.', null, '070-8824-0347', 'open', 'info', 'approved', 'TourAPI', null, '2551117', 35.2348642516, 128.8772389826, now()),
    (gen_random_uuid(), adm, '김해분청도자기축제', '축제', '김해분청도자기축제', '2026-11-06', '2026-11-10', '경남', '경상남도 김해시 진례면 분청로 17', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 김해분청도자기축제는 조선 초기 분청사기의 본고장인 김해에서 열리는 대표적인 도자기 축제로, 전통과 현대가 어우러진 문화예술의 장으로 자리매김하고 있다. 올해로 30회를 맞이한 김해분청도자기축제는 분청의 시간, 세종을 만나다 라는 슬로건 아래, 김해 분청도자기의 예술성과 실용성을 직접 체험하고 즐길 수 있는 다채로운 프로그램을 마련했다. 도예 명인들의 작품 전시, 도자기 빚기와 전통 가마 체험, 현대 도예와 융합한 창의적 작품전 등 관람객이 직접 보고 느끼며 참여할 수 있는 체험형 축제로 기획되었다. 어린이·가족 단위 체험 프로그램 등을 통해 남녀노소 누구나 함께 즐길 수 있는 축제가 될 것이다. 김해분청도자기축제는 김해시가 간직한 분청사기의 아름다움과 정신을 세계에 알리는 뜻깊은 문화행사로서, 도자문화의 전통을 보존하고 새로운 도자예술의 가능성을 열어가는 소중한 장이 될 것이다.', null, '055-330-3244', 'open', 'info', 'approved', 'TourAPI', 'http://festival.buncheong.co.kr/main.web', '506470', 35.2517277593, 128.7458798521, now()),
    (gen_random_uuid(), adm, '나오라쇼', '축제', '나오라쇼', '2026-04-25', '2026-10-31', '강원', '강원특별자치도 원주시 지정면 소금산길 12', null, null, 0, 0, null, false, false, false, false, '나오라쇼 - 나이트 오브 라이트(Night of Light Show)는 "간현에 나와 빛의 밤을 즐기자"라는 주제로 잔잔하게 흐르는 강물과 기암절벽이 어루러져 절경을 이루는 간현관광지에서 밤에 내리는 아름다운 조명과 신비한 이야기를 아름다운 음악과 즐기며 특별한 추억과 낭만이 가득한 밤을 즐길 수 있는 쇼이다. 버스킹, 악기 연주, 댄스 등으로 구성된 1부 ''Prologue : NAORA LIVE''는 공연 시작 전 현장 분위기를 고조시키는 도입 공연으로 진행되며, 2부 ''Finale : NAORA SHOW 2026''은 미디어파사드와 음악분수가 결합된 본 공연으로 화려한 야간 미디어아트를 선보인다. 미디어파사드는 가로 250m, 세로 70m 규모의 자연 암벽에 12대의 빔프로젝터와 7대의 레이저 장비를 활용하여 생동감 있는 영상을 구현하고, 음악분수는 최대 60m 높이까지 치솟는 물줄기와 다채로운 연출을 통해 관람객에게 몰입감 있는 야간 공연 경험을 제공한다.', null, '033-749-4860', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://cms.wfmc.kr/
공식 인스타그램 https://www.instagram.com/wfmc_ganhyeon/', '2766000', 37.36457643111233, 127.83403799313135, now()),
    (gen_random_uuid(), adm, '나주영산강축제', '축제', '나주영산강축제', '2026-10-07', '2026-10-11', '서울', '전남광주통합특별시 나주시 영산동', null, null, 0, 0, null, false, false, false, false, '2026 나주영산강축제는 10월 7일부터 11일까지 5일간 영산강정원 일원에서 개최되는 나주의 대표 가을축제이다. 드넓은 영산강과 아름다운 정원을 배경으로 나주의 역사·문화·관광자원을 한자리에서 만날 수 있는 화합의 장이다. 화려한 공연과 시민 참여 프로그램, 온 가족이 함께 즐기는 체험행사, 나주의 맛을 느낄 수 있는 다채로운 먹거리 등이 풍성하게 마련된 축제이다. 낮에는 가을 정원의 여유와 활기찬 프로그램을 즐기고, 밤에는 빛으로 물든 야간경관과 열정적인 공연을 감상할 수 있는 체류형 축제이다. 시민과 관광객이 함께 어우러져 특별한 추억을 만들고, 영산강의 생태적 가치와 나주만의 매력을 널리 알리는 문화관광축제이다.', null, '061-339-8594', 'open', 'info', 'approved', 'TourAPI', 'https://www.naju.go.kr/tour/festival/river', '3009344', 35.0012960000, 126.7222730000, now()),
    (gen_random_uuid(), adm, '남구청년예술제', '축제', '남구청년예술제', '2026-09-01', '2026-09-11', '대구', '대구광역시 남구 앞산순환로 478 (대명동)', null, null, 0, 0, null, false, false, false, false, '청년 예술인의 예술 활동을 지원하고 나아가 청년 문화예술 저변 확대를 위해 매년 9월 개최하는 「남구청년예술제」가 새로운 청년예술인들과 함께 돌아온다. 소규모 예술인을 위한 ''프린지 FESTA''는 오는 9월 1일(화)부터 9월 4일(금)까지 대구음악창작소 창공홀에서, 대규모 예술팀의 무대로 구성되는 ''청년예술제''는 9월 10일(목)과 9월 11일(금) 양일간 대덕문화전당 드림홀에서 펼쳐진다. 보다 많은 예술인 참여를 위해 지역내 예술인에 대한 참가 요강을 삭제하고 출연 예술인을 위한 실질적인 혜택을 더욱 강화한 [2026 남구 청년예술제]는 전석 무료로 5세 이상 입장 가능하다. 「2026 남구청년예술제」 의 전시 분야 예술 무대는 지역을 대표하는 예술대학인 계명대학교 미술대학, 동서대학교 미술학과, 부산대학교 미술학과 소속 104명의 청년 작가들이 함께 한다. 회화, 미디어, 시각 디자인, 공예 디자인, 웹툰 등 미술의 여러 장르를 아우를 「청년작가_ART CONNECT 」 는 오는 8월 18일(화)부터 9월 18일(금) 까지 대덕문화전당 제1~3전시실에서 무료 관람으로 펼쳐지며 매주 일요일 휴관 한다.', null, '053-664-3118', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://nam.daegu.kr/
공식 인스타그램 https://www.instagram.com/arti_daedeok/', '2748395', 35.8312933337, 128.5769703970, now()),
    (gen_random_uuid(), adm, '남산봉수의식 등 전통문화행사', '축제', '남산봉수의식 등 전통문화행사', '2026-01-01', '2026-12-31', '서울', '서울특별시 종로구 종로 54 (관철동)', null, null, 0, 0, null, false, false, false, false, '남산봉수의식 등 전통문화행사는 조선시대 통신수단을 재현하여 시민 및 국내외 관광객에게 우리 고유의 전통문화를 알리고 문화향유의 기회를 제공하는 서울시 주최 사업이다. 남산봉수대는 조선시대에 전국의 봉화대에서 올라오는 봉화를 최종적으로 집결해 상황을 도성에 알리는 중요한 통신수단이었다. 남산봉수대에서 남산봉수의식을 관람하며 역사 해설 안내를 들어볼 수 있다. 또한 매일 정오에 타종하는 보신각 시민상설 타종행사는 시민 및 관광객들과 함께하는 참여형 행사이다. 서울 남산타워 팔각정 광장에서 사물놀이 공연 및 전통무예시범을 관람할 수 있다. 이외에도 일일 경점관체험, 일일 봉수꾼 체험과 같은 체험 프로그램도 마련되어있다.', null, '행사장 02-319-1220운영사 02-737-6444', 'open', 'info', 'approved', 'TourAPI', 'https://namsanbongsu.kr/', '2809535', 37.5697673859634, 126.983677617361, now()),
    (gen_random_uuid(), adm, '달성가족문화축제 YES! 키즈존', '축제', '달성가족문화축제 YES! 키즈존', '2026-09-05', '2026-09-06', '대구', '대구광역시 달성군 유가읍 테크노대로6길 20', null, null, 0, 0, null, false, false, false, false, '지난 5월에 이어 온 가족이 함께 즐길 수 있는 달성군 대표 어린이 축제 ''YES! 키즈존'' 2회차가 개최된다. ''YES! 키즈존''은 가족 간의 유대 강화와 공동의 문화 경험을 제공하기 위해 기획된 가족문화축제로, 이번 2회차 행사는 달성군 각 권역에서 준비한 다양한 체험 프로그램과 지역 내에서 활동하는 공연팀의 무대로 지역민들의 장을 마련했다. 더불어 무대 프로그램에서는 빅벌룬쇼와 계면활성제 아저씨의 버블쇼, 그리고 크레용용의 폴로세움, 팀 퍼니스트의 코미디서커스 등 서커스 공연과 마술사 박주용의 마술 버블쇼, 마술사 문시호의 싸이언스 매직쇼 등 다채로운 장르의 공연으로 현장의 분위기를 띄울 예정이다. 또한 9월 5일에는 인기 크리에이터인 마술사 니키, 9월 6일에는 키즈유튜버 인싸가족이 특별 무대에 올라 생생한 무대 공연과 유쾌한 에너지로 현장의 열기를 한층 뜨겁게 달굴 예정이다.', null, '053-668-4273', 'open', 'info', 'approved', 'TourAPI', 'https://www.dsart.or.kr/', '3301281', 35.6862027968, 128.4664210807, now()),
    (gen_random_uuid(), adm, '대전 동구동락 축제', '축제', '대전 동구동락 축제', '2026-10-09', '2026-10-11', '대전', '대전광역시 동구 철갑2길 2 (소제동)', null, null, 0, 0, null, false, false, false, false, '교통의 중심지인 대전역 뒤편 동광장과 대동천 일원에서 펼쳐지는 대전 동구동락 축제는 도심과 자연이 어우러진 가을의 정취 속에서 즐길 수 있는 대전을 대표하는 문화관광축제이다. 이색적인 테마부스에서 맛보는 세계 음식부터 남녀노소 누구나 참여하고 즐길 수 있는 게임존 등 풍성한 콘텐츠로 가득하다. 특히 대동천의 자연을 배경으로 책과 휴식을 함께 즐기는 북크닉은 도심 속 여유와 낭만을 선사하며, 참가자들의 창의성과 실력을 엿볼 수 있는 베이커리 경연대회와 전문 셰프의 요리를 현장에서 만나볼 수 있는 쿠킹쇼는 축제에 특별한 미식 경험을 더한다. 관사촌, 소제동 카페거리 등 지역의 관광자원에 자연과 문화가 어우러진 이 축제에서는 대전 동구만의 고유한 감성과 매력을 온전히 느낄 수 있다.', null, '042-251-6673', 'open', 'info', 'approved', 'TourAPI', null, '3113001', 36.3349767742, 127.4373883609, now()),
    (gen_random_uuid(), adm, '대전 중구 북페스티벌', '축제', '대전 중구 북페스티벌', '2026-09-12', '2026-09-13', '대전', '대전광역시 중구 중앙로 85 (선화동)', null, null, 0, 0, null, false, false, false, false, '2026년 중구 북페스티벌은 2025년 축제에서 발견한 중구 안의 다양한 독서문화와 존재들을 바탕으로, 그 존재들을 서로 연결하고 도시 안의 관계를 확장하는 제2장을 연다. 제 2장 「서로의 연결」은 오랜 시간 이야기가 축적된 중구를 하나의 책처럼 읽어내는 축제이며, 골목에 쌓인 시간, 원도심에 남은 기억, 사람들의 삶, 지역이 품은 감정을 따라가며 중구 안에 이미 존재하는 이야기들을 새롭게 발견하고 연결한다. 이번 축제는 책을 매개로 사람과 사람, 장소와 기억, 도시와 독서문화를 잇는 장을 마련하며, 중구가 가진 이야기의 깊이와 독서문화의 가능성을 함께 나누는 시간으로 구성된다.', null, '042-825-6781', 'open', 'info', 'approved', 'TourAPI', null, '3532372', 36.3259454984, 127.4202942759, now()),
    (gen_random_uuid(), adm, '대한민국 청년의 날 축제', '축제', '대한민국 청년의 날 축제', '2026-09-18', '2026-09-20', '부산', '부산광역시 수영구 광안해변로 219 (광안동)', null, null, 0, 0, null, false, false, false, false, '대한민국 청년의 날은 사단법인 청년과미래의 제안과 주도로 시작된 청년 기념 행사에서 비롯된 법정기념일이다. 사단법인 청년과미래는 2016년부터 청년의 날을 법정기념일로 지정하기 위한 사회적 공감대를 확산하고 청년의 권익 증진에 대한 국민적 관심을 높이고자 매년 9월 청년의 날 기념행사를 개최하였으며, 2017년부터는 [대한민국 청년의 날 축제]를 공식 명칭으로 사용하여 대한민국을 대표하는 청년 축제로 발전시켜 왔다. 이후 2020년 1월 9일 청년의 날을 법정기념일로 지정하는 내용을 담은 ''청년기본법''이 국회 본회의를 통과하였고, 청년의 날은 매년 9월 셋째 주 토요일인 법정기념일로 지정되었다. 대한민국 청년의 날 축제는 법정기념일인 청년의 날의 의미를 널리 알리고 청년의 사회참여 확대와 권익 증진, 청년문화 활성화를 목적으로 개최되는 행사이다. 올해는 청년의 날 10주년을 맞아 대한민국 대표 관광지인 부산광역시 광안리 일원에서 제10회 대한민국 청년의 날 축제가 개최된다. 본 축제는 청년정책 홍보를 비롯해 문화·예술, 취·창업, 공연, 체험, 콘텐츠 산업 등 청년의 다양한 분야를 아우르는 프로그램을 운영하며, K-POP 콘서트, 대학가요제, 대한민국 청년드', null, '02-780-3939', 'open', 'info', 'approved', 'TourAPI', null, '2412052', 35.1537727634, 129.1185199725, now()),
    (gen_random_uuid(), adm, '덕수궁 밤의 석조전', '축제', '덕수궁 밤의 석조전', '2026-09-09', '2026-10-18', '서울', '서울특별시 중구 세종대로 99 (정동)', null, null, 0, 0, null, false, false, false, false, '[덕수궁 밤의 석조전]은 전문 해설사와 함께하는 ''석조전 야간 탐방''과 클래식 연주를 들으며 고종이 사랑했던 가배차(커피)와 디저트를 즐기는 ''테라스 카페 체험'', 대한제국 황실의 이야기를 담은 뮤지컬 공연 관람으로 구성되어 있는 덕수궁 야간 관람 프로그램이다. 2021년 시범 사업을 시작으로 높은 만족도와 호응에 힘입어 2022년 정식 개최되었으며, 2023년부터 반기별로 운영되고 있다. 궁인의 안내에 따라 대한제국 황실의 이야기를 품은 덕수궁 석조전으로 시간 여행을 떠나는 특별함을 경험하고, 개화기 소품을 활용한 ''인생궁컷'' 사진과 기념품을 통해 덕수궁 석조전에서의 밤을 오래 기억할 수 있는 복합 문화 체험 프로그램이다.', null, '1522-2295', 'open', 'info', 'approved', 'TourAPI', 'https://www.kh.or.kr/short/M3K4', '2756396', 37.5650549194, 126.9765746344, now()),
    (gen_random_uuid(), adm, '동대문구 맥주축제', '축제', '동대문구 맥주축제', '2026-08-28', '2026-08-29', '서울', '서울특별시 동대문구 장안동', null, null, 0, 0, null, false, false, false, false, '동대문구 맥주축제는 장안1수변공원에서 개최되는 대표적인 여름철 도심형 야외축제이다. 시원한 수변공간을 배경으로 다양한 수제맥주와 푸드트럭, 재즈 음악공연, 체험 프로그램, 영화 상영, 포토존 등을 운영하여 남녀노소 누구나 즐길 수 있는 문화축제로 자리매김하고 있다. 매년 8월 마지막 주에 개최되어 무더운 여름철 주민과 방문객에게 도심 속 휴식과 여가를 제공하며, 가족·친구·연인과 함께 특별한 추억을 만들 수 있는 공간을 조성한다. 또한, 다양한 문화예술 콘텐츠를 접할 수 있는 기회를 제공함으로써 동대문구를 대표하는 여름축제로서 지역의 문화적 매력과 브랜드 가치를 높이는 데 기여하고 있다.', null, '02-3291-5506', 'open', 'info', 'approved', 'TourAPI', 'https://www.ddmac.or.kr/', '3351268', 37.5665910000, 127.0753330000, now()),
    (gen_random_uuid(), adm, '동대문구 북 페스티벌', '축제', '동대문구 북 페스티벌', '2026-09-12', '2026-09-12', '서울', '서울특별시 동대문구 천호대로 145 (용두동)', null, null, 0, 0, null, false, false, false, false, '2026 동대문구 북 페스티벌은 9월 독서의 달을 맞이하여 주민의 독서에 대한 관심을 높이고 지역 독서 문화 진흥에 기여하기 위해 개최되는 독서문화 진흥 축제이다. 올해 축제는 ‘책력장-펼쳐라 책, 뛰어라 몸!’을 주제로 기존의 정적인 독서 활동을 넘어 책과 신체활동을 결합한 온 가족이 함께 즐길 수 있는 다양한 참여형 독서문화 프로그램이 펼쳐진다. 동대문구청 미래광장에서는 몸을 움직이며 책을 읽는 ''독서 피트니스'', 전래동화를 놀이로 즐겨보는 ''몸으로 읽는 책'', 독서와 사색을 함께 만끽할 수 있는 야외도서관 등이 운영된다. 다목적 강당에서는 동대문구 도서관 네트워크가 운영하는 ''책력 모험단'', ''도전! 도서관 미니 운동회'', ''독서력 건강검진'', ''답십리 모터스'' 등 다양한 부스 체험이 진행된다. 이외에도 어린이들의 눈높이에 맞춘 독서 장려 뮤지컬, 버블쇼, 버스킹 등 다양한 공연을 통해 관람객들에게 풍성한 볼거리와 즐길 거리를 제공한다.', null, '070-7742-8871', 'open', 'info', 'approved', 'TourAPI', 'https://www.l4d.or.kr/intro/index.do', '4098740', 37.5743917162, 127.0398965801, now()),
    (gen_random_uuid(), adm, '동래읍성역사축제', '축제', '동래읍성역사축제', '2026-10-16', '2026-10-18', '부산', '부산광역시 동래구 문화로 80 (명륜동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*동래읍성역사축제는 1995년 제1회 충렬제를 시작으로 31년 동안 이어져온 부산광역시 동래구의 대표적인 역사교육형 체험축제로, 올해는 ''동래성 사람들, 역사와 미래를 잇다!''라는 새로운 슬로건으로 개최된다. 2025년 제31회 동래읍성역사축제는 새로운 시작을 위해 대표프로그램인 동래성전투재현 실경뮤지컬을 더욱 업그레이드하여 미디어아트와 접목한 멋진 퍼포먼스를 제공할 예정이며, 야외방탈출, 몰입형영상체험관 등 새로운 콘텐츠를 추가하여 10월 24일부터 10월 26일까지 5개 분야 51개 프로그램으로 알차게 구성될 예정이다.', null, '051-550-4092', 'open', 'info', 'approved', 'TourAPI', 'https://www.dongnae.go.kr/festival/index.dongnae', '229048', 35.2120802836554, 129.09053553882106, now()),
    (gen_random_uuid(), adm, '명량대첩축제', '축제', '명량대첩축제', '2026-09-11', '2026-09-13', '서울', '전남광주통합특별시 진도군 군내면 명량대첩로 11', null, null, 0, 0, null, false, false, false, false, '명량대첩축제는 삼도수군통제사로 재임명된 이순신 장군의 조선수군과 전라도 어민이 1597년 9월 16일 울돌목에서 일본 수군을 물리친 세계사에서 유례없는 명량해전을 기념하는 호국 역사문화축제이다. 전라남도와 진도군, 해남군이 함께 2008년부터 매년 개최하는 지역 대표 역사문화축제로, 명량해전을 현대적으로 재현한 ICT 융복합 멀티미디어 해전과 해상 퍼레이드, 출정 퍼레이드, 지역 공연 등 다양한 프로그램을 운영하는 것이 특징이다. 또한 축제장 곳곳에 경관조명을 설치하고 역사와 문화를 체험할 수 있는 프로그램을 마련해 방문객에게 명량대첩의 역사적 현장을 직접 경험할 수 있는 기회를 제공한다. 이를 통해 명량대첩의 역사적 가치와 호국정신을 널리 알리고 진도와 해남의 역사·문화·관광자원을 함께 소개할 예정이다.', null, '061-802-2192', 'open', 'info', 'approved', 'TourAPI', 'https://www.mldc.kr/web/', '607417', 34.5690469324, 126.3034327394, now()),
    (gen_random_uuid(), adm, '목포항구축제', '축제', '목포항구축제', '2026-10-16', '2026-10-18', '서울', '전남광주통합특별시 목포시 삼학로92번길 6 (산정동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*목포는 1897년 개항하여 교역, 물류 교통의 중심지로서 과거 전국 3대항, 6대 도시의 영광을 누리면서, 지역경제의 부흥을 주도했으며 현재에는 서남해안의 배후 중심 도시이다. 목포항구축제는 설화가 공존하는 삼학도에서 항구 내음 가득한 목포항의 전통 파시(波市)를 전국에서 유일하게 축제로 재현하여 역사적인 가치를 널리 알린다. 또한 제철 수산물을 활용한 파시 경매, 경매 받은 수산물을 즉석해서 구워먹고 요리 해먹는 등 풍요로운 목포항의 낭만을 가득 담은 행사가 마련되어 있는 가을 축제이다.', null, '061-270-8441', 'open', 'info', 'approved', 'TourAPI', 'https://www.mokpo.go.kr/tour/festival/harbor', '574014', 34.7865334008, 126.3936724331, now()),
    (gen_random_uuid(), adm, '무안 황토 갯벌축제', '축제', '무안 황토 갯벌축제', '2026-08-29', '2026-09-06', '서울', '전남광주통합특별시 무안군 해제면 황토갯벌길 88', null, null, 0, 0, null, false, false, false, false, '무안황토갯벌축제는 ''갯벌이 살아있다''를 주제로 유네스코 세계유산인 무안갯벌에서 개최되는 생태체험 축제이다. 대한민국 최초 습지보호지역 제1호인 무안갯벌의 생태적 가치와 황토갯벌의 우수성을 널리 알리고, 자연과 사람이 공존하는 갯벌의 의미를 체험과 문화행사를 통해 전달하는 축제이다. 축제장인 무안황토갯벌랜드는 국내 최장 1.5km 해상보행목교인 무안갯벌탐방다리와 생태체험시설을 갖추고 있으며, 갯벌과 바다를 가까이에서 경험할 수 있는 생태관광지이다. 축제 기간에는 갯벌 생태를 주제로 한 체험과 문화행사, 전시, 공연 등이 운영되며, 가족 단위 방문객이 함께 참여할 수 있는 다양한 콘텐츠가 구성된다. 무안황토갯벌축제는 세계유산 무안갯벌의 보전 가치와 지역의 생태·문화자원을 연계하여 지속가능한 생태관광과 지역문화 활성화를 도모하는 축제이다.', null, '061-450-5473', 'open', 'info', 'approved', 'TourAPI', null, '1953493', 35.1022012699, 126.3336418836, now()),
    (gen_random_uuid(), adm, '무주반딧불축제', '축제', '무주반딧불축제', '2026-09-04', '2026-09-12', '전북', '전북특별자치도 무주군 무주읍 한풍루로 326-17', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*무주반딧불축제는 천연기념물인 반딧불이와 청정 자연환경을 테마로 한 대한민국 대표 환경축제이다. 매년 8월 말에서 9월 초경 무주군 일원에서 개최되며, 청정 자연 속에서 반딧불이가 뿜어내는 신비로운 불빛을 직접 관찰하며 자연의 소중함과 생태환경 보전의 가치를 느낄 수 있는 특별한 경험을 선사한다. 축제 기간에는 대표 프로그램인 ‘반딧불이 신비탐사’를 비롯해 다양한 생태·환경 체험과 전통문화 행사, 공연, 야간경관 등 다채로운 볼거리와 즐길 거리가 마련된다. 특히 반딧불이 신비탐사는 반딧불이 서식지를 직접 찾아가 자연 그대로의 빛을 만나는 무주만의 차별화된 프로그램으로, 방문객들에게 잊지 못할 추억을 선사한다. 무주반딧불축제는 자연과 인간이 공존하는 삶의 가치를 공유하며 환경보전의 중요성을 알리는 축제로 자리매김하고 있다.', null, '063-324-2440', 'open', 'info', 'approved', 'TourAPI', 'https://www.firefly.or.kr/', '506523', 36.0023418250, 127.6625749245, now()),
    (gen_random_uuid(), adm, '무창포 신비의바닷길축제', '축제', '무창포 신비의바닷길축제', '2026-09-11', '2026-09-13', '서울', '충남 보령시 웅천읍 관당리 805-4 일원', null, null, 0, 0, null, false, false, false, false, '약 1.5km의 갈라지는 바닷길을 배경으로 ‘바닷길 횃불체험’을 진행하며, 갯벌을 걸으며 바다의 신비를 느낄 수 있는 보령 대표 해양 축제이다. 바다 갈라짐에 맞춰 갯벌을 걷는 체험과 함께 다채로운 문화 프로그램이 운영된다. 낮에는 관람객이 함께 즐기는 마당극 공연과 직접 물고기를 잡는 맨손 물고기 잡기 등 다양한 가족 참여형 체험이 진행된다. 밤에는 화려한 공연과 더불어 축제의 하이라이트인 ''바닷길 LED 횃불체험''이 펼쳐져 밤바다를 밝히는 장관을 연출한다. 자연 현상의 신비로움과 다양한 해양 문화 체험을 한자리에서 즐길 수 있는 축제이다.', null, '041-930-0891', 'open', 'info', 'approved', 'TourAPI', 'https://mudfestival.or.kr/festival/event/list?level=2&menuNo=86', '1071143', 36.2426668000, 126.5357220000, now()),
    (gen_random_uuid(), adm, '문학주간2026 〈곁눈질〉', '축제', '문학주간2026 〈곁눈질〉', '2026-09-16', '2026-09-20', '서울', '서울특별시 종로구 대학로 104 (동숭동)', null, null, 0, 0, null, false, false, false, false, '문학주간은 문학에 대한 국민적 관심을 높이고, 문학 향유 분위기를 조성하여 한국문학 진흥의 기반을 다지기 위해 2016년부터 매년 개최되고 있다. 올해 문학주간은 ''곁눈질''이라는 주제로 문학과 문학 밖을 살펴보는 의미있는 시간을 마련하고자 한다. ''문학주간 2026''은 오는 9월 16일부터 20일까지 5일 간 마로니에 공원 일대에서 열리며, 다양한 주제를 담은 프로그램들로 구성될 예정이다.', null, '070-7954-1369', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://munhakweek.or.kr 
공식 인스타그램 https://www.instagram.com/munhak_week/', '2556687', 37.5805124610, 127.0023742293, now()),
    (gen_random_uuid(), adm, '문화가 흐르는 서울광장', '축제', '문화가 흐르는 서울광장', '2026-05-06', '2026-12-31', '서울', '서울특별시 중구 을지로 지하12 (을지로1가)', null, null, 0, 0, null, false, false, false, false, '일상 속 문화 향유 기회를 제공하는 이 5월부터 12월까지 약 8개월 간 서울광장에서 진행된다. 2026년 5월 6일 개막공연을 시작으로 대중가요부터 힙합, 재즈, 밴드, 퍼포먼스까지 다양한 장르의 공연이 매월 진행 될 예정이다.', null, '02-2133-2543', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://cultureseoul.co.kr', '2598331', 37.56544835496842, 126.97878183534239, now()),
    (gen_random_uuid(), adm, '백제문화제', '축제', '백제문화제', '2026-10-03', '2026-10-11', '충남', '충청남도 부여군 부여읍 정림로 83', null, null, 0, 0, null, false, false, false, false, '1955년 부여군에서 처음 개최된 제1회 백제대제를 출발점으로 한 백제문화제는 올해로 제72회를 맞이하는 대한민국 대표 역사문화축제이다. 백제의 찬란한 문화와 유구한 역사를 널리 알리고, 선조들의 정신과 문화유산을 현대적으로 계승·발전시키며 지역의 정체성과 자긍심을 높여 온 축제이다. 제72회 백제문화제는 2026년 10월 3일(토)부터 10월 11일(일)까지 9일간 ‘아름다운 백제, 빛나는 사비’를 주제로 부여 시가지 일원에서 개최된다. 정림사지와 석탑로, 관북리유적 등을 중심으로 제례·불전, 역사문화행렬, 공연, 전시, 체험, 야간경관 등 7개 분야 40여 개 프로그램을 선보인다. 특히 올해 축제의 무대를 부여 시가지에서 개최하여 백제의 역사문화와 지역 상권, 주민의 일상이 함께 어우러지는 열린 축제로 운영되며, 방문객에게 과거와 현재가 공존하는 특별한 문화 경험을 제공할 예정이다.', null, '041-837-2517', 'open', 'info', 'approved', 'TourAPI', 'https://www.baekjeculturalfestival.kr/', '952988', 36.2790252706, 126.9128806392, now()),
    (gen_random_uuid(), adm, '보은대추 축제', '축제', '보은대추 축제', '2026-10-16', '2026-10-25', '충북', '충청북도 보은군 보은읍 뱃들로 54', null, null, 0, 0, null, false, false, false, false, '올해로 20주년을 맞은 보은대추축제는 보은의 대표 특산물인 명품 보은대추와 청정 자연에서 생산된 농특산물을 한자리에서 만나볼 수 있는 대한민국 대표 농특산물 축제이다. 2025년 보은대추축제는 우수한 운영 성과를 인정받아 2026년 충청북도 지정축제 최우수축제로 선정되었으며, 2017년에 이어 3회 연속 충청북도 농특산물 판매활성화 최우수축제로 선정되는 등 전국적인 경쟁력을 인정받고 있다. 또한 임금님께 진상하였던 보은대추의 역사와 우수한 품질을 널리 알리며 보은을 대표하는 축제로 자리매김하고 있다. 축제 기간에는 대추 및 농특산물 판매장을 비롯해 온라인장터와 생대추 주문 콜센터를 운영하여 전국 어디서나 보은의 농특산물을 편리하게 구매할 수 있도록 지원한다. 또한 개막식과 폐막식을 비롯한 다양한 문화예술 공연과 체험 프로그램을 운영하여 방문객들에게 풍성한 볼거리와 즐길거리를 제공하고, 가족 단위 관광객부터 남녀노소 누구나 보은의 가을 정취를 만끽할 수 있도록 구성된다. 이와 함께 농업·문화·관광을 연계한 다채로운 프로그램을 통해 지역 농특산물의 우수성을 널리 알리고 관광객 유치와 지역경제 활성화를 도모하는 것은 물론, 보은의 가을 관광 브랜드 가치를 높이는 ', null, '043-540-3392', 'open', 'info', 'approved', 'TourAPI', 'https://www.boeunjujube.com/', '900168', 36.4869676010, 127.7234716104, now()),
    (gen_random_uuid(), adm, '보은회인 국가유산야행', '축제', '보은회인 국가유산야행', '2026-09-11', '2026-09-13', '충북', '충청북도 보은군 회인면 중앙리', null, null, 0, 0, null, false, false, false, false, '2026 보은 회인 국가유산 야행은 충청북도 보은군 회인면에 위치한 국가유산과 마을 공간을 야간에 관람하고 체험하는 지역 문화유산 행사이다. 피반령 도깨비가 회인 마을에 내려와 사람들을 신비로운 놀잇간으로 초대한다는 이야기를 중심으로 야경, 야로, 야설, 야사, 야화, 야시·야식, 야숙 프로그램을 운영하는 행사이다. 회인 인산객사, 동헌내아, 사직단, 회인향교, 풍림정사 등 지역의 역사 공간을 따라 현감행렬, 망궐례, 전기수 이야기 공연, 전통놀이, 붓글씨, 천연염색, 무형유산 시연과 체험이 이어지는 구성이다. 행사장 곳곳에는 국가유산을 활용한 야간 경관과 도깨비 캐릭터 연출, 달빛 스탬프 투어, 주민 참여 프로그램, 가족 체험 공간, 먹거리 공간, 꽃밭과 사진 촬영 공간이 조성되는 행사이다. 방문객이 회인의 역사와 생활문화를 직접 걸으며 경험하고 지역 주민과 함께 국가유산의 가치와 지역의 이야기를 공유하는 야간형 문화유산 축제이다.', null, '043-540-3407', 'open', 'info', 'approved', 'TourAPI', 'https://yahang.imweb.me/', '2858917', 36.4913994484, 127.5982973737, now()),
    (gen_random_uuid(), adm, '부산국제록페스티벌', '축제', '부산국제록페스티벌', '2026-10-02', '2026-10-04', '부산', '부산광역시 사상구 삼락동', null, null, 0, 0, null, false, false, false, false, '*하기 축제장 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*부산국제록페스티벌은 2000년 첫 개최 이래, 27년 동안 명맥을 꾸준히 지켜온 국내 최초·최장수 국제록페스티벌이다. 2026년에는 10월 2일(금)부터 10월 4일(일)까지 3일간, 삼락생태공원에서 개최되며, 다양한 국내외 아티스트가 참여할 예정이다. 삼락생태공원 곳곳에 조성된 무대에서 신진 아티스트부터 글로벌 최정상급 헤드라이너까지 취향에 따라 다양한 공연을 관람할 수 있으며, 무료 개방형 무대에서 진행되는 관람객 참여형 게임 이벤트와 노래자랑, 부산의 로컬 음식을 담은 푸드코트 라운지, 삼락 오토 캠핑존 등 다양한 부대 이벤트도 즐길 수 있다.', null, '051-713-5000', 'open', 'info', 'approved', 'TourAPI', 'https://busanrockfestival.com/', '140799', 35.1728573000, 128.9681914000, now()),
    (gen_random_uuid(), adm, '부산브릿지마라톤', '축제', '부산브릿지마라톤', '2026-12-06', '2026-12-06', '부산', '부산광역시 해운대구 APEC로 55 (우동)', null, null, 0, 0, null, false, false, false, false, '부산브릿지마라톤은 아름다운 해양 도시 부산의 매력을 만끽할 수 있는 러닝 축제이다. 행사 집결지는 부산의 랜드마크인 벡스코 제1전시장이며, 전국의 러너들이 모여 활기찬 열기를 나누는 화합의 장이다. 대회 종목은 자신의 체력과 목표에 맞추어 선택할 수 있도록 구성되어 있다. 자신의 한계에 도전하는 풀코스와 누구나 건강하게 즐길 수 있는 10㎞로 운영된다. 특히 풀코스의 경우, 안전하고 내실 있는 대회를 위해 타 대회 공식 기록증 기준 4시간 30분 이내의 완주 기록을 소지해야하며 10㎞ 코스는 만 18세 이상의 건강한 남녀라면 누구나 참여할 수 있다.', null, '070-4111-5620', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://busanmarathon.com/
