    (gen_random_uuid(), adm, '부천국제만화축제', '축제', '부천국제만화축제', '2026-09-18', '2026-09-20', '경기', '경기도 부천시 원미구 길주로 1 (상동)', null, null, 0, 0, null, false, false, false, false, '2026년, 제29회를 맞이하는 부천국제만화축제는 만화를 사랑하는 누구나 즐길 수 있는 대한민국 만화전문 대표 문화관광축제이다. 올해는 “만화·웹툰 만만합니다” 라는 주제로 풍성한 즐길거리를 통한 관람 만족도를 높이기 위해 다채로운 만화 콘텐츠 프로그램과 문화체험을 제공하고 언제 어디서나 즐길 수 있는 축제이다. 기획·특별전을 비롯해 만화 마니아 행사인 작가와의 만남 프로그램, 다양한 체험의 장을 경험할 수 있는 플레이그라운드와 야외마켓부스, 전 세계 14개국 코스어가 참여하는 국제코스프레챔피언십까지 경험할 수 있는 축제의 장이다.', null, '032-310-3071', 'open', 'info', 'approved', 'TourAPI', null, '589386', 37.5081987483, 126.7421932715, now()),
    (gen_random_uuid(), adm, '부평풍물대축제', '축제', '부평풍물대축제', '2026-10-02', '2026-10-04', '인천', '인천광역시 부평구 부평대로 34-1 (부평동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 제30회 부평풍물대축제는 도심 속에서 울려 퍼지는 서른 번째 신명과 화합의 장이다. 인천을 넘어 대한민국을 대표하는 전통문화 예술 축제인 부평풍물대축제가 어느덧 뜻깊은 30주년을 맞이했다. 1997년 첫발을 내디딘 이래, 부평풍물대축제는 삭막한 도심 한복판에 우리 고유의 전통장단을 불어넣으며 시민과 예술인이 하나 되는 거대한 소통의 장으로 성장해 왔다. 축제의 핵심인 22개 동풍물단이 만들어내는 신명 나는 장단은 구민 모두를 하나로 연결하는 축제의 든든한 근간이 되어왔다. 특히 2026년 10월 2일부터 4일까지 3일간 열리는 이번 제30회 축제는 지난 30년간 이어온 전통의 맥을 되짚어보고, 앞으로 다가올 새로운 미래를 축하하는 특별한 의미를 담아 그 어느 때보다 거대하고 화려한 규모로 펼쳐진다. 또한 부평 도시 재생의 상징인 굴포천 일대까지 축제 공간을 확장하여 새롭고 다채로운 콘텐츠를 선보일 예정이다.', null, '032-509-7516', 'open', 'info', 'approved', 'TourAPI', 'https://portal.icbp.go.kr/bpf/', '1266642', 37.4944181127, 126.7229954336, now()),
    (gen_random_uuid(), adm, '사천시 삼천포항 자연산 전어축제', '축제', '사천시 삼천포항 자연산 전어축제', '2026-08-20', '2026-08-23', '경남', '경상남도 사천시 팔포3길 56-35 (동금동)', null, null, 0, 0, null, false, false, false, false, '사천시 삼천포항 자연산 전어축제는 사천시 삼천포항의 대표 수산물인 전어를 주제로 개최하는 먹거리 축제로서 외래 관광객 및 시민들의 지속적인 관심과 사랑을 받아 전국적인 먹거리 축제로 성장·발전하고 있으며 현재 제23회까지 개최하게 되었다. 금년 2026년에 제23회 사천시 삼천포항 자연산 전어축제라는 타이틀로 전어 풍어기에 맞추어서 명성 높은 사천시 전어 맛을 전국에 알리고, 또한 지역 어민 및 수산업과 수산 관련업에 종사하시는 시민들의 소득증대와 더 나아가 깨끗한 청정해역 사천시와 사천시의 수산물을 알리고자 전어축제를 개최하고자 한다.', null, '055-832-8565', 'open', 'info', 'approved', 'TourAPI', 'http://www.3004palpo.co.kr', '1068150', 34.9273831672, 128.0788862920, now()),
    (gen_random_uuid(), adm, '사천에어쇼', '축제', '사천에어쇼', '2026-10-22', '2026-10-25', '경남', '경상남도 사천시 사천읍 정의리', null, null, 0, 0, null, false, false, false, false, '"사천에어쇼" 는 남부권 최대 규모의 에어쇼이자 우주항공축제이다. 우주항공청 개청 이후 대한민국 우주항공수도로서의 위상을 강화하고 있는 사천시의 우주항공 생태계 속에서, 2026사천에어쇼가 비행과 체험 중심의 시민 축제를 넘어 우주항공방위산업전으로서의 도약을 선보인다.2026년 10월 22일(목)부터 25일(일)까지 4일간 사천비행장 일원에서 개최되며, 에어쇼 / 우주항공방위산업전 / 항공기·장비 전시 / 우주항공·군사장비 체험 / 학술회의 / 체험비행 / 우주항공 관련 대회 등 B2C·B2B·B2G를 아우르는 다양한 메인프로그램과 부대행사를 만날 수 있다.', null, '055-831-2061', 'open', 'info', 'approved', 'TourAPI', 'http://airshow.sacheon.go.kr', '234232', 35.0911816485, 128.0699132182, now()),
    (gen_random_uuid(), adm, '산청한방약초축제', '축제', '산청한방약초축제', '2026-10-02', '2026-10-11', '경남', '경상남도 산청군 금서면 동의보감로555번길 45-6', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*제25회를 맞이한 대한민국 대표 약초축제이다. 지리산 청정지역의 약초자원과 소설 동의보감을 기반으로, 2001년 전국최초의 한의약 테마관광지 조성 등 역사와 문화, 자연 조건을 최대한 활용하여 축제를 통해 산청한방약초의 우수성을 홍보하고 현대인들의 최대 관심사인 웰니스, 항노화 관련 산업을 연계한 산업형 축제이다. 산청의 우수한 약초의 효능을 직접 체험해 보는 산청한약방체험, 내몸의 보약체험, 웰니스헬스투어 등이 준비되어 있다.', null, '055-970-6670', 'open', 'info', 'approved', 'TourAPI', '홈페이지 http://scherb.or.kr/', '506600', 35.44106596986498, 127.82935943935597, now()),
    (gen_random_uuid(), adm, '삼토 페스티벌', '축제', '삼토 페스티벌', '2026-09-11', '2026-09-13', '강원', '강원특별자치도 원주시 서원대로 311 (명륜동)', null, null, 0, 0, null, false, false, false, false, '원주삼토페스티벌은 원주의 농업과 농촌문화를 시민과 함께 즐기기 위해 마련된 지역 대표 축제이다. 축제는 지역에서 생산된 우수한 농특산물을 소개하고, 농업의 가치를 알리며, 다양한 체험과 공연을 통해 남녀노소 누구나 참여할 수 있는 장을 마련한다. 농산물 직거래 장터에서는 신선한 먹거리를 직접 구입할 수 있으며, 가족 단위 방문객을 위한 농촌 체험 프로그램이 운영된다. 또한 지역 예술 공연과 어울린 무대 행사가 마련되어 풍성한 볼거리를 제공한다. 삼토페스티벌은 농업인과 시민이 함께 어울리고 교류하는 축제의 장으로, 원주의 농업 정체성과 문화를 널리 알리는 역할을 하고 있다.', null, '033-737-4155', 'open', 'info', 'approved', 'TourAPI', 'https://www.3to.kr/', '1409287', 37.3368480903, 127.9436723245, now()),
    (gen_random_uuid(), adm, '새연교 주말 문화공연 ''금토금토 새연쇼''', '축제', '새연교 주말 문화공연 ''금토금토 새연쇼''', '2026-04-25', '2026-10-31', '제주', '제주특별자치도 서귀포시 남성중로 40 (서홍동)', null, null, 0, 0, null, false, false, false, false, '새연교 주말공연 ‘금토금토 새연쇼’는 서귀포시 천혜의 자연경관과 문화체험을 접목한 독창적인 야간관광 프로그램이다. 화려한 조명 아래 음악, 댄스, 퍼포먼스 등 다양한 장르의 공연이 관객들을 맞이하며, 공연이 끝난 뒤에는 푸른 바다와 야경을 배경으로 환상적인 불꽃쇼가 이어져 서귀포의 밤을 더욱 빛내준다. 4월 25일을 시작으로 매주 금요일과 토요일 저녁 7시에 진행되며 10월 까지 이어진다. 아름다운 새연교 경관을 배경으로 다채로운 문화 콘텐츠 및 불꽃쇼, 음악분수쇼를 함께 즐길 수 있고 새섬 속 야간 조명 아래 산책하는 것도 추천하는 콘텐츠이다. ※ 기상 상황 등에 따라 일정 및 프로그램이 변동 될 수 있습니다.', null, '064-760-2654', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/seogwipo_tourism/', '2434545', 33.239201142544914, 126.5584238742126, now()),
    (gen_random_uuid(), adm, '새활용 페스티벌', '축제', '새활용 페스티벌', '2026-09-04', '2026-09-06', '서울', '서울특별시 성동구 자동차시장길 49 (용답동)', null, null, 0, 0, null, false, false, false, false, '새활용페스티벌은 자원순환과 새활용 문화 확산을 목적으로 개최되는 환경문화축제이다. 새활용의 가치와 지속가능한 생활방식을 시민에게 알리고, 다양한 체험과 전시, 공연, 참여 프로그램을 통해 자원순환에 대한 공감대를 형성하는 행사이다. 축제는 새활용 마켓, 수리(리페어) 프로그램, 업사이클링 체험, 전시, 공연, 피크닉 공간 등 다양한 콘텐츠로 구성되어 연령과 계층에 관계없이 참여할 수 있는 복합 문화행사이다. 또한 새활용 기업과 기관, 창작자, 시민이 함께 참여하는 교류의 장을 마련하여 새활용 산업과 문화의 활성화를 도모하는 행사이다. 현장에서는 시민 참여형 이벤트와 체험 프로그램을 운영하여 자원순환 실천을 유도하며, 친환경 축제 운영 방식을 적용하여 지속가능한 축제 모델을 구현하는 것을 목표로 하는 행사이다.', null, '070-4289-5542', 'open', 'info', 'approved', 'TourAPI', 'https://www.seoulup.or.kr/', '3348418', 37.5586120945, 127.0578225987, now()),
    (gen_random_uuid(), adm, '생생우리음악축제', '축제', '생생우리음악축제', '2026-08-28', '2026-08-30', '경기', '경기도 화성시 효행구 봉담읍 동화새터길 133', null, null, 0, 0, null, false, false, false, false, '2026 The 9th 생생우리음악축제, 대한민국 우수 공연예술제로 전국 120여개 지원 팀 중 선발된 최고의 우리음악 아티스트와 함께하며, 경기도 화성시 봉담읍 문화 거점 공간에서 펼쳐지는 ''라이브&언플러그드'' 우리음악 기반 공연으로 3일간 봉담지역 약 10여곳에서 진행된다.', null, '031-236-7103', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.yulteo.kr/', '2853756', 37.2152816297, 126.9626937088, now()),
    (gen_random_uuid(), adm, '서귀포칠십리축제', '축제', '서귀포칠십리축제', '2026-10-23', '2026-10-25', '제주', '제주특별자치도 서귀포시 서홍동', null, null, 0, 0, null, false, false, false, false, '서귀포 칠십리축제는 서귀포의 원도심과 바다를 배경으로, 지역 문화예술과 시민 참여 프로그램을 한데 모아 즐기는 서귀포 대표 축제이다. 보통 천지연폭포 주차장 및 서귀포 원도심(구 시가지) 일대에서 진행되며, 거리 전체가 무대가 되는 거리 퍼레이드, 다양한 장르의 공연·버스킹, 지역 예술인 참여 무대, 먹거리·플리마켓 등으로 축제 분위기를 더한다. 특히 퍼레이드는 시민과 단체가 함께 참여해 서귀포의 정체성과 활기를 보여주는 핵심 프로그램으로, 축제 기간 원도심 일대를 걸으며 볼거리와 즐길 거리를 동시에 체험할 수 있다는 점이 특징이다. 이 축제는 과거와 현재, 미래가 만나는 무대이자 시민과 관객이 하나 되어 즐기는 신명나는 축제이다. 자연과 문화, 사람이 어우러진 서귀포 칠십리축제에서 특별한 추억을 만들 수 있다.', null, '064-760-3942', 'open', 'info', 'approved', 'TourAPI', 'https://www.seogwipo.go.kr/tourismculture/destination/festival/70ri.htm', '506616', 33.243863, 126.560563, now()),
    (gen_random_uuid(), adm, '서리풀뮤직페스티벌', '축제', '서리풀뮤직페스티벌', '2026-09-19', '2026-09-20', '서울', '서울특별시 서초구 서초대로 233 서초역', null, null, 0, 0, null, false, false, false, false, '서리풀뮤직페스티벌은 매년 9월 개최되는 도심 속 음악 축제로, 2015년 첫선을 보인 후 지난 2025년까지 누적 134만여 명이 찾으며 서초구를 대표하는 브랜드 축제로 확실히 자리매김했다. 일 년에 단 이틀, 10차선 반포대로를 무대로 다채로운 장르의 공연과 감동적인 시민 참여 프로그램을 선보이며 한층 더 풍성하고 확장된 축제로 도약하고 있다. 특히 올해는 ‘Seocho is the Music’이라는 주제 아래 반포대로 본행사를 비롯해, 8월 말부터 한 달 동안 서초구 전역을 아름다운 선율로 물들이는 ‘4주간의 음악 여정’을 통해 더욱 특별한 감동으로 관람객을 맞이한다.', null, '02-3477-2808', 'open', 'info', 'approved', 'TourAPI', 'https://seoripul.org/', '2759788', 37.4918235233, 127.0075934663, now()),
    (gen_random_uuid(), adm, '서산해미읍성축제', '축제', '서산해미읍성축제', '2026-10-09', '2026-10-11', '충남', '충청남도 서산시 해미면 남문2로 143', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*축성 600년의 세월을 간직한 국가유산, 서산 해미읍성. 그 깊은 역사와 전통 위에 오늘의 감성을 더해, 제22회 서산해미읍성축제가 새로운 이야기로 펼쳐진다. 이번 축제는 ‘지혜’를 주제로, 선조들의 슬기로운 삶과 문화를 현대적으로 재해석한 다채로운 공연과 체험 콘텐츠를 선보인다. 세대를 아우르는 문화예술 공연과 클래식 음악, 해미읍성을 수놓을 미디어아트까지— 과거와 현재, 미래를 잇는 색다른 경험이 서산 해미읍성 곳곳에서 펼쳐진다. 어린이부터 어르신까지 3일간 모두가 함께 즐길 수 있는 풍성한 가을 축제이다.', null, '041-660-2696', 'open', 'info', 'approved', 'TourAPI', 'http://www.haemifest.com/', '140752', 36.71355657908334, 126.55038368933553, now()),
    (gen_random_uuid(), adm, '서울 왕궁수문장 교대의식', '축제', '서울 왕궁수문장 교대의식', '2026-01-01', '2026-12-31', '서울', '서울특별시 중구 세종대로 99 (정동)', null, null, 0, 0, null, false, false, false, false, '‘서울 왕궁수문장 교대의식’은 서울시가 주최하는 대표적인 전통문화재현 행사로, 조선시대 궁궐 문을 지키던 수문군의 교대 장면을 실감 나게 되살린 프로그램이다. 수문장은 종6품의 관직으로, 수문장청 소속 참하와 수문군과 함께 궁문을 지키고, 출입을 단속하며 순찰을 수행했다. 교대의식은 실제 역사자료에 근거해 구성되었으며, 조선 후기 덕수궁을 중심으로 전개된다. 행사는 매주 월요일을 제외한 주 6일, 오전 11시와 오후 2시에 덕수궁 대한문 앞에서 열린다. 일반 시민과 외국인 관광객의 흥미를 더하기 위해 다양한 체험 프로그램도 함께 운영되는데, ‘개식타고 체험’은 북을 직접 두드리며 의식 시작을 알리는 체험이고, ‘나도 수문장’은 수문장 복장을 입고 역할을 체험하는 프로그램이며, ‘전통복식 체험’은 조선시대 의상을 입고 사진을 남길 수 있는 인기 체험이다.', null, '02-6242-7402', 'open', 'info', 'approved', 'TourAPI', 'http://www.royalguard.kr', '292961', 37.565054919430565, 126.97657463444833, now()),
    (gen_random_uuid(), adm, '서울국제작가축제', '축제', '서울국제작가축제', '2026-09-11', '2026-09-16', '서울', '서울특별시 종로구 인사동9길 26 (견지동)', null, null, 0, 0, null, false, false, false, false, '서울국제작가축제는 한국문학과 세계문학의 교류를 위해 2006년부터 이어온 글로벌 문학 축제이다. 올해로 15회를 맞이하는 2026 서울국제작가축제는 작가, 독자, 그리고 다양한 언어와 이야기가 한자리에서 만나는 특별한 자리를 만들었다. 국내 작가는 물론, 평소 쉽게 접하기 어려운 해외 작가들과 함께 대담, 워크숍, 전시 등 풍성한 프로그램을 통해 문학을 더욱 가깝게 경험할 수 있다. 책과 사람, 언어와 감정이 교차하는 축제의 현장에서 ''누구세요?''라는 물음 아래 오직 사람과 사람 사이에서만 가능한 문학의 깊은 경험을 할 수 있는 축제이다.', null, '02-6339-1232', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.siwf.or.kr
공식 인스타그램 https://www.instagram.com/siwf_insta/', '1018469', 37.5734199329, 126.9836265705, now()),
    (gen_random_uuid(), adm, '서울어텀페스타 개막행사', '축제', '서울어텀페스타 개막행사', '2026-09-18', '2026-09-18', '서울', '서울특별 광진구 자양동 704-1', null, null, 0, 0, null, false, false, false, false, '서울어텀페스타는 서울의 가을을 공연예술로 엮는 계절 브랜드이다. 9월 18일부터 11월 29일까지, 73일간 이어지는 공식 시즌에는 크고 작은 축제와 개별 공연이 한자리에 모여, 서울 전역을 예술로 물들이는 무대를 만든다. 총 약 200편의 연극·무용·음악·전통예술 공연이 전 시즌에 걸쳐 펼쳐지며, 시민은 가을의 시작부터 끝까지 공연예술과 함께하는 특별한 여정을 경험할 수 있다. 오는 9월 18일 서울 전역을 무대로 펼쳐질 2026 서울어텀페스타의 서막을 여는 개막공연이 열리며 이번 개막공연은 단순한 축하 자리가 아니라 서울의 가을을 공연예술로 정의하고 ‘공연예술 중심도시 서울’을 선언하는 뜻깊은 무대이다. : 더 쉽게, 더 가깝게 공연을 만나는 곳 축제 기간동안 시민과 관광객이 서울 곳곳의 공연과 축제를 한눈에 살펴보고, 취향에 맞는 공연을 발견할 수 있도록 온라인과 현장을 연결하는 통합안내플랫폼 - 장소 : 서울문화재단 대학로센터 1층 - 기간 : 2026.09.01(화)~2026.11.29(일) ※ 매주 월요일 / 공휴일 휴관 - 운영 프로그램 : 취향기반 공연·축제 정보 제공 키오스크, 현장 참여 이벤트, 공연 연계 프로그램 등', null, '02-758-2037', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.sfac.or.kr/seoulautumnfesta/
공식 인스타그램 https://www.instagram.com/seoulautumnfesta/', '3544886', 37.5284392683, 127.0696398632, now()),
    (gen_random_uuid(), adm, '서울프린지페스티벌2026', '축제', '서울프린지페스티벌2026', '2026-08-06', '2026-08-23', '서울', '서울특별시 마포구 월드컵북로 94 (성산동)', null, null, 0, 0, null, false, false, false, false, '1998년, 대학로에서 ''독립예술제''라는 이름으로 시작된 서울프린지페스티벌은 매년 여름, 연극, 무용, 음악, 퍼포먼스, 영상, 시각예술, 전시 그리고 하나의 장르로는 설명 할 수 없는 다양한 예술적 실험들이 모이는 축제이다. 예술가에 대한 심사도, 작품에 대한 성정도 하지 않는다. ''누구나 예술가가 될 수 있다''고 믿으며 모두에게 참여의 기회를 열어둔다. 무대든, 공원이든, 그 어떤 공간에서든 하고 싶은 이야기를 표현하고, 시도할 수 있도록 지지하고 응원한다. 자신을 드러내는 용기, 장르의 경계를 넘나드는 실험, 책임과 존중을 나누는 과정 속에서 우리는 진정한 예술의 자유를 만들어간다. 올해는 ''우리가 함께 한다는 것''을 슬로건으로 내세우며, 지금 우리에게 필요한 새로운 연결의 방식을 발견하고자 한다.', null, '070-7092-8172', 'open', 'info', 'approved', 'TourAPI', 'www.seoulfringefestival.net', '142193', 37.5620373293, 126.9150631652, now()),
    (gen_random_uuid(), adm, '서천 국가유산야행', '축제', '서천 국가유산야행', '2026-09-11', '2026-09-12', '충남', '충청남도 서천군 한산면 지현리', null, null, 0, 0, null, false, false, false, false, '2026 서천국가유산야행은 ‘한산의 성주, 요란한 잠행’을 주제로 2026년 9월 11일(금)부터 12일(토)까지 한산읍성 일원에서 개최된다. 한산읍성과 한산의 역사·문화유산을 배경으로 다채로운 야간 문화 프로그램과 공연, 체험, 다양한 전시가 펼쳐지며 전통과 현대가 어우러진 멋진 밤을 선사한다. 지역 주민과 관광객이 함께 참여하여 한산의 문화를 오감으로 즐기고 서천 국가유산의 깊은 매력을 색다르게 경험할 수 있는 대표 야간 문화축제이다. 아름다운 국가유산을 무대로 펼쳐지는 잊지 못할 특별한 밤으로 여러분을 모두 초대하는 자리이다.', null, '041-957-9030', 'open', 'info', 'approved', 'TourAPI', 'https://seocheon-yahaeng.kr/', '3351888', 36.0824920000, 126.8037260000, now()),
    (gen_random_uuid(), adm, '서천 홍원항 자연산 전어 꽃게 축제', '축제', '서천 홍원항 자연산 전어 꽃게 축제', '2026-08-22', '2026-09-06', '충남', '충청남도 서천군 홍원길 88', null, null, 0, 0, null, false, false, false, false, '서천 홍원항 자연산 전어·꽃게 축제는 서해안의 대표 포구인 홍원항에서 싱싱한 제철 수산물을 맛보고 다채로운 행사를 즐길 수 있는 수산물 문화 축제이다. 본 행사는 서천의 으뜸 별미인 고소한 자연산 전어와 살이 꽉 찬 제철 꽃게를 마음껏 즐기는 식도락 여행의 장이다. 축제장에서는 남녀노소 누구나 즐겁게 참여할 수 있는 맨손 전어 잡기 등 이색적인 체험 행사와 정겨운 민속놀이, 소중한 추억을 남길 수 있는 포토존 등 풍성한 즐길 거리가 제공된다. 아름다운 바다 풍경과 함께 제철 수산물의 진수를 만끽하고 잊지 못할 추억을 쌓을 수 있는 대표적인 축제이다.', null, '041-950-4414', 'open', 'info', 'approved', 'TourAPI', 'https://www.seocheon.go.kr', '141268', 36.1562870722, 126.5012838671, now()),
    (gen_random_uuid(), adm, '성남동 커피페스티벌', '축제', '성남동 커피페스티벌', '2026-10-30', '2026-11-01', '울산', '울산광역시 중구 북정동', null, null, 0, 0, null, false, false, false, false, '과거 공업도시지구 지정 이후 청춘들이 모여들어 다방을 중심으로 문학과 낭만의 문화를 꽃피웠던 성남동에서, 커피를 주제로 한 특별한 축제가 열립니다. 성남동 커피페스티벌은 커피를 사랑하는 모든 이들을 위한 시민 참여형 문화축제이다. 매년 가을 개최되는 본 축제는 성남동 지역 상인과 커피 업계 종사자들이 함께 기획하고 운영하며, 핸드드립 시연, 라떼아트 체험, 브루잉 대회, 다양한 커피 브랜드 시음 행사 등 풍성한 프로그램을 제공한다. 또한 전국의 실력 있는 바리스타들이 참여하는 커피 퍼포먼스 대회를 비롯해, 가족 단위 방문객도 함께 즐길 수 있는 체험 부스, 라이브 공연, 먹거리 마켓 등 다채로운 즐길 거리가 마련되어 남녀노소 누구나 참여할 수 있는 열린 축제로 자리매김하고 있다.', null, '052-290-3541', 'open', 'info', 'approved', 'TourAPI', 'https://www.uscoffeefest.com/', '3501104', 35.5572230000, 129.3214690000, now()),
    (gen_random_uuid(), adm, '세종대왕과 초정약수축제', '축제', '세종대왕과 초정약수축제', '2026-10-16', '2026-10-18', '충북', '충청북도 청주시 청원구 내수읍 초정약수로 851', null, null, 0, 0, null, false, false, false, false, '세종대왕이 초정행궁에 머무르며 120일간 초정약수로 소갈증과 안질을 치료하고, 국정 운영과 한글 창제 등 위대한 업적을 이룩한 역사적 사실을 기념함으로써 세종대왕과 초정약수의 가치를 재조명하고, 세계적으로 희귀한 3대 광천수 중 하나인 초정약수의 역사적·과학적 우수성을 널리 알리고자 한다. 이를 통해 청주의 청정 자연환경과 건강 자원의 가치를 국내외에 확산함으로써 국내를 넘어 세계적인 문화관광축제로 도약할 수 있는 기반을 마련하며, 지난 20년간 이어져 온 축제의 성과를 바탕으로 청주를 대표하는 브랜드 축제로 자리매김하고자 한다.', null, '043-223-4048', 'open', 'info', 'approved', 'TourAPI', 'http://www.cjart21.org/', '1344850', 36.72128130535547, 127.60067592555232, now()),
    (gen_random_uuid(), adm, '세종한글축제', '축제', '세종한글축제', '2026-10-09', '2026-10-11', '세종', '세종특별자치시 다솜로 216 (세종동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제장 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 국내 유일 ‘한글’을 주제로 한 축제로, 매년 한글날을 기념하는 세종시 대표 축제로 개최되고 있다. 세종대왕의 우수한 업적인 한글의 창제 정신을 기반으로 2013년부터 개최되었으며, 2025년 ‘세종축제’에서 ‘세종한글축제’로 명칭이 변경되었다. 한글의 아름다움과 창의성을 현대적으로 재해석한 공연·전시·체험 프로그램을 통해 세대와 국적을 넘어 남녀노소 누구나 공감하고 즐길 수 있는 축제로 운영되고 있다. 또한, 전통과 현대가 어우러진 다양한 문화예술 프로그램을 통해 한글의 매력과 세종대왕의 정신을 도심 속에서 쉽고 재미있게 경험할 수 있는 세종시만의 차별화된 문화관광축제로 성장하고 있다.', null, '044-850-0591~0594', 'open', 'info', 'approved', 'TourAPI', 'http://sjfestival.kr/', '1849007', 36.49895345303314, 127.27018405937929, now()),
    (gen_random_uuid(), adm, '소래포구축제', '축제', '소래포구축제', '2026-10-02', '2026-10-04', '인천', '인천광역시 남동구 장도로 86-17 (논현동)', null, null, 0, 0, null, false, false, false, false, '소래포구축제는 소래포구가 지닌 풍부한 생태자원과 역사·문화적 가치를 바탕으로 지역의 정체성을 담아내는 대표 축제이다. 축제장은 메인무대존, 체험존, 부스존, 아트존, 역사존, 타워존, 경관존 등 다양한 테마 공간으로 구성되어 남녀노소 누구나 즐길 수 있는 다채로운 프로그램을 선보인다. 어린이 갯벌 놀이터, 어린이 소금 놀이터, 대하 잡기 체험 등 소래의 자연환경을 직접 체험할 수 있는 생태 프로그램을 비롯하여 구민 참여 어등 만들기, 소래 청소년 그림그리기 대회 등 지역 주민, 상인, 예술인, 유관기관이 함께 만들어가는 주민참여 프로그램이 운영된다. 또한 화려한 드론쇼, 가족 모두가 즐길 수 있는 오징어게임, 문화예술 공연과 전시, 야간 경관 콘텐츠 등 풍성한 즐길 거리를 제공한다. 소래포구의 과거와 현재, 그리고 미래를 잇는 소래포구축제는 생태와 역사, 문화와 예술, 사람과 지역이 어우러지는 특별한 축제로서 방문객들에게 잊지 못할 추억과 감동을 선사한다.', null, '070-8820-4038', 'open', 'info', 'approved', 'TourAPI', 'https://blog.naver.com/soraefestival', '506809', 37.3979276988, 126.7393126807, now()),
    (gen_random_uuid(), adm, '수성못페스티벌', '축제', '수성못페스티벌', '2026-09-18', '2026-09-20', '대구', '대구광역시 수성구 무학로 112 (두산동)', null, null, 0, 0, null, false, false, false, false, '수성못페스티벌은 대구시민이 가장 즐겨찾는 수성못을 배경으로 시민들에게 예술체험을 선사하는 축제이다. ''대구광역시 우수지역축제 평가''에서 2019년, 2020년 2회 연속 1위에 선정됐다. 수성문화재단의 정체성을 나타내는 사업 중 하나이다. 올해는 국악관현악과 가·무·악의정수를 담은 K아츠판타지부터 수상음악회, 수상무도회 ''파(波)'', 거리예술공연과 같은 공식 초청공연들과 시민과 예술인이 참여하는 대규모 합창공연인 수성행복콘서트 등이 진행된다. 그 외에도 시민들이 공연하는 전국 청소년 댄스 경연대회, 수성구 초·중학교 음악 어울림 마당, 무형유산한마당을 관람하고, 현장 체험프로그램인 사생실기대회, 들안길 K-푸드 축제까지 참여할 수 있다. 축제의시작과 끝에는 음악 불꽃쇼가 펼쳐진다.', null, '053-668-1500', 'open', 'info', 'approved', 'TourAPI', 'http://www.ssfestival.net/', '1846818', 35.8293753137, 128.6205782501, now()),
    (gen_random_uuid(), adm, '수원 국가유산야행', '축제', '수원 국가유산야행', '2026-08-14', '2026-08-30', '경기', '경기도 수원시 수원천로392번길', null, null, 0, 0, null, false, false, false, false, '수원 국가유산 야행은 수원화성 일원에서 열리는 야간형 문화유산 축제이다. 지역의 특색 있는 역사문화자원을 기반으로 하여 방화수류정~화홍문~수원천 일원, 용연, 행궁광장~팔달문 일원 장소에서 진행된다. 수원화성의 주요 국가유산과 문화시설등을 거점으로 운영하며, 행사는 ‘야경, 야로, 야사, 야화, 야설, 야시, 야식, 야숙’ 등 8야(夜) 주제를 바탕으로 전시, 공연, 체험 프로그램으로 구성되어 있다. 프로그램 운영 시간은 오후 6시부터 오후 10시까지이다. 행사는 수원화성 성곽의 밤을 국가유산과 함께 즐기는 체험의 장으로 다양한 프로그램이 준비되어 있으며, 수원화성의 매력을 느낄 수 있다.', null, '031-290-3562~5', 'open', 'info', 'approved', 'TourAPI', 'https://www.swcf.or.kr/', '1916616', 37.2866450000, 127.0197179000, now()),
    (gen_random_uuid(), adm, '수원남문시장 「불취무귀」 야시장', '축제', '수원남문시장 「불취무귀」 야시장', '2026-09-05', '2026-09-19', '경기', '경기도 수원시 팔달구 팔달문로 9 (팔달로2가)', null, null, 0, 0, null, false, false, false, false, '"취하지 않으며 돌아가지 못하리!" 정조대왕의 말이 왕의 야시장 〈불취무귀〉로 다시 깨어난다. 2026년 9월 5일과 19일, 팔달문 남문시장 일원에서 펼쳐지는 이번 야시장은 정조대왕이 백성을 위해 열었던 시장의 역사적 이야기를 바탕으로, 먹거리와 음악, 공연, 체험 콘텐츠가 함께 운영되는 체류형 야간 축제이다. 축제에서는 푸드트럭과 상인매대, 아트마켓이 운영되며, 방문객은 남문시장 곳곳을 걸으며 다양한 먹거리와 야시장 분위기를 즐길 수 있다. 또한 시장을 누비는 도사 캐릭터와의 대결, 숨은 부적 찾기, 환술 봉인 등 세계관을 기반으로 한 참여형 이벤트가 진행되어 직접 참여하는 축제로 구성된다. 왕의 야시장 〈불취무귀〉는 수원의 역사성과 남문시장의 에너지를 하나로 엮어 방문객이 먹고 걷고 사진을 남기며 수원의 밤을 경험하는 축제이다.', null, '070-7575-2352', 'open', 'info', 'approved', 'TourAPI', 'https://sscf2016.or.kr/', '4099101', 37.2777511770, 127.0184725227, now()),
    (gen_random_uuid(), adm, '수원화성 미디어아트', '축제', '수원화성 미디어아트', '2026-09-19', '2026-10-06', '경기', '경기도 수원시 팔달구 장안동', null, null, 0, 0, null, false, false, false, false, '세계문화유산 수원화성을 배경으로 2021년부터 개최하고 있는 수원화성 미디어아트는 2021~2025년 만천명월:정조의 꿈, 빛이되다 시즌을 끝내고 2026년 「새빛동락(同樂) : 수원화성(華城), 빛으로 피어나다」 ''[새빛]으로 손님을 맞이하고, [동락]으로 함께 즐기는 수원화성의 밤''을 주제로 새롭게 기획했다. 세계문화유산 ''수원화성''의 축성부터 지금까지 시간을 관통하는 사람들의 이야기를 다채로운 빛으로 표현하는 초대형 미디어아트를 구현하는 야간 축제로 화서문 일원의 빛과 영상, 퍼포먼스가 결합된 초대형 미디어아트와 장안공원에서의 다양한 체험형, 반응형 미디어아트 등 18일간의 일정으로 관광객에게 풍성한 볼거리, 즐길거리를 제공한다.', null, '031-290-3622031-5191-3084', 'open', 'info', 'approved', 'TourAPI', 'https://www.swcf.or.kr/?p=317', '2751090', 37.2855120000, 127.0096730000, now()),
    (gen_random_uuid(), adm, '수원화성문화제', '축제', '수원화성문화제', '2026-10-04', '2026-10-11', '경기', '경기도 수원시 팔달구 정조로 825 (남창동)', null, null, 0, 0, null, false, false, false, false, '수원화성문화제는 1795년 정조대왕의 8일간의 화성 행행(行幸)을 현대적 감각으로 풀어낸 수원 대표 종합문화예술축제이다. 《원행을묘정리의궤》에 기록된 역사적 순간들이 공연, 퍼레이드, 체험, 시민참여 프로그램으로 되살아나며, 유네스코 세계유산 수원화성과 화성행궁 일원에서 펼쳐진다. 대표 프로그램인 ‘정조대왕 능행차’는 시민과 관광객이 함께 즐기는 국내 최대 규모의 왕실 퍼레이드로, 축제의 웅장한 매력을 보여준다. 또한 낮에는 전통문화 체험과 참여형 프로그램을, 밤에는 수원화성의 아름다운 경관과 어우러진 고품격 공연 콘텐츠를 즐길 수 있어 국내외 관광객에게 특별한 축제 경험을 선사한다.', null, '031-5191-3647', 'open', 'info', 'approved', 'TourAPI', 'https://shfestival.com/', '914138', 37.2818820192, 127.0143944638, now()),
    (gen_random_uuid(), adm, '순창장류축제', '축제', '순창장류축제', '2026-10-15', '2026-10-18', '전북', '전북특별자치도 순창군 순창읍 장류로 55', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*한국의 장담그기 문화 유네스코 인류무형문화유산 등재 기념과 제20회 성년을 맞은 장류축제를 전통장류의 고장으로서의 정체성 확립 및 K-푸드 우수성을 세계에 알리는 대한민국 대표 발효 음식 축제로 전통장류를 소재로 한 체험 프로그램과문화공연, 전시 및 판매 등 8개 분야 50여개의 다양한 프로그램들이 진행되며, 순창고추장으로 만든 매콤하고 감칠맛 넘치는 음식들을 맛볼 수 있다. 특히 ''순창고추장 임금님 진상행렬'' 퍼포먼스와 발효나라 1997, 콩, 삶고 찧고 메주만들자 등 순창장류축제만의 차별화된 특별한 체험 프로그램들도 선보일 예정이다. 올해는 20주년을 맞아 ''황금메주를 찾아라'', ''성년을 맞은 너와 나'' 장류제품 할인이벤트 등 다채로운 프로그램도 진행될 예정이다.', null, '063-650-1624', 'open', 'info', 'approved', 'TourAPI', 'http://www.jangfestival.co.kr', '638241', 35.36875547170213, 127.11232141891857, now()),
    (gen_random_uuid(), adm, '시민창작예술축제 학산마당극놀래', '축제', '시민창작예술축제 학산마당극놀래', '2026-09-19', '2026-09-19', '인천', '인천광역시 미추홀구 경인로 216-1 (도화동)', null, null, 0, 0, null, false, false, false, false, '2014년에 시작된 학산마당극놀래는 인천광역시 미추홀구 미추홀학산문화원이 주최 주관하여 시민들이 직접 창작극을 만들고 즐기는 대표적인 시민창작예술축제이다. 주민들이 마을에서 모여 문화로 소통하며 지역의 이슈나 삶의 이야기를 담아 창작한 공연 작품을 이웃과 나누는 신명나는 마당이다. 창작 난타극, 탈춤극, 연극, 인형극, 음악극, 입체낭독극 등 예술적 표현의 다양한 형식을 넘나드는 시민문화예술의 장으로 거듭나고 있다. 지역주민이 만드는 주민 주도형 시민공동체예술축제를 위하여 주민과 예술가, 관련 단체 및 기관 등이 연대하여 공동체 예술의 성장과 지역 문화의 발전을 이루어 가고 있다.', null, '032-866-3994', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.haksanculture.or.kr
공식 인스타그램 https://www.instagram.com/mchhaksan/', '2829118', 37.4631460755, 126.6663055720, now()),
    (gen_random_uuid(), adm, '시흥갯골축제', '축제', '시흥갯골축제', '2026-09-18', '2026-09-20', '경기', '경기도 시흥시 동서로 287 (장곡동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*시흥갯골축제는 경기도 유일의 내만갯골에 위치한 시흥갯골생태공원에서 펼쳐지는 생태축제로 옛 염전 터와 습지가 어우러진 자연환경을 기반으로 자연에서 쉬고 배우며 즐기는 다양한 프로그램을 통해 자연과 동화되는 축제로 생태공원의 자연환경을 보호하기 위해 차 없는 축제로 진행하고 있다. 대표 프로그램으로는 염판 공연 ‘소금의 기억, 물의 춤’이 있으며 공연으로는 콘서트 in 갯골, 소금창고 인형극장, 나무숲 음악제, 갯골 시니어 런웨이가 펼쳐질 예정이다. 그 밖에 판타지 열기구 체험, 갯골험대, 솔트플레이⋅맨발의 소금길, SEA POOL파티, 폴짝폴짝 곤충체험, 오늘하루 갯골이 내 놀이터, 염전 체험, 느린 우체국, 「걷자 시흥」 걷기 한마당, 시흥염전 소금제, 거리로 나온 예술제, 갯골 전국 미술대회, 갯골 추억의 사진관, 갯골 스탬프 랠리 등 다양한 즐길거리가 제공될 예정이다.', null, '031-310-2916, 2919~2920', 'open', 'info', 'approved', 'TourAPI', null, '142197', 37.3897711469, 126.7812405855, now()),
    (gen_random_uuid(), adm, '시흥월곶포구축제', '축제', '시흥월곶포구축제', '2026-10-09', '2026-10-11', '경기', '경기도 시흥시 월곶해안로 188 (월곶동)', null, null, 0, 0, null, false, false, false, false, '도심속 바다에서 경험하는 다양한 포구체험을 즐길 수 있는 바다축제인 [시흥월곶포구축제]는 도시와 바다가 어우러진 생생한 포구체험과 어민이 직접 잡은 신선한 제철 수산물을 활용한 먹거리 등 풍성한 프로그램을 통해 방문객들에게 잊지 못할 추억을 선사하는 행사이다. 대표체험프로그램인 어선승선체험과 맨손 고기잡이, 왕새우잡이 체험을 통해 바다와 가까워지는 경험을 할 수 있으며, 3세대가 함께 즐길 수 있는 월곶 달빛콘서트 및 개폐막식 불꽃축제는 매년 많은 관광객들의 기대를 모으고 있는 인기프로그램 중 하나이다. 또한, [시흥월곶포구축제]에서만 만날 수 있는 수산물 깜짝 경매 및 건어물 도매시장, 새우젓 담그기 체험 등 직접적인 어촌의 포구체험도 만나볼 수 있다.', null, '031-310-4794', 'open', 'info', 'approved', 'TourAPI', null, '2828336', 37.3873639083, 126.7402812374, now()),
    (gen_random_uuid(), adm, '신라문화제', '축제', '신라문화제', '2026-10-09', '2026-10-11', '경북', '경상북도 경주시 노동동', null, null, 0, 0, null, false, false, false, false, '신라문화제는 1962년 제1회를 시작으로 올해 제53회를 맞이한다. 월정교를 배경으로 신라의 찬란한 역사를 재현하는 화백제전과 수많은 아티스트가 참여해 화려한 공연을 선보이는 거리예술축제, 실크로드페스타까지 다채로운 콘텐츠가 가득하다. 화랑힙합페스타는 고분을 배경으로 국내 최정상급 힙합 아티스트의 공연이 펼쳐져 경주에서만 볼 수 있는 이색적인 풍경을 선사한다. 즐거움을 더하는 낭만 야시장인 달빛난장은 경주 지역 상인이 직접 참여하여 경주의 맛을 자랑한다. 이처럼 천년고도 경주를 대표하는 축제인 신라문화제에서는 역사와 예술이 하나로 어우러지는 특별한 순간을 만나볼 수 있다.', null, '054-776-5265', 'open', 'info', 'approved', 'TourAPI', 'https://www.gyeongju.go.kr/', '1718137', 35.841281, 129.210644, now()),
    (gen_random_uuid(), adm, '안동국제탈춤페스티벌', '축제', '안동국제탈춤페스티벌', '2026-09-24', '2026-10-04', '경북', '경상북도 안동시 육사로 239 (운흥동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제장 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*안동국제탈춤페스티벌은 가면의 기억, 모두의 춤으로 하나가 되는 글로벌 축제이다. 유네스코 인류무형문화유산으로 등재된 한국의 탈춤과 세계 여러나라의 탈춤 모두 축제장에서 경험하며 함께 즐길 수 있다. 나아가 다채로운 공연과 퍼레이드, 대동난장, 세계탈놀이 경연대회 등 함께 어울릴 수 있는 장을 선사할 예정이다. 안동국제탈춤페스티벌2026은 가면이 간직해 온 시간을 현재의 삶과 연결하고자 한다. 아이부터 어르신까지, 지역 주민과 세계의 방문객까지 모두가 같은 공간에서 웃고 박수 치며 리듬을 나누는 순간, 탈이 전해 온 기억은 살아 있는 문화가 된다. 이번 축제는 그렇게 이어진 마음들이 모여 완성되는 ‘모두의 춤’이며, 함께할 때 더욱 빛나는 공동체의 힘을 보여주는 자리가 될 것이다.', null, '054-840-3400', 'open', 'info', 'approved', 'TourAPI', 'https://www.maskdance.com/2024/main.asp', '506670', 36.5597879985, 128.7307724581, now()),
    (gen_random_uuid(), adm, '안산 대부포도축제', '축제', '안산 대부포도축제', '2026-09-19', '2026-09-20', '경기', '경기도 안산시 단원구 대부황금로 1480-7 (대부북동)', null, null, 0, 0, null, false, false, false, false, '안산 대부포도축제는 서해안의 풍부한 해풍과 비옥한 토양에서 자라 당도가 높고 향이 진한 대부포도의 우수성을 알리기 위해 매년 9월 가을철에 개최되는 안산의 대표적 축제이다. 1995년에 처음 시작되어 오랜 역사를 이어오고 있으며 단순한 농산물 판매를 넘어 남녀노소 누구나 참여해 즐길 수 있는 오감 만족형 축제로 자리잡았다. 행사장인 대부다바향기테마파크 일원에서는 중간 유통 마진을 뺀 신선한 고품질 포도를 합리적인 가격에 구매할 수 있는 직거래 장터가 열린다. 또한, 축제의 하이라이트인 신나는 음악과 함께 포도를 직접 밟아보는 포도밟기 체험도 빠질 수 없는 즐길거리이다. 이외에도 축하공연, 대부해솔길 걷기축제와 안산마라톤대회 등 다채로운 연계행사와 풍성한 먹거리가 어우러져 대부에 취하고 즐기고 빠지는 추억을 선사한다.', null, '031-481-2318', 'open', 'info', 'approved', 'TourAPI', null, '1389228', 37.2862743274, 126.5745536210, now()),
    (gen_random_uuid(), adm, '안성 남사당바우덕이 풍물단 상설 공연 ‘곰뱅이텄다’', '축제', '안성 남사당바우덕이 풍물단 상설 공연 ‘곰뱅이텄다’', '2026-04-04', '2026-11-29', '경기', '경기도 안성시 보개면 남사당로 198-2', null, null, 0, 0, null, false, false, false, false, '안성 남사당바우덕이 풍물단 상설공연은 2003년부터 진행한 안성시의 대표 문화콘텐츠이다. 안성시를 대표하는 안성시립 남사당 바우덕이 풍물단의 2026년 상설공연 ''곰뱅이텄다''는 ''장터의 신명, 경복궁을 들썩이다!''라는 부제 아래 남사당 놀이의 정수인 6마당을 현대적인 감각으로 재구성하여 선보이는 공연이다. 공연은 매주 토요일과 일요일 오후 2시에 안성 남사당 공연장에서 약 90분간 진행된다. 태평소와 꽹가리 등이 어우러지는 활기찬 풍물과 3m 높이의 줄 위에서 아슬아슬한 기예와 재담을 나누는 어름(줄타기), 대접을 돌리는 버나, 땅재주를 부리는 살판 등 다채로운 볼거리가 가득하다.', null, '031-678-2518', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.anseong.go.kr/tourPortal/namsadang', '293030', 37.0317706868448, 127.310126633916, now()),
    (gen_random_uuid(), adm, '안성맞춤 남사당 바우덕이축제', '축제', '안성맞춤 남사당 바우덕이축제', '2026-10-02', '2026-10-05', '경기', '경기도 안성시 보개면 남사당로 198', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*안성맞춤 남사당 바우덕이축제는 유네스코 인류무형문화유산으로 지정된 남사당놀이를 소재로 한 축제이다. 조선 최초 여성 꼭두쇠 바우덕이의 예술혼과 안성 남사당패의 흥과 멋을 계승·발전시키며, 조선시대 전국 3대 장터의 풍성한 모습을 재현한 안성 옛장터를 비롯해 전통문화 체험, 국내외 전통예술 공연, 해외 민속공연 등 남녀노소 모두가 함께 즐길 수 있는 다채로운 프로그램을 선보인다. 특히 줄타기와 남사당놀이의 진수를 가까이에서 만나고, 전통과 현대가 어우러진 공연을 통해 한국 전통문화의 매력을 생생하게 경험할 수 있다. 역사와 문화, 공연, 관광이 어우러진 안성맞춤 남사당 바우덕이축제는 국내외 관광객이 함께 즐기는 문화관광축제로 자리매김하며, 대한민국을 대표하는 전통문화축제로 발전하고 있다.', null, '031-678-5414', 'open', 'info', 'approved', 'TourAPI', 'https://www.anseong.go.kr/', '506690', 37.0336344681, 127.3054103868, now()),
    (gen_random_uuid(), adm, '안아드림 페스티벌', '축제', '안아드림 페스티벌', '2026-10-02', '2026-10-03', '경북', '경상북도 안동시 풍천면 갈전리', null, null, 0, 0, null, false, false, false, false, '경상북도에서 2021년부터 개최하는 경북 최대 규모의 안전체험행사로, 도민들이 직접 참여할 수 있는 다양한 안전체험과 이벤트, 전시·공연 등을 즐길 수 있다. 올해에는 40여 개의 기관, 단체와 협력하여 70여 개의 양질의 안전체험 프로그램을 운영한다. 또한 어린이들이 좋아하는 마술쇼, 버블쇼 등 공연행사뿐 아니라 눈이 즐거운 인명구조견 훈련시범, 드론시연행사도 준비되어 있으며 실제 현장에서 사용하는 소방차량, 소방장비, 무인방수차량 전시 등을 통해 새로운 경험을 해볼 수 있다. 올해에는 영유아층이 좋아하는 대교 트니트니와 함께 에어바운스 및 안전체조를 경험할 수 있으며 스탬프투어, 보물찾기, 소방퍼레이드, ''안아드림 소방학교'', ''안전UP체력 한마당'' 등의 도민들이 참여할 수 있는 특별한 부대 행사도 즐길 수 있다.', null, '010-8266-7331', 'open', 'info', 'approved', 'TourAPI', null, '2856675', 36.5715690000, 128.5049710000, now()),
    (gen_random_uuid(), adm, '안양춤축제', '축제', '안양춤축제', '2026-09-18', '2026-09-20', '경기', '경기도 안양시 동안구 관평로 149 중앙공원관리부속', null, null, 0, 0, null, false, false, false, false, '[안양춤축제 – ANYANG DANCE FESTIVAL]이 9월 18일부터 20일까지 안양 평촌중앙공원과 삼덕공원에서 3일간 펼쳐진다. 2000년 첫 문을 연 안양시민축제는 23년간 시민들과 함께 하며 매년 30만여 명의 관람객이 찾는 안양시 대표 축제를 넘어 경기도 대표 관광축제로 입지를 다졌다. 시민이 만들고, 참여하고, 관람하는 대표적인 시민 참여형 축제로 시민과 사람, 그리고 시민의 생활예술(Living Arts) 콘텐츠를 주제로 지역 예술인 공동체 형성과 시민 문화 커뮤니티 육성에 기여하고 있다. 걷고 달리는 행위도 넓은 범위에서 몸을 자유롭게 움직이는 ‘춤’이라는 인식을 줄 수 있도록 ‘걷고, 달리고, 춤추자!’라는 슬로건 아래, 안양 곳곳에 잠재되어 있는 움직임, Dance에 대한 열정을 발굴해 시민예술가들의 에너지와 역동성을 마음껏 펼치도록 독려한다. 또한 축제에 참여하는 안양 시민과 안양을 찾는 관람객들이 안양이라는 공간 안에서 ‘같이 추는’ 문화를 만들어 ‘춤’과 ‘문화 예술’을 매개로 화합할 수 있는 국내 유일의 지역 기반 K-Dance 문화 예술축제로 거듭나고자 한다.', null, '031-687-0538', 'open', 'info', 'approved', 'TourAPI', null, '1390147', 37.3901347706, 126.9613281280, now()),
    (gen_random_uuid(), adm, '안흥찐빵축제', '축제', '안흥찐빵축제', '2026-10-02', '2026-10-04', '강원', '강원특별자치도 횡성군 안흥면 주천강로 1868', null, null, 0, 0, null, false, false, false, false, '달콤하고 모락모락 피어나는 정겨운 온기가 가득한 제18회 안흥찐빵축제에는 풍성하고 다채로운 프로그램이 준비되어 있다. 이번 축제는 남녀노소 모두가 함께 즐길 수 있는 이색적이고 흥겨운 행사들로 가득 채워져 방문객들에게 잊지 못할 추억을 선사할 예정이다. 찐빵 & 도깨비 페스티벌은 안흥찐빵의 고유한 매력과 지역 설화인 도깨비 테마를 결합하여 올해로 3회째를 맞는 특색 있는 메인 페스티벌이다. 축제장의 분위기를 한층 더 유쾌하고 신나는 에너지로 물들일 예정이다. 토토가(토요일, 토요일은 가수다)는 큰 호응을 얻으며 어느덧 세 번째 시즌을 맞이하며 90년대를 추억하는 레트로 감성의 명곡들과 신나는 흥이 어우러져 세대를 뛰어넘는 대통합의 무대가 진행될 예정이다. 도깨비 원정대 및 체험 이벤트는 축제장 곳곳을 누비며 활력을 불어넣는 ''도깨비 원정대''의 퍼포먼스와 더불어, 찐빵을 주제로 한 다양한 참여형 이벤트이며 상시 운영될 예정이다. 대망의 마지막 날 ''면민 노래자랑''은 축제의 대미를 장식할 마지막 날에 지역 주민과 관광객이 하나 되는 화합의 장, ''면민 노래자랑''이 개최되어 뜨거운 열기 속에 화려한 피날레를 장식할 예정이다. 모락모락 피어나는 맛있는 찐빵의 달콤함', null, '033-340-2746', 'open', 'info', 'approved', 'TourAPI', 'https://www.hsg.go.kr/tour/contents.do?key=1372&', '2027215', 37.4096593219, 128.1555666937, now()),
    (gen_random_uuid(), adm, '어부장터X포트빌리지 통영', '축제', '어부장터X포트빌리지 통영', '2026-11-06', '2026-11-08', '경남', '경상남도 통영시 도남동', null, null, 0, 0, null, false, false, false, false, '2026 어부장터 x 포트빌리지 통영은 통영 어부장터와 항구 미식 축제 포트빌리지가 협업하여 선보이는 지역 미식 축제이다. 2026년 11월 6일부터 11월 8일까지 3일간 통영시 도남동 트라이애슬론광장에서 개최되는 축제이며, 통영의 대표 수산물과 지역 먹거리를 활용한 다양한 메뉴를 선보이는 행사이다. 주요 참여 부문은 일반 먹거리 부스, 퍼포먼스 부스, 셰프 컨설팅 부스로 구성되며, 일반 먹거리 부스는 굴, 장어, 멍게, 참돔 등 통영의 대표 원물과 먹거리를 활용한 메뉴를 운영하는 방식이다. 퍼포먼스 부스는 현장 조리, 메뉴 연출, 고객 참여 등 조리 과정과 볼거리를 함께 제공하는 방식이며, 셰프 컨설팅 부스는 유명 셰프와 함께 통영 대표 먹거리를 활용한 메뉴를 개발하는 방식이다. 축제는 통영의 바다와 미식을 지역의 콘텐츠로 활용하고, 지역 브랜드와 생산자가 방문객을 만나는 기회를 제공하는 행사이다. 또한 축제 전후의 홍보와 콘텐츠, 브랜드 성과를 연계하여 축제를 일회성 행사에 그치지 않고 통영의 관광 및 지역 브랜드와 연결하는 플랫폼으로 운영하는 것을 주요 방향으로 하는 축제이다.', null, '070-4680-1718', 'open', 'info', 'approved', 'TourAPI', null, '3400809', 34.8255760000, 128.4338030000, now()),
    (gen_random_uuid(), adm, '얼음나라화천 산천어축제', '축제', '얼음나라화천 산천어축제', '2027-01-09', '2027-01-31', '강원', '강원특별자치도 화천군 화천읍 산천어길 137', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 2026년 축제 내용으로, 2027년도 축제 내용은 업데이트 중에 있습니다*강원특별자치도 화천에서 열리는 얼음나라화천 산천어축제는 2011년 미국 CNN이 선정한 ''겨울의 7대 불가사의'' 중 하나로 꼽힌 이색 겨울축제다. 물 맑기로 유명한 화천천이 꽁꽁 얼어붙는 매년 1월에 축제가 열리며 얼음낚시, 맨손잡기 등으로 계곡의 여왕이라고 불리는 산천어를 잡는 체험을 할 수 있다. 산천어 얼음낚시의 손맛은 물론 바로 회나 구이로 맛있게 먹을 수 있고 낚시 외에도 얼음썰매, 눈썰매, 봅슬레이 등의 다양한 겨울놀이가 펼쳐져 매년 100만명 이상이 방문하고 있다.', null, '1688-3005', 'open', 'info', 'approved', 'TourAPI', 'www.narafestival.com', '507599', 38.1126243028, 127.7098811689, now()),
    (gen_random_uuid(), adm, '여주오곡나루축제', '축제', '여주오곡나루축제', '2026-10-23', '2026-10-25', '경기', '경기도 여주시 천송동', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*여주오곡나루축제는 쌀과 고구마 등 여주의 우수한 농특산물을 조선시대 4대 나루터 중 하나인 조포나루를 통해 임금님께 진상하던 역사적 배경을 바탕으로 열리는 전통문화축제이다. 대표 프로그램으로는 진상 퍼레이드, 여주쌀 가마솥 비빔밥, 군고구마 기네스, 소원지길, 낙화놀이 등이 있으며, 다채로운 먹거리와 전통 체험, 야간 프로그램을 통해 남녀노소 모두 즐길 수 있는 가을 대표 축제이다.', null, '031-881-9694', 'open', 'info', 'approved', 'TourAPI', 'https://www.yjfestival.or.kr/', '1147035', 37.29912, 127.655753, now()),
    (gen_random_uuid(), adm, '영광불갑산상사화축제', '축제', '영광불갑산상사화축제', '2026-09-18', '2026-09-27', '서울', '전남광주통합특별시 영광군 불갑면 불갑사로 450', null, null, 0, 0, null, false, false, false, false, '천년의 시간을 품은 고찰 불갑사와 사계절 아름다운 자연을 간직한 불갑산 자락에 가을의 시작을 알리는 상사화가 다시 피어난다. 제26회를 맞이하는 영광불갑산상사화축제는 붉은 꽃물결 속에서 자연과 사람이 이어지는 특별한 순간으로 관람객을 초대하는 축제이다. 불갑산 일대에 펼쳐진 수백만 송이 상사화 군락을 중심으로 산과 길 곳곳에서 다채로운 프로그램이 운영된다. 낮에는 자연과 꽃이 어우러진 풍경을 감상할 수 있으며, 밤에는 은은한 조명으로 연출된 상사화 야간경관이 또 다른 감동을 선사한다. 공연·전시·체험 프로그램과 캐릭터 ‘상사호’ 이벤트가 더해져 남녀노소 모두가 함께 즐길 수 있는 축제이다. 붉게 물든 상사화 꽃길을 따라 천천히 걸으며 소중한 사람과 추억을 나누고, 분주한 일상에서 벗어나 마음을 쉬어갈 수 있는 시간이다. 자연이 전하는 위로와 설렘, 그리고 사랑의 감성이 머무는 곳이다. 가을이 가장 먼저 피어나는 영광불갑산상사화축제에서 특별한 가을의 시작을 만날 수 있다.', null, '061-350-5269', 'open', 'info', 'approved', 'TourAPI', 'www.상사화축제.com/', '1078905', 35.2001494518, 126.5506284863, now()),
    (gen_random_uuid(), adm, '영덕 국가유산야행', '축제', '영덕 국가유산야행', '2026-08-21', '2026-08-23', '경북', '경상북도 영덕군 영해면 예주2길 10', null, null, 0, 0, null, false, false, false, false, '2026 영덕 국가유산 야행은 ''영해 1926, 그날 밤을 거닐다''를 부제로, 경상북도 영덕군 영해면 영해장터거리 근대역사문화공간 일원에서 2026년 8월 21일부터 23일까지 3일간 펼쳐지는 야간 역사문화 축제이다. 영해장터거리는 전국 6개 지역에만 존재하는 면(面) 단위 국가등록문화유산으로, 이곳에서 열리는 야행은 100년 전 영해의 풍경을 골목 곳곳에 되살려 관람객이 직접 걸으며 역사를 체험하는 몰입형 문화 행사이다. 1926년이라는 시간을 배경 삼아, 실경뮤지컬·근대의상 퍼레이드·인력거·무성영화·전통 무형유산 공연 등 다채로운 콘텐츠가 밤거리를 가득 채운다. 야경·야로·야사·야화·야설·야식·야숙·야시 8가지 테마 아래 총 40개 프로그램이 매일 오후 7시부터 11시까지 운영되며, 모든 행사는 무료로 참여할 수 있다.', null, '054-730-5852', 'open', 'info', 'approved', 'TourAPI', 'http://yahaeng.ydstay.kr/', '2846353', 36.5363350972, 129.4083003171, now()),
    (gen_random_uuid(), adm, '영동난계국악축제', '축제', '영동난계국악축제', '2026-10-15', '2026-10-18', '충북', '충청북도 영동군 영동읍 영동힐링로 117', null, null, 0, 0, null, false, false, false, false, '*하기 축제장 먹거리 정보는 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*영동군의 문화유산이자 전통문화예술인 국악을 주제로 하여 난계 박연선생의 음악적 업적을 기리고 전통문화예술 진흥에 기여하기 매년 개최되고 있는 문화예술 공연 축제이다. 제57회 영동난계국악축제는 2025 영동세계국악엑스포의 성과를 계승하여 국악이라는 대한민국 유산을 전세계적으로 홍보하고 제2의 한류문화 부흥에 이바지 하고자 한다. 또한 대한민국 유일의 국악축제로 다양한 국악공연과 체험 프로그램을 통한 전통문화예술을 현대적으로 계승하고 지역 특성에 맞는 프로그램으로 축제의 지역관광자원화에 힘쓰고 있다. 지역민의 문화적 수준 향상과 자발적 참여를 통한 군민 화합의 한마당 자리 마련한다.', null, '043-745-8917', 'open', 'info', 'approved', 'TourAPI', 'http://ydnan-gye.co.kr/', '293084', 36.1563534107, 127.7865136910, now()),
    (gen_random_uuid(), adm, '예산사과축제', '축제', '예산사과축제', '2026-10-30', '2026-10-31', '서울', '충남 예산군 응봉면 후사리 39', null, null, 0, 0, null, false, false, false, false, '이번 제23회 예산사과축제는 국대 최대 규모를 자랑하는 예당호 출렁다리의 장관과 함께 남녀노소 누구나 즐길 수 있는 다채로운 사과 체험 프로그램으로 진행될 예정이다. ''예당호출렁다리''라는 지역의 관광자원을 활용하고 올해 개최지로 정함으로써, 지역의 상징적인 예당호 전망대를 시작으로 예당호 일원 관광시설과 연계하여 축제기간 예산사과와 지역의 랜드마크를 동시에 홍보하는 축제로 진행될 예정이다. 사과 와인, 사과 디저트와 그리고 재즈,국악,클래식 콜라보로, ''예당호에서의 달콤한 하루''라는 테마로 방문객들에게 예산사과의 맛과 우수성을 알리는 축제로 진행될 예정이다. 프로그램 중 ''예산사과 세일페스타''는 예산사과 과수농가가 참여하고 예당사과원예농업협동조합이 운영하는 예산사과 세일 판매장으로, 축제기간동안인 단 이틀간만 진행되며, 고품질의 예산사과를 저렴한 가격에 만날 수 있을 대표프로그램으로 진행될 것이다.', null, '041-332-3506', 'open', 'info', 'approved', 'TourAPI', null, '639648', 36.6390415000, 126.8019627000, now()),
    (gen_random_uuid(), adm, '예산장터 삼국축제', '축제', '예산장터 삼국축제', '2026-10-22', '2026-10-25', '충남', '충청남도 예산군 예산읍 예산시장길 2', null, null, 0, 0, null, false, false, false, false, '올해는 예산장터 삼국축제 10년, 예산시장 100년을 기념하는 특별한 해로, 국밥·국수·국화에 담긴 군민들의 삻과 이야기, 새로운 100년을 시작하는 예산시장의 끝없는 희망의 메시지를 전달하는 축제로 진행될 예정이며 지난 10년간의 기록들과 군민들의 바람을 생동감과 안정감있게 ''삼국''이라는 희망상자에 빠짐없이 담을 예정이다. 가치의 확장, 공간의 확장, 참여의 확장, 시간의 확장 이 4가지의 테마로 ''끝나지 않는 이야기'' 주제를 풀어나갈 것이며, "예산장터! 우리들의 이야기는 계속된다"라는 슬로건을 가지고, 우리 지역 전역의 축제분위기를 고조시키며, 지역 청년로컬크리에이터 및 청년단체와의 협업을 통한 지역축제의 브랜드를 선보일 예정이다. 예산장터 삼국축제에서 꼭 해야하는 버킷리스트 10가지 중 선정하여 참여하는 대표프로그램을 중심으로 삼국콘텐츠를 강화한 지역민과 함께하는 먹거리문화를 활성화하여 운영될 예정이다.', null, '041-332-4317', 'open', 'info', 'approved', 'TourAPI', null, '2558866', 36.6770296847, 126.8496518916, now()),
    (gen_random_uuid(), adm, '예산황새축제', '축제', '예산황새축제', '2026-09-05', '2026-09-06', '충남', '충청남도 예산군 광시면 시목대리길 62-19', null, null, 0, 0, null, false, false, false, false, '''제7회 예산황새축제''는 복원된 황새들의 안정적인 서식 환경 조성과 야생에서의 생존을 간절히 응원하는 황새마을의 따뜻한 노력을 담아낸 뜻깊은 생태 축제이다. 최근 급격한 기후 변화로 인해 자연 생태계가 위협받으며, 황새들이 자연에서 살아가는 데 많은 어려움이 더해지고 있다. 하지만 강한 귀소본능으로 잊지 않고 황새마을을 찾아오는 이 아름다운 새들을 위해, 우리는 황새와 사람이 함께 어우러져 살아가는 친환경적인 서식지를 정성껏 가꾸어 나가고 있다. 이번 축제는 이러한 마을의 헌신과 생태 보전의 메시지를 다채로운 기획 체험 프로그램과 전시를 통해 생생하게 전달할 예정이다. 황새와 더불어 사는 청정 예산황새마을에서 자연의 소중함을 느끼고, 생명의 경이로움을 나누는 특별한 시간으로 진행될 예정이다.', null, '041-339-8367', 'open', 'info', 'approved', 'TourAPI', null, '2843521', 36.5430163206, 126.7970564001, now()),
    (gen_random_uuid(), adm, '오감만족 문경새재맨발페스티벌', '축제', '오감만족 문경새재맨발페스티벌', '2026-08-22', '2026-08-22', '경북', '경상북도 문경시 문경읍 새재로 932', null, null, 0, 0, null, false, false, false, false, '매년 만 명 이상이 모이는 문경새재 제1관문~3관문 사이 황톳길 7㎞를 맨발로 걷는 행사이다. 인기 가수 초청 공연과 행사장 곳곳 맨발로 참여할 수 있는 게임이 다수 마련되어 있다. 다양한 종류의 부스 운영을 통해 맨발 걷기 뿐만 아니라 다채로운 프로그램에 참여할 수 있다. 또한 일반인 노래자랑과 아이들을 위한 프로그램 마련으로 남녀노소 불문하고 가족과 연인 친구가 함께 문경새재의 풍경을 즐기면서 건강까지 챙길 수 있다. 3관문에 완주하는 사람에게는 선착순으로 메달도 증정한다.', null, '053-755-5881', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://cafe.naver.com
