    (gen_random_uuid(), adm, '완주 상관 워터풀파티', '축제', '완주 상관 워터풀파티', '2026-09-12', '2026-09-13', '전북', '전북특별자치도 완주군 상관면 춘향로 4355', null, null, 0, 0, null, false, false, false, false, '상관 워터풀파티는 완주군 상관면의 물, 숲, 온천, 숙박, 먹거리 등 지역 관광자원을 연계하여 운영하는 체류형 관광축제이다. 상관면을 단순 경유지가 아닌 머무르며 즐길 수 있는 관광지로 알리고, 지역의 다양한 관광자원과 공간을 함께 경험할 수 있도록 기획한 행사이다. 주요 프로그램은 물놀이를 중심으로 한 상관 워터풀파티와 지역 먹거리를 즐길 수 있는 상관 야시장으로 구성한다. 이와 함께 편백숲 등 자연자원을 활용한 체험 프로그램인 ‘상관 숲티비티’, 지역의 숲과 마을을 걸으며 즐기는 트레킹 프로그램 ‘상관있이 걷기’, 지역 숙박시설과 연계한 체류 프로그램 ‘상관 ZIP’ 등을 운영한다. 낮 시간대의 물놀이와 숲 체험부터 야간 먹거리와 숙박까지 연계하여 상관면의 자연·관광·생활 자원을 종합적으로 경험할 수 있도록 구성한 축제이다.', null, '063-262-3955 (070-7715-7456)', 'open', 'info', 'approved', 'TourAPI', 'https://wfac.or.kr/', '4098980', 35.7394598918, 127.2229537240, now()),
    (gen_random_uuid(), adm, '완주 와일드&로컬푸드축제', '축제', '완주 와일드&로컬푸드축제', '2026-10-02', '2026-10-04', '전북', '전북특별자치도 완주군 고산면 고산휴양림로 89', null, null, 0, 0, null, false, false, false, false, '완주군 대표축제인 ''완주 와일드&로컬푸드축제''는 완주의 청정자연속에서 일상에서 경험해보지 못한 와일드(WILD)한 이색 체험과 로컬푸드 1번지로서 건강한 지역(LOCAL) 먹거리(FOOD)를 만날 수 있는 남녀노소 누구나 즐길 수 있는 축제이다. 2026년 축제는 "불 타오르는 거친 야생"이라는 슬로건으로 불타는 화덕구이, 로컬 부시크래프트, 감자삼굿, 불 주제 대형 이벤트를 대표 프로그램으로, 이 외에도 시랑천 수상놀이, 볓집미끄럼틀 등 자연을 담은 와일드 놀이터, 13개읍면 부녀회 셰프들이 정성을 담아낸 로컬밥상, 농특산물 직거래 장터, 야생 와푸 EDM 뮤직파티 등 가을날 정취와 함께 추억과 향수, 일탈과 힐링을 한꺼번에 경험할 수 있다.', null, '063-290-3976~8', 'open', 'info', 'approved', 'TourAPI', 'https://www.wanjufestival.kr/', '1336591', 35.974170146415695, 127.23120952485095, now()),
    (gen_random_uuid(), adm, '왕가의 산책', '축제', '왕가의 산책', '2026-01-05', '2026-12-31', '인천', '인천광역시 영종구 공항로 272 (운서동)', null, null, 0, 0, null, false, false, false, false, '인천국제공항에서 출국 전 만날 수 있는 전통문화행사인 왕가의 산책은 조선시대 궁중생활을 재현하는 행사이다. 제1여객터미널에서는 왕과 왕비가 궁궐을 산책하는 모습이 재현된다. 제2여객터미널에서는 조선 후기 무과 전시장에 거둥 왕과 무관의 행렬이 재현된다. 행사 종료 후 궁중 복식 및 의장물을 착용한 출연자들과 함께 기념사진을 찍을 수 있어 색다른 경험을 할 수 있다. 조선시대의 생활을 눈앞에서 직접 관람할 수 있어 특별한 재미를 선사하며 공항에서 진행되는 행사로 공항 방문객들에게 볼거리를 제공한다. 가족들과 함께 관람하기에도 좋은 행사이다.', null, '032-743-0468', 'open', 'info', 'approved', 'TourAPI', 'https://www.kh.or.kr/', '2433596', 37.458350712273, 126.427699293474, now()),
    (gen_random_uuid(), adm, '왜관 홀리 페스티벌', '축제', '왜관 홀리 페스티벌', '2026-09-04', '2026-09-06', '경북', '경상북도 칠곡군 왜관읍 관문로 61', null, null, 0, 0, null, false, false, false, false, '경북 칠곡군이 보유한 풍부한 천주교 문화유산과 관광을 연계한 축제이며, Holy(신성한, 가치)한 곳에서 Holiday(휴일, 재미)를 보내는 콘셉트로, 천주교의 역사와 정신이 깃든 왜관수도원을 중심으로 개최된다. 주간에는 빛의 풍경, 야간에는 빛의 성당과 몽환의 숲을 연출하였으며, MZ신부님(이창민)과 함께하는 토크콘서트, 홀리콘서트(린, 안예은), 버스킹 공연, 그레고리안 성가 공연, 파이프 오르간 연주 등 다양한 공연을 즐길 수 있다. 중세 유럽과 같은 분위기의 왜관수도원에는 다양한 포토존(인생사진 스튜디오, 수도복 복식체험 포토부스 등), 이색적인 체험(하늘성당 아빠스 특별미사, 수도사와 함께하는 수도원 투어, 피정 체험 등) 프로그램이 준비되어 있다.', null, '054-979-6087', 'open', 'info', 'approved', 'TourAPI', null, '3486887', 35.9877833495, 128.4014504193, now()),
    (gen_random_uuid(), adm, '외계인 대축제', '축제', '외계인 대축제', '2026-09-19', '2026-09-20', '경남', '경상남도 밀양시 시청로 28 (교동)', null, null, 0, 0, null, false, false, false, false, '제7회 외계인 대축제는 국내 유일 외계생명에 특화된 밀양아리랑우주천문대가 선보이는 대표 가족형 체험축제이다. 우주와 외계인을 주제로 어린이와 부모 세대가 함께 즐길 수 있도록 구성한 밀양의 과학문화 축제이다. 올해 축제는 영남루 밀양강변 일원에서 ''외계인 운동회'' 콘셉트로 진행된다. 기존의 관람 중심 행사를 넘어 가족이 함께 뛰고, 체험하며 즐길 수 있는 참여형 축제로 메테오 런, 레이저 태그, 코스튬 대회 등 온 가족이 함께 참여할 수 있는 체험형 콘텐츠로 마련된다. 여기에 우주·과학 콘텐츠를 더해 놀이의 즐거움과 교육적 의미를 함께 담아낸다. 또한 밀양아리랑우주천문대와 연계한 우주·과학 콘텐츠를 더해 놀이의 즐거움과 교육적 의미를 함께 담아내어 과학문화 축제로 가족, 친구와 함께 일상을 벗어나 색다른 즐거움과 추억을 남길 수 있다.', null, '055-359-5788', 'open', 'info', 'approved', 'TourAPI', null, '2872196', 35.5056758310, 128.7448340945, now()),
    (gen_random_uuid(), adm, '요즘 청년, 요즘 문화', '축제', '요즘 청년, 요즘 문화', '2026-09-04', '2026-09-05', '서울', '서울특별시 마포구 어울마당로 68 (서교동)', null, null, 0, 0, null, false, false, false, false, '2026 청년문화주간 〈요즘 청년, 요즘 문화〉는 요즘 청년의 다양한 문화 활동과 관심사를 공유하고 교류하는 청년문화축제이다. 문화체육관광부가 주최하는 대표적인 청년행사로, 청년들이 현재의 문화와 사회를 바라보는 다양한 시선과 이야기를 문화 콘텐츠를 통해 만나볼 수 있도록 기획되었다. 공연, 강연, 체험, 커뮤니티 프로그램 등 다채로운 콘텐츠를 운영하며, 문화예술·여행·체육·라이프스타일 등 다양한 분야의 활동을 한자리에서 경험할 수 있는 장을 마련한다. 또한 청년 창작자, 문화 기획자, 브랜드, 커뮤니티가 함께 참여하며 청년문화의 흐름과 가치를 공유하고, 문화적 경험을 확장할 수 있는 기회를 제공한다. 청년이 만들고 즐기는 문화를 직접 경험하며 현재의 청년문화를 이해하고 공감할 수 있는 축제이다.', null, '070-7575-2353', 'open', 'info', 'approved', 'TourAPI', 'https://www.instagram.com/p/Db1wcLSgbjp/?img_index=1', '4097339', 37.5510972768, 126.9214939470, now()),
    (gen_random_uuid(), adm, '우리동네 문화아지트 : LH주택전시관 복합문화행사', '축제', '우리동네 문화아지트 : LH주택전시관 복합문화행사', '2026-08-06', '2026-08-22', '세종', '세종특별자치시 대평동 270-8', null, null, 0, 0, null, false, false, false, false, 'LH주택전시관의 유휴 공간이 도심 속 열린 복합문화공간으로 새롭게 태어난다. 무더운 여름 멀리 떠나지 않고도 시원하게 즐길 수 있는 도심 속 문화 바캉스를 선사한다. 매주 새로워지는 원데이 클래스, 지역 예술인들과 함께 만들어가는 공연 무대를 경험하며 단순히 관람하는 전시관을 넘어 일상 속 따듯한 휴식과 활력을 채워가는 특별한 행사이다.', null, '070-4266-7078', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://lhagit.com/
공식 인스타그램 https://www.instagram.com/lhagit_official/', '4091116', 36.4711413718, 127.2722214092, now()),
    (gen_random_uuid(), adm, '울산고래축제', '축제', '울산고래축제', '2026-10-15', '2026-10-18', '울산', '울산광역시 남구 장생포고래로 244 (매암동)', null, null, 0, 0, null, false, false, false, false, '제30회 울산고래축제는 울산광역시 남구가 주최하고 (재)고래문화재단이 주관하는 울산의 대표적인 문화관광 축제이다. 과거 포경의 중심지였던 장생포가 고래와 인간이 공존하는 생태도시로 전환된 역사를 배경으로 하며, 2026년 축제 30주년을 맞아 ''고래의 초대, 서른살 파티!''라는 주제와 ''함께할 고래''라는 슬로건 아래 개최된다. 본 축제는 2026년 10월 15일(목)부터 10월 18일(일)까지 4일간 장생포 고래문화특구 일원에서 진행된다. 주요 행사 공간은 메인무대인 고래극장을 비롯해 새우마당, 고래 체험마당, 버스킹존, 소상공인 전용 플리마켓존 등으로 구성된다. 방문객 접근 편의를 위해 태화강역 광장 일원에는 환승형 웰컴 게이트가 운영된다. 축제 기간 동안 개·폐막식, 스페셜 불꽃쇼, 주제공연, 300인 시민대합창, 고래 퍼레이드 등 다양한 대표 프로그램이 운영된다. 또한 고래나라 키즈페스타, 도전! 고래 라이더 챌린지, 소원고래 프로젝트, AR 및 반응형 미디어 체험(고래의 꿈 AI존), 고래가족 댄싱스타 및 가족가요제 등 전 세대가 참여할 수 있는 다채로운 문화 체험과 경연이 펼쳐진다. 이외에도 30주년 기념 아카이브 전시 ''고래의 시간''을 비롯해 먹거', null, '052-270-9324', 'open', 'info', 'approved', 'TourAPI', 'https://www.ulsanwhale.com/', '553263', 35.5031615190, 129.3808069186, now()),
    (gen_random_uuid(), adm, '웰컴투신관동', '축제', '웰컴투신관동', '2026-10-09', '2026-10-10', '충남', '충청남도 공주시 공주대학로 92 (신관동)', null, null, 0, 0, null, false, false, false, false, '웰컴투신관동은 공주시 신관동 대학로 일원에서 개최되는 청년문화 중심의 거리축제이다. 공주시와 공주문화관광재단이 추진하는 문화도시 조성사업의 일환으로, 신관동을 청년 문화거점으로 육성하고 지역 문화생태계와 상권 활성화를 도모하는 것을 목적으로 한다. 축제는 2022년부터 개최되어 거리공연 중심의 축제로 운영되어 왔으며, 버스킹 경연대회, 거리 퍼포먼스, 맥주페스타, 플리마켓, 체험 프로그램 등 다양한 콘텐츠를 단계적으로 확대해 왔다. 2025년에는 거리 이정표와 조형물 설치, 내비게이션 서비스 표기 등을 통해 ''웰컴투신관동'' 브랜드를 구축하였으며, 2026년에는 주민·상인·대학·청소년이 함께 참여하는 협력 운영체계를 기반으로 지속 가능한 축제 모델을 마련하는 것을 목표로 한다. 2026년 축제는 10월 9일부터 11일까지 신관동 대학로 일원에서 개최될 예정이며, 메인공연과 전국 단위 거리 퍼포먼스, 지역 청소년 및 청년 공연단 공연, 지역 상권 연계 프로그램, 지역화폐 쿠폰 이벤트 등이 운영된다. 또한 백제문화제와 연계하여 방문객의 체류를 유도하고 신관동 일대의 문화·경제 활성화를 도모하는 지역 대표 거리축제로 운영될 계획이다.', null, '041-852-1321', 'open', 'info', 'approved', 'TourAPI', null, '2877244', 36.4731467766, 127.1378517748, now()),
    (gen_random_uuid(), adm, '유성온날', '축제', '유성온날', '2026-08-14', '2026-12-11', '대전', '대전광역시 유성구 온천로 89 (봉명동)', null, null, 0, 0, null, false, false, false, false, '유성온천의 새로운 매력, 체류형 관광 프로그램 유성온날은 지친 일상 속에서 편안한 쉼표를 찾고 있는 이들에게 머물며 즐길 수 있는 특별한 휴식을 선사하는 관광 활성화 프로그램이다. 이번 행사는 계룡스파텔 잔디광장에서 아로마테라피와 다도가 결합되어 진정한 오감 릴랙스를 경험할 수 있는 유성 힐링요가 클래스와 선선한 바람을 맞으며 대형 스크린과 무선 헤드셋으로 몰입감 넘치는 영화를 감상하는 유성 온빛 야외 시네마로 다채롭게 채워져 있다. 또한 옛 대통령 별장인 비룡재 앞마당에서 성악, 클래식, 영화음악 등 세대를 아우르는 아름다운 선율을 즐길 수 있는 비룡재 작은 음악회, 갑천의 아름다운 물길을 따라 유성온천지구까지 달리며 건강과 활력을 챙기는 상시 참여형 갑천따라 런(Run) 챌린지가 함께 진행된다. 아울러 유성온천의 브랜드 ''유온''을 알리는 이동식 팝업 트럭과 함께 프로그램 참여자들에게 유성온천지구 내 호텔, 카페, 베이커리 등에서 사용할 수 있는 쿠폰이 제공되어 지역 상권에 따뜻한 활력을 더한다. 유성온천의 깨끗한 활력과 여유로운 하루를 선물하는 유성온날의 세부적인 일정 확인과 프로그램 신청은 공식 홈페이지(yu-on.com)에서 간편하게 진행할 수 있다.', null, '042-383-6855042-672-6857', 'open', 'info', 'approved', 'TourAPI', 'https://yu-on.com/', '4098134', 36.3548338694, 127.3478052748, now()),
    (gen_random_uuid(), adm, '음성명작페스티벌', '축제', '음성명작페스티벌', '2026-09-17', '2026-09-20', '충북', '충청북도 음성군 금왕읍 금빛공원2길 16', null, null, 0, 0, null, false, false, false, false, '음성명작페스티벌은 충청북도 음성군에서 개최되는 농산물 중심의 지역 축제이다. 축제는 음성군에서 생산되는 농산물과 지역 특산품을 홍보하고 판매하기 위해 운영되며, 농산물 전시·판매 행사, 먹거리 부스, 체험 프로그램, 문화공연 등 다양한 콘텐츠로 구성된다. 행사장에서는 지역 농산물을 직접 구매할 수 있으며, 농산물을 활용한 체험 프로그램도 함께 진행된다. 또한 생산자와 소비자가 직접 소통할 수 있는 기회를 제공하여 지역 농업 홍보와 농산물 소비 촉진에 기여하고 있다. 축제는 지역 주민과 관광객이 함께 참여하는 행사로 운영되며, 음성군의 농업 자원과 지역 특색을 소개하는 역할을 수행하고 있다. 이를 통해 지역 농산물의 인지도를 높이고 지역경제 활성화에 기여하는 지역 대표 축제로 자리하고 있다.', null, '043-873-0107', 'open', 'info', 'approved', 'TourAPI', null, '2699287', 36.9898919857, 127.5886600812, now()),
    (gen_random_uuid(), adm, '의정부지 상설 전통문화행사', '축제', '의정부지 상설 전통문화행사', '2026-04-11', '2026-10-31', '서울', '서울특별시 종로구 종로1길 45 (세종로)', null, null, 0, 0, null, false, false, false, false, '의정부지 상설 전통문화행사는 의정부지 역사유적광장을 찾는 시민 및 관광객들에게 우리의 전통문화를 널리 알려 역사도시 서울 이미지를 높이고, 평소에 경험하기 어려운 전통무예행사를 통해 문화 향유 기회를 제공하기 위해 서울시 주최로 진행되는 행사이다. 행사는 의정부를 포함한 육조거리에 주둔하였던 삼군부 군사들의 ''열무閱武'' 재현과 승경도 놀이 체험, 전통무예체험으로 구성된다.', null, '02-737-6444', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://cafe.naver.com/ujbj2025', '3497454', 37.574618321885374, 126.97838493180903, now()),
    (gen_random_uuid(), adm, '의좋은 형제 축제', '축제', '의좋은 형제 축제', '2026-11-07', '2026-11-08', '충남', '충청남도 예산군 대흥면 의좋은형제길 3', null, null, 0, 0, null, false, false, false, false, '의좋은형제축제는 충청남도 예산군 대흥면에 전해지는 의좋은형제 설화를 바탕으로 형제애와 나눔, 배려의 가치를 현대적으로 재해석한 가족 참여형 문화축제이다. 의좋은형제 동화 스토리텔링을 활용한 체험 프로그램을 비롯해 전통놀이, 가족 참여 이벤트, 문화공연, 지역 먹거리와 농특산물 장터 등을 운영하는 축제이며, 남녀노소가 참여할 수 있는 프로그램을 통해 지역의 역사와 문화를 체험하고 공동체의 가치를 이해할 수 있도록 구성된 행사이다. 축제 개최지 인근에는 예당호 출렁다리와 예당호 모노레일 등 예산군의 대표 관광시설이 위치하고 있으며. 지역 문화와 관광을 함께 경험할 수 있는 예산군 대표 문화관광축제이다.', null, '041-331-0619', 'open', 'info', 'approved', 'TourAPI', null, '1087020', 36.6065267555, 126.7921939309, now()),
    (gen_random_uuid(), adm, '인천 독서대전', '축제', '인천 독서대전', '2026-09-19', '2026-09-20', '인천', '인천광역시 제물포구 제물량로218번길 3 (해안동1가)', null, null, 0, 0, null, false, false, false, false, '2026 인천 독서대전은 책을 매개로 사람과 사람의 마음을 다정하게 이어주는 인천의 대표 책 문화 축제이다. ‘인천을 읽다, 마음을 잇다’라는 슬로건 아래 펼쳐지는 이번 행사는 2026년 9월 19일 토요일부터 9월 20일 일요일까지 이틀간 인천아트플랫폼에서 개최된다. 인천아트플랫폼 야외광장 메인무대에서는 설렘 가득한 개막식을 시작으로 오감을 자극하는 그림책 공연과 감성적인 버스킹이 펼쳐져 축제의 활기를 더한다. 야외광장 곳곳에는 지역 서점과 출판사가 참여해 숨은 보물 같은 책들을 소개하는 북마켓과 감성 포토존, 그리고 유쾌한 몰입감을 선사하는 BOOK탈출 등 다채로운 즐길 거리를 마련하였다. 아울러 실내공간에서는 작가와의 만남, 책수다, 지역 작가 강연을 비롯해 깊이 있는 독서토론과 포럼으로 풍성한 담론의 장을 마련한다. 마지막으로 전시실에서는 특별전시와 함께 도서관 및 유관기관이 준비한 체험 프로그램이 펼쳐져 찾아오는 시민들에게 깊은 문화적 울림과 추억을 선사할 예정이다.', null, '032-440-7873', 'open', 'info', 'approved', 'TourAPI', 'https://www.incheon.go.kr/incheon_rf/index', '2764526', 37.4727889015, 126.6206091372, now()),
    (gen_random_uuid(), adm, '인천 영화 주간 2026', '축제', '인천 영화 주간 2026', '2026-10-23', '2026-10-25', '인천', '인천광역시 연수구 청능대로 210 (동춘동)', null, null, 0, 0, null, false, false, false, false, '인천 영화 주간 2026은 한국 영화의 태동에 중추적인 역할을 해온 ''영화 도시, 인천''의 정체성을 다시 한번 인천 시민과 함꼐 되새길 수 있는 영화 축제이다. 축제는 10월 23일(금) 개막식을 시작으로 25일(일)까지 CGV인천연수에서 ''우리는 서로의 미래다''라는 부제 하에 미래를 꿈꾸며 달리는 우리들의 이야기를 담은 영화들과 온 가족이 함께 즐길 수 있는 부대 프로그램을 한 자리에 모았다. 자세한 행사 일정과 부대 프로그램 내용은 인천 영화 주간 홈페이지에서 순차적으로 공개된다.', null, '032-435-7172', 'open', 'info', 'approved', 'TourAPI', 'http://www.ifwk.co.kr/', '2872078', 37.4059981779, 126.6836220553, now()),
    (gen_random_uuid(), adm, '인천개항장 국가유산야행', '축제', '인천개항장 국가유산야행', '2026-10-09', '2026-10-11', '인천', '인천광역시 제물포구 신포로27번길 80 (관동1가)', null, null, 0, 0, null, false, false, false, false, '11번째로 개최되는 2026 인천 개항장 국가유산 야행은 제물포구 출범을 맞아 더욱 특별한 모습으로 시민과 관광객을 찾아간다. 인천 개항장 곳곳에서는 야설(夜說), 야경(夜景), 야로(夜路), 야사(夜史), 야화(夜畵), 야식(夜食), 야시(夜市), 야숙(夜宿) 등 8야(夜) 프로그램을 통해 개항장의 역사와 문화를 다채롭게 체험할 수 있다. 3일간 진행되는 이번 행사는 개막식을 시작으로 어린이부터 성인까지 모든 세대가 함께 즐길 수 있는 공연, 전시, 체험, 먹거리 프로그램 등 풍성한 콘텐츠를 선보인다. 개항장의 역사와 미식, 그리고 근대문화유산이 어우러진 특별한 야간 여행을 통해 이곳에서만 경험할 수 있는 색다른 추억을 선사할 예정이다. 또한 국가유산 야간 특별 개방과 숙박 프로모션을 운영하여 방문객들에게 더욱 풍성한 문화 향유 기회를 제공한다.', null, '1544-7056', 'open', 'info', 'approved', 'TourAPI', 'https://www.culturenight.co.kr/', '2408959', 37.4734688979, 126.6213512914, now()),
    (gen_random_uuid(), adm, '임실N치즈축제', '축제', '임실N치즈축제', '2026-10-08', '2026-10-11', '전북', '전북특별자치도 임실군 성수면 도인2길 50', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*1967년 임실로 선교활동을 하러 오신 지정환 신부님께서 산양 두 마리를 시작으로, 마을 청년들과 함께 수많은 시행착오와 고생 끝에 대한민국 최초로 치즈를 만들어낸 것을 기념하고, 지역경제 활성화와 치즈산업 발전을 위하여 매년 10월 초 임실치즈테마파크에서 임실군민과 방문객들이 함께 즐기는 대한민국 대표 문화관광축제로 거듭 발전해 나가는 임실N치즈축제이다.', null, '063-643-3900', 'open', 'info', 'approved', 'TourAPI', 'https://www.imsilfestival.com/', '2031318', 35.63156938109518, 127.30177597177955, now()),
    (gen_random_uuid(), adm, '장수한우랑사과랑축제', '축제', '장수한우랑사과랑축제', '2026-09-10', '2026-09-13', '전북', '전북특별자치도 장수군 장수읍 한누리로 378', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 장수는 전국 최고의 한우와 사과의 생산지이다. 장수한우랑사과랑축제는 한우와 사과를 중심 테마로 2007년 제1회 축제를 시작으로 2026년 제20회에 이르는 등 그 역사가 깊은 유서깊은 대한민국 최초의 레드컬러축제이다. 특히 2024년부터는 기존 한우와 사과의 농특산 단품에서 벗어나 장수 레드푸드(한우, 사과, 오미자, 토마토)로 그 품목을 확장했으며, 사과맥주, 사과소주, 사과빵, 오미자주 등 가공품의 영역으로 축제의 범위를 확장시켰으며 대한민국 최초의 레드컬러 축제에서 대한민국 최초의 레드푸드 축제로 그 영역을 넓혀 대한민국 대효 문화관광축제로 그 위상을 높이고 있다.', null, '063-350-2356', 'open', 'info', 'approved', 'TourAPI', 'https://www.jangsufestival.com/Jfest/', '763974', 35.6402165225, 127.5190644518, now()),
    (gen_random_uuid(), adm, '장항 맥문동 꽃 축제', '축제', '장항 맥문동 꽃 축제', '2026-08-28', '2026-08-30', '충남', '충청남도 서천군 장항읍 송림리 산58-48', null, null, 0, 0, null, false, false, false, false, '연간 약 100만 명이 방문하는 장항 송림자연휴양림은 약 28만㎡ 규모의 소나무숲에 600만 본의 맥문동을 식재하여 전국 최대 규모의 맥문동 군락을 이루고 있다. 장항 송림자연휴양림은 서해안과 인접한 해송림과 맥문동 군락이 함께 조성된 공간으로 산림휴양과 자연경관을 함께 즐길 수 있는 관광지이다. 장항 맥문동 꽃 축제는 이러한 자연자원을 활용하여 개최되는 축제로 맥문동 군락을 중심으로 문화공연, 체험 프로그램, 전시, 지역 농·특산물 판매, 먹거리 운영 등 다양한 프로그램을 진행한다. 또한 장항 송림의 자연경관과 관광자원을 활용한 문화·관광 콘텐츠를 운영하여 방문객에게 계절의 특색을 반영한 볼거리와 체험 기회를 제공하고 있으며, 자연과 문화가 조화를 이루는 지역 대표 축제로 운영되고 있다.', null, '041-950-4256', 'open', 'info', 'approved', 'TourAPI', 'http://mmdfestival.kr/', '3302552', 36.0184392979, 126.6655625042, now()),
    (gen_random_uuid(), adm, '전국해양스포츠제전', '축제', '전국해양스포츠제전', '2026-08-27', '2026-08-30', '경남', '경상남도 거제시 일운면 지세포해안로 15-44', null, null, 0, 0, null, false, false, false, false, '제18회 전국해양스포츠제전은 해양스포츠에 대한 국민의 관심을 높이고 해양레저문화의 저변 확대를 위해 개최되는 국내 최대 규모의 해양스포츠 종합축제이다. 해양수산부가 주최하고 개최도시 및 관계기관이 함께 운영하는 전국 단위 행사로, 매년 개최지를 달리하여 전국의 해양스포츠 선수와 동호인들이 참가하는 정식경기와 번외경기가 진행된다. 제18회 대회는 경상남도 거제시에서 개최되며, 요트, 카누, 수중·핀수영, 철인3종 등 다양한 종목의 경기가 펼쳐진다. 또한 바나나보트, 카약, SUP패들보드 등 해양레저 체험프로그램과 문화공연, 부대행사 등을 함께 운영하여 선수와 시민, 관광객 누구나 참여하고 즐길 수 있는 축제의 장을 제공하는 행사이다. 아름다운 거제의 해양환경을 배경으로 스포츠와 관광, 체험을 함께 즐길 수 있는 전국 규모의 해양축제이다.', null, '055-639-4182~6', 'open', 'info', 'approved', 'TourAPI', 'https://www.geoje.go.kr/marinesports/index.geoje', '581040', 34.8391873222, 128.7012355043, now()),
    (gen_random_uuid(), adm, '전주독서대전', '축제', '전주독서대전', '2026-09-11', '2026-09-13', '전북', '전북특별자치도 전주시 완산구 전주천동로 20 (교동)', null, null, 0, 0, null, false, false, false, false, '제9회 전주독서대전은 ''책 읽는 도시 글 쓰는 전주''와 ''달려라 책''이라는 슬로건 및 주제 아래 개최되는 전주시의 대표적인 책 축제이다. 이번 행사는 2026년 9월 11일 금요일부터 9월 13일 일요일까지 3일 동안 전주한벽문화관 및 완판본문화관 일원에서 진행된다. 전 세대가 함께 즐기는 축제를 만들기 위해 세대별 맞춤형 콘텐츠를 강화했으며, 기후 변화에 대비하여 친환경 실천형 축제 모델을 구축한 점이 주요 특징이다. 주요 프로그램으로 한벽문화관 공연장에서는 행사의 막을 올리는 개막식과 초청 강연, 퓨전국악 공연이 열린다. 전시실에서는 가족 단위 관람객이 직접 참여하는 ''가족독서골든벨'' 등의 경연이 준비되어 있다. 또한, 야외공연장에서는 어린이 공연, 태권도 공연, 마당창극이 활기차게 펼쳐지며 , 향교문화관 세미나실에서는 지역 작가 강연, 독서토론, 세미나, 독서 관련 워크숍이 마련되어 깊이 있는 문화 체험을 선사한다. 이 밖에도 전주천동로 일대에는 여러 서점과 출판사가 참여하는 북마켓과 다채로운 체험부스가 들어서고 , 야외마당에서는 시민참여전시 및 전주독서대전 특별전시가 열려 시민들에게 풍성한 볼거리와 즐길 거리를 제공한다.', null, '063-230-1858', 'open', 'info', 'approved', 'TourAPI', 'https://www.jjbook.kr/?mode=homepage', '1945450', 35.81227650714569, 127.15958408130633, now()),
    (gen_random_uuid(), adm, '전주한옥마을 전통연희 퍼레이드-노상놀이야', '축제', '전주한옥마을 전통연희 퍼레이드-노상놀이야', '2026-04-18', '2026-10-31', '전북', '전북특별자치도 전주시 완산구 태조로 44 (풍남동3가)', null, null, 0, 0, null, false, false, false, false, '거리에서 만나는 뜻밖의 전주민속. 전주의 상징인 전주기접놀이의 화려한 용깃발 퍼포먼스와 풍물놀이가 한가득 넘치는 공연이다. 해학 넘치는 단편 마당놀이, 거대한 용깃발 전주기접놀이 퍼포먼스 풍물연희와 전통기예를 한껏 보고 즐길 수 있다. 그리고 현장에서 전주 구전 노동요인 ''만두레 소리''를 함께 배워볼 수 있는 공연이다.', null, '- 063-236-1577 - 010-4348-3130', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.hapgood.kr/', '2547013', 35.814171786262136, 127.15002124718735, now()),
    (gen_random_uuid(), adm, '정관생태하천학습문화축제', '축제', '정관생태하천학습문화축제', '2026-10-16', '2026-10-18', '부산', '부산광역시 기장군 정관읍 구연3로 27', null, null, 0, 0, null, false, false, false, false, '아름다운 좌광천을 따라 자연의 가치를 배우고, 가족과 이웃이 함께 걸으며 사람과 사람의 마음을 잇는 축제다. 생태하천 체험을 통해 좌광천의 생태환경을 직접 만나고, 사생대회와 백일장을 통해 좌광천의 아름다움과 이야기를 펼친다. 방문객 모두가 참여하는 길놀이 퍼레이드와 가족걷기대회로 서로 교감하고 다양한 공연과 전시, 체험 프로그램은 지역의 문화와 주민의 일상을 축제의 무대로 확장한다. 특히 이번 축제는 좌광천 지방정원의 아름다움과 가치를 알리고, 자연과 사람이 함께하는 새로운 지역문화를 소개하며 자연을 배우고, 사람을 잇고, 문화를 즐기며, 기장의 미래를 함께 만들어가는 3일간의 축제이다.', null, '051-727-6444', 'open', 'info', 'approved', 'TourAPI', 'https://blog.naver.com/jg_sangtae', '3007256', 35.3221880006, 129.1818961362, now()),
    (gen_random_uuid(), adm, '정선아리랑제', '축제', '정선아리랑제', '2026-10-01', '2026-10-04', '강원', '강원특별자치도 정선군 정선읍 봉양리', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*정선아리랑제는 대한민국 대표 소리인 정선아리랑의 역사와 문화적 가치 및 전통을 계승·발전시키기 위해 개최하는 정선군의 대표 문화관광축제이다. 유네스코 인류무형문화유산으로 등재된 아리랑의 가치를 널리 알리고, 전통과 현대가 조화를 이루는 공연, 퍼레이드, 체험 프로그램, 전시, 문화예술 행사 등 다양한 콘텐츠를 통해 모든 세대가 함께 즐길 수 있는 축제로 운영한다. 또한 지역 주민이 직접 기획과 운영에 참여하는 주민참여형 축제를 지향하며, 지역의 문화자원과 관광자원을 연계한 프로그램을 통해 지역경제 활성화와 관광객 유치에도 기여하고 있다. 아리랑의 문화적 가치와 정선만의 고유한 전통을 바탕으로 대한민국을 대표하는 아리랑 문화축제로 자리매김하고, 세계인이 함께 공감하는 글로벌 문화관광축제로 발전해 나가고자 한다.', null, '033-560-3013~5', 'open', 'info', 'approved', 'TourAPI', 'https://arirangfestival.kr/', '506895', 37.3771987522, 128.6658996682, now()),
    (gen_random_uuid(), adm, '정읍 구절초 꽃축제', '축제', '정읍 구절초 꽃축제', '2026-10-08', '2026-10-18', '전북', '전북특별자치도 정읍시 산내면 청정로 926-89', null, null, 0, 0, null, false, false, false, false, '정읍 구절초 축제는 청정한 산골하천과 천혜의 자연경관을 자랑하는 솔숲을 배경으로 한 동양 최대의 150,000㎡ 구절초꽃 동산에서 가을의 절정기인 매년 10월에 개최된다. 솔향기와 은은한 꽃향기가 어우러진 산책로를 걸으며 자연 속에서 온전한 치유와 위로를 느낄 수 있다. 안개가 자욱하게 피어오르는 새벽녘이나 따스한 가을 햇살이 내리쬐는 오후 모두 사진작가들이 빼놓지 않고 즐겨찾는 대한민국 최고의 출사명소이기도 하다. 자연이 인간에게 주는 최고의 선물인 순백의 구절초와 함께 지역 향토자원을 테마로 한 다채로운 체험 프로그램, 정읍의 풍성한 지역 농특산물도 가득해 가을의 정취를 오감으로 만끽하기에 안성맞춤이다.', null, '063-539-5697', 'open', 'info', 'approved', 'TourAPI', 'https://www.jeongeup.go.kr/culture/index.jeongeup?menuCd=DOM_000000602004002001', '1105347', 35.5544107679, 127.0193690153, now()),
    (gen_random_uuid(), adm, '정조대왕 능행차 공동재현', '축제', '정조대왕 능행차 공동재현', '2026-10-04', '2026-10-04', '서울', '서울특별시 종로구 사직로 161 (세종로)', null, null, 0, 0, null, false, false, false, false, '백성과 함께한 행복한 8일, 시민의 축제로 다가온다. 조선 역사상 가장 성대한 축제이자 백성과 성군이 함께한 동행! 2026년 정조대왕의 능행차 길을 따라 『원행을묘정리의궤』 속 정조의 뜻을 되새긴다. 1795년 정조는 어머니 혜경궁 홍씨의 회갑을 기념하여 수원 화성으로 행차했다. 정조의 8일 간의 여정은 단순한 왕의 이동이 아닌 백성과 즐거운 기억을 공유한 역사적인 사건이었다. 정조의 애민정신은 『원행을묘정리의궤』에 담겨 널리 배포되었다. 2026년, 정조대왕의 정신을 계승하고 백성의 행복한 기억이 시민의 행복한 기억으로 재현된다. 정조대왕 능행차 공동재현은 서울시, 경기도, 수원시, 화성시가 협력해 ''을묘년 화성원행''의 원형을 현대에 화려하게 재현하는 축제이다.', null, '서울 02-786-0610수원 031-5191-2367화성 070-4202-1017', 'open', 'info', 'approved', 'TourAPI', null, '2554814', 37.5760307000, 126.9767218661, now()),
    (gen_random_uuid(), adm, '정조효문화제', '축제', '정조효문화제', '2026-10-03', '2026-10-04', '경기', '경기도 화성시 장조1로 34', null, null, 0, 0, null, false, false, false, false, '정조효공원 일원에서 펼쳐지는 정조효문화제는 역사적 가치와 가족 친화적인 요소를 함께 담은 화성특례시의 대표 역사문화축제이다. 다양한 공연과 전통 체험 프로그램을 즐길 수 있으며, 특히 정조대왕이 아버지 사도세자의 묘를 조선 최고 길지로 이름난 화성시 융릉으로 이전하는 대서사시를 재현한 현륭원 천원은 정조대왕의 지극한 효심을 상징적으로 보여주는 대표 프로그램이다. 또한 10월 4일에는 1795 을묘원행을 재현하는 정조대왕 능행차가 동탄 센트럴파크에서 출발해 장대한 행렬을 펼치며 전통과 현대가 어우러진 다채로운 볼거리를 선사한다. 천하의 명당, 효의 도시 "화성특례시"에서 펼쳐지는 본 축제는 역사와 문화, 그리고 가족이 함께하는 특별한 시간을 제공할 것이다.', null, '031-290-4679', 'open', 'info', 'approved', 'TourAPI', 'http://www.정조효문화제.com', '1725929', 37.2066442866, 126.9950637750, now()),
    (gen_random_uuid(), adm, '제11회 울산울주세계산악영화제', '축제', '제11회 울산울주세계산악영화제', '2026-09-18', '2026-09-22', '울산', '울산광역시 울주군 상북면 알프스온천5길 103-8', null, null, 0, 0, null, false, false, false, false, '울산울주세계산악영화제는 산악 영화를 중심으로 자연과 인간의 삶을 조명하는 영화제이다. 시련과 극복, 도전과 실패, 갈등과 공존 등 인간 존재가 자연과 더불어 살아가는 다양한 방식을 담아내며, 그 과정을 통해 삶에 대한 깊은 성찰을 이끌어내는 것이 특징이다. 영남알프스라는 독특한 지리적 배경과 자연환경을 적극 반영한 프로그램과 운영 방식을 통해 영화제의 정체성을 공고히 하며, 단순한 영화 상영의 장을 넘어 산악인과 영화인, 관객이 함께 어우러지는 교류의 장으로 기능한다. 또한 국내외 다양한 산악영화와 다큐멘터리를 소개하며, 장르와 형식의 경계를 확장하는 영화들을 적극적으로 발굴·상영하는 데 힘쓰고 있으며, 해마다 참신한 시선의 작품들을 통해 영화제의 깊이를 더하고 있다.', null, '052-248-6451', 'open', 'info', 'approved', 'TourAPI', 'https://www.umff.kr/kor/', '2555932', 35.5564659757, 129.0679770709, now()),
    (gen_random_uuid(), adm, '제14회 부산국제코미디페스티벌', '축제', '제14회 부산국제코미디페스티벌', '2026-08-21', '2026-08-30', '부산', '부산광역시 해운대구 APEC로 55 (우동)', null, null, 0, 0, null, false, false, false, false, '부산국제코미디페스티벌(BICF)은 2013년 아시아 최초로 시작된 국제 코미디 페스티벌로, 국내외 최고의 코미디 아티스트들이 함께하는 대한민국 대표 코미디 축제이다. 부산 전역을 무대로 펼쳐지는 다채로운 공연과 특별 프로그램을 통해 세대와 국경을 넘어 모두가 함께 웃고 즐기는 문화의 장을 만들어가고 있다. 코미디 공연을 넘어 K-코미디의 가치를 세계에 알리고, 새로운 코미디 콘텐츠와 인재를 발굴하며 지속 가능한 코미디 산업의 미래를 그려가고 있다. 올 여름, 부산국제코미디페스티벌에서 가장 유쾌한 웃음의 순간을 만나볼 수 있다.', null, '051-916-8828', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://www.bicf.kr/', '1840830', 35.1687048508, 129.1354937071, now()),
    (gen_random_uuid(), adm, '제14회 부산국제항만컨퍼런스', '축제', '제14회 부산국제항만컨퍼런스', '2026-09-15', '2026-09-16', '부산', '부산광역시 동구 충장대로 206 (초량동)', null, null, 0, 0, null, false, false, false, false, '부산국제항만컨퍼런스(BIPC)는 급변하는 글로벌 해운·물류 환경 속에서 항만의 미래를 함께 모색하고 국제협력을 강화하기 위해 마련된 컨퍼런스이다. 세계 주요 항만과 해운, 물류 분야의 전문가들이 한자리에 모여 글로벌 컨테이너 해운시장 전망을 공유하고, 항만 운영과 관련된 주요 이슈와 대응 전략을 논의한다. 특히 디 지털 전환, 탈탄소화, 공급망 변화 등 항만 산업이 직면한 핵심 과제를 중심으로 각국 항만의 경험과 성과를 공유하며 실질적인 협력 방안을 모색하는 장으로 기능 하고 있다. 이를 통해 BIPC는 글로벌 항만 간 교류와 협력의 네트워크를 확대하고, 지속가능한 항만 산업 발전과 미래 경쟁력 확보를 위한 국제 협력 플랫폼으로 자리매김하고 있다.', null, '051-711-0069', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://bipc.kr/', '4033328', 35.1175129767356, 129.049383440539, now()),
    (gen_random_uuid(), adm, '제24회 동강국제사진제', '축제', '제24회 동강국제사진제', '2026-07-17', '2026-10-11', '강원', '강원특별자치도 영월군 영월읍 영월로 1909-10', null, null, 0, 0, null, false, false, false, false, '올해로 제24회를 맞이하는 동강국제사진제는 국내외 사진작가와 강원도민, 영월군민, 사진 애호가들이 함께 만들어 가는 대한민국 대표 사진 행사로 7월 17일(금)부터 10월 11일(일)까지 동강사진박물관을 비롯한 영월군 일원에서 개최된다. 올해 에서는 올해 동강 사진상 수상자 임안나 작가의 작품을 감상할 수 있다. 또한, 전 세계 작가들이 온라인으로 참여한 에 선정된 19명의 작품도 만나볼 수 있다. 이 외에도 , , , , , , 등 전 세계 사진인들이 기다리는 연례행사인만큼 다채로운 전시가 아름다운 강원도 영월군 일대에서 진행된다.', null, '033-375-6372', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://www.dgphotofestival.com', '606549', 37.1819133415, 128.4614563757, now()),
    (gen_random_uuid(), adm, '제38회 춘천인형극제', '축제', '제38회 춘천인형극제', '2026-09-10', '2026-09-16', '강원', '강원특별자치도 춘천시 영서로 3017 (사농동)', null, null, 0, 0, null, false, false, false, false, '제38회 춘천인형극제는 아시아 최대 규모의 인형극 축제이다. 춘천세계인형극제에서는 세계 각국의 최정상 아티스트와 인형극단이 참가하며, 춘천인형극장을 중심으로 춘천시 전역에서 인형극 공연과 대규모 퍼레이드, 아트마켓이 진행될 예정이다. 인형극 공연 외에도 인형극 장르의 확산과 발전을 위한 체험, 전시, 워크숍 등 다채로운 프로그램이 진행된다. 세계 인형극계의 흐름을 조망할 수 잇는 국제 교류의 장이자, 모든 세대를 아우르는 문화예술축제로 자리매김하고 있다.', null, '033-242-8452', 'open', 'info', 'approved', 'TourAPI', 'www.cocobau.com', '573459', 37.9209224402, 127.7201075840, now()),
    (gen_random_uuid(), adm, '제67회 한국민속예술제', '축제', '제67회 한국민속예술제', '2026-09-18', '2026-09-20', '강원', '강원특별자치도 평창군 진부면 오대천로 1958-27', null, null, 0, 0, null, false, false, false, false, '아름다운 자연경관을 품은 평창에서 ''제67회 한국민속예술제''가 펼쳐져 우리 전통문화 예술의 가치를 드높일 예정이다. ''한국민속예술제''는 민속예술의 보존과 전승을 위해 1958년부터 현재까지 지역별 민속 종목을 발굴하며 이어져 온 최장수 축제이다. 67년 역사를 가진 한국민속예술제를 동계올림픽 개최도시 평창에서 개최 함으로써, 문화 관광 거점으로 평창의 브랜드 가치를 높이고 지역 경제 활성화에 기여하고자 한다. 평창의 아름다운 대자연 속에서 우리 전통민속예술 문화의 위대한 향연을 함께 즐겨볼 수 있는 축제이다.', null, '033-330-2856', 'open', 'info', 'approved', 'TourAPI', 'https:///www.pc.go.kr/', '140880', 37.6308685360, 128.5567707084, now()),
    (gen_random_uuid(), adm, '제7회 고창농악 꽃대림축제', '축제', '제7회 고창농악 꽃대림축제', '2026-08-28', '2026-08-30', '전북', '전북특별자치도 고창군 성송면 향산1길 106', null, null, 0, 0, null, false, false, false, false, '고창농악 꽃대림축제는 전북특별자치도 무형유산 고창농악의 꽃대림굿에 담긴 공종체 정신을 창의적으로 계승하는 공연예술축제이다. 꽃대림굿은 음력 칠석 무렵 마을 사람들이 함께 굿을 벌이며 그동안의 노고를 풀고 남은 한 해의 풍요를 기원하던 공동체 의례이다. 축제는 고창농악의 풍장굿·문굿·판굿 등 전통연희 공연을 중심으로 음악, 소리, 연희 등 다양한 장르의 초청공연과 관람객 참여 프로그램을 운영하는 행사이다. 또한 전통예술 공연과 체험·마켓·전시·학술·교류 프로그램을 함께 구성하여 관람객, 문화예술인, 지역민, 농악 애호가와 연구자가 한 공간에서 교류하도록 마련한 축제이다. 제7회 축제는 2026년 8월 28일부터 30일까지 3일간 고창농악전수관 일원에서 개최되며, 고창농악의 전승 기반을 확장하고 지역의 전통 문화를 동시대 공연예술과 연결하는 것을 목적으로 하는 지역 기반 문화예술축제이다.', null, '063-562-2044', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://www.gochanggut.kr/
공식 인스타그램 https://www.instagram.com/kkotdaerim_festival/', '3339982', 35.3835095686, 126.6404331137, now()),
    (gen_random_uuid(), adm, '제8회 대전특수영상영화제', '축제', '제8회 대전특수영상영화제', '2026-09-17', '2026-09-19', '대전', '대전광역시 서구 둔산대로 135 (만년동)', null, null, 0, 0, null, false, false, false, false, '대전특수영상영화제는 대전의 특수영상 산업 인프라를 기반으로 창작, 기술, 산업 분야를 연계하여 운영하는 국내 유일의 특수영상 특화 영화제이다. 주요 프로그램은 국내 영상 콘텐츠의 특수영상 성과를 조명하는 DFX OTT어워즈[OverTheTop], 특수영상 작품 상영과 관객과의 대화로 구성된 DFX 스크리닝, AI·VFX 기술과 관련 산업 동향을 공유하는 DFX 테크쇼, 특수영상 장편 프로젝트를 발굴하는 DFX 피치이다. DFX OTT어워즈는 국내 OTT 콘텐츠를 대상으로 특수영상 기술과 표현 성과를 조명하는 시상 프로그램이다. DFX 스크리닝은 특수영상이 활용된 작품을 상영하고 감독, 배우, 제작진과 관객이 작품에 관해 대화를 나누는 프로그램이다. DFX 테크쇼는 AI와 VFX 등 영상 제작 기술 및 산업 현황을 소개하는 프로그램이다. DFX 피치는 특수영상 장편 프로젝트를 발굴하고 제작 및 산업 관계자와의 연계 기회를 제공하는 프로그램이다. 대전특수영상영화제는 창작자, 기술 전문가, 산업 관계자와 관객이 참여하여 특수영상 분야의 성과와 산업 동향을 공유하는 문화예술 행사이다.', null, '042-259-8063', 'open', 'info', 'approved', 'TourAPI', 'https://dfx.dicia.or.kr/', '3352431', 36.3666138000, 127.3837588314, now()),
    (gen_random_uuid(), adm, '제8회 예천국제스마트폰영화제', '축제', '제8회 예천국제스마트폰영화제', '2026-10-09', '2026-10-11', '경북', '경상북도 예천군 호명읍 산합리 73', null, null, 0, 0, null, false, false, false, false, '예천국제스마트폰영화제는 올해 8회째 개최되는 영화제로서, 스마트폰으로 촬영된 영화 및 영상을 공모받아 심사를 거쳐 수상작을 선정하고 10월 9일(토) 현장에서 시상식 진행과 함께 주민들도 함께 즐길 수 있는 영화축제이다. 천혜의 자연 환경의 도시 경상북도 예천에서 2019년 첫 발을 내딛은 예천국제스마트폰 영화제 (이하 YISFF)는 예천을 상징하고, 경북을 넘어 전국에서 스마트폰 영화제로서 대표적인 영화제이다. ‘누구나’가지고 있는 스마트폰을 가지고 시대의 발자취에 맞추어 영화를 제작함으로서 신선하고 새로운 바람을 불러 일으켰다.', null, '054-655-8082', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://yisff.kr/', '2622679', 36.5715986793, 128.4887513731, now()),
    (gen_random_uuid(), adm, '지상군페스티벌', '축제', '지상군페스티벌', '2026-10-01', '2026-10-05', '충남', '충청남도 계룡시 신도안면 석계리', null, null, 0, 0, null, false, false, false, false, '2026년 지상군페스티벌은 육군이 주최하는 대한민국 최대 군 문화축제로 국민들에게 육군의 발전과 미래정책을 홍보하고 군에 대한 신뢰도 증진과 긍정적 가치 확산 등 공익 목적의 비영리 행사이며, 10. 1.(목)부터 10. 5.(월)까지 5일간 충남 계룡대 활주로에서 개최된다. 올해로 22회를 맞이한 2026년 지상군페스티벌에서는 ''국민의 일상을 지키는 대한민국 육군''을 주제로 최신 한·미 전투장비 전시 및 탑승체험, Army TIGER+와 드론봇 시범을 실시하고, AI·첨단과학기술 기반 전투체계와 변화하는 육군의 다양한 모습 등을 육군정책홍보관에서 시범·전시·체험을 통해 직접 확인할 수 있다. 또한 군악·의장대 공연, 태권도 시범, 군사경찰 MC 기동시범, 육군공연팀 퍼포먼스, 로드 퍼레이드 등 다채로운 고품격 군 문화공연을 만날 수 있다.', null, '042-550-5310~2', 'open', 'info', 'approved', 'TourAPI', 'https://armyfest.or.kr', '229054', 36.3085210000, 127.2359510000, now()),
    (gen_random_uuid(), adm, '직지문화축제', '축제', '직지문화축제', '2026-09-04', '2026-09-06', '충북', '충청북도 청주시 흥덕구 직지대로 713 (운천동)', null, null, 0, 0, null, false, false, false, false, '2026 직지문화축제는 유네스코 세계기록유산에 등재된 ''직지''의 가치를 대중화하고, 인류 인쇄기술의 혁신과 지식 공유의 상징인 직지의 의미를 새롭게 조명하는 축제다. ''직지, 시간의 문을 열다''를 주제로, ''직지''의 기록유산 등재일인 9월 4일을 기념하여 직지가 지닌 역사적 가치와 문화적 의미를 시민과 관광객이 함께 공감할 수 있도록 구성하였다. 누구나 보고, 즐기고, 머무를 수 있는 전시, 체험, 공연, 강연 프로그램을 통해 직지를 보다 쉽고 흥미롭게 만나고, 시간의 흐름 속에서 살아 숨 쉬는 기록문화의 가치를 경험할 수 있도록 구성하였다.', null, '043-201-3666', 'open', 'info', 'approved', 'TourAPI', 'https://jikjifestival.com/', '3305165', 36.6429424201, 127.4722198763, now()),
    (gen_random_uuid(), adm, '진안홍삼축제', '축제', '진안홍삼축제', '2026-09-18', '2026-09-20', '전북', '전북특별자치도 진안군 진안읍 마이산로 160', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*대한민국 유일의 홍삼특구 진안군에서 펼쳐지는 진안홍삼축제는 가을의 정취 속에서 건강과 즐거움을 동시에 만나는 특별한 축제이다. 깊은 향과 뛰어난 품질을 자랑하는 진안홍삼을 직접 맛보고, 홍삼을 보다 친근하고 재미있게 경험할 수 있도록 다양한 이색 먹거리와 체험 프로그램이 마련되어 있어 아이부터 어른까지 모두 색다른 즐거움을 느낄 수 있다. 진안홍삼빙고, 홍삼파워존, 홍삼바비큐, 야외족욕체험 등 오직 이곳에서만 즐길 수 있는 참여형 콘텐츠가 가득하며, 전통공연과 초청가수 공연 등 다채로운 무대와 이벤트가 어우러져 축제의 열기를 더한다. 특히 엄격한 기준을 통해 품질이 인증된 진안 홍삼 제품을 합리적인 가격에 만나볼 수 있어 건강한 먹거리와 특별한 추억을 함께 담아갈 수 있는 가을 대표 축제이다.', null, '063-430-2392', 'open', 'info', 'approved', 'TourAPI', 'https://www.jinan.go.kr/festival/', '1718060', 35.7730393521, 127.4162448689, now()),
    (gen_random_uuid(), adm, '진주 국가유산야행', '축제', '진주 국가유산야행', '2026-09-03', '2026-09-06', '경남', '경상남도 진주시 망경남길 30 (망경동)', null, null, 0, 0, null, false, false, false, false, '국가유산 야행은 국가유산의 역사·문화적 가치를 야간 프로그램을 통해 체험할 수 있도록 기획된 야간 문화유산 활용 축제이다. 진주 국가유산 야행은 ‘암행어사’를 주제로 진주성과 원도심 일원에서 개최되며, 국가유산과 지역의 역사·문화를 다양한 방식으로 체험할 수 있도록 운영된다. 축제는 야경, 공연, 전시, 체험, 문화해설, 야시장 등 ’진주 8야(夜)’를 중심으로 구성되어 있으며, 방문객이 국가유산을 야간에도 안전하고 흥미롭게 향유할 수 있도록 기획된 행사이다. 진주의 대표 국가유산과 지역 문화자원을 연계한 다양한 콘텐츠를 통해 지역의 역사성과 문화적 정체성을 널리 알리고, 시민과 관광객에게 풍성한 문화 향유 기회를 제공하는 것을 목적으로 하는 축제이다.', null, '055-795-3200', 'open', 'info', 'approved', 'TourAPI', null, '2843904', 35.1807435788, 128.0847734101, now()),
    (gen_random_uuid(), adm, '진주남강유등축제', '축제', '진주남강유등축제', '2026-10-03', '2026-10-18', '경남', '경상남도 진주시 남강로 626 (본성동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.* 진주남강유등축제는 임진왜란 진주성 전투에서 왜군이 강을 건너는 것을 저지하고, 가족에게 안부를 전하기 위해 남강에 유등을 띄운 데에서 유래되었다. 문화체육관광부 지정 대한민국 대표 축제였음과 동시에 5년 연속 대한민국 글로벌 육성 축제로 선정된 해외로 진출하는 명품 축제이다.', null, '055-755-9111,761-9111', 'open', 'info', 'approved', 'TourAPI', 'https://yudeung.com/', '506926', 35.1904937892, 128.0800831631, now()),
    (gen_random_uuid(), adm, '진주의 수호자들', '축제', '진주의 수호자들', '2026-08-14', '2026-09-06', '경남', '경상남도 진주시 강남로 287 (강남동)', null, null, 0, 0, null, false, false, false, false, '진주의 수호자들은 진주성과 역사대첩문화공원 일원을 배경으로 한 미션투어 콘텐츠이다. 참가자는 별도의 앱 설치 없이 웹기반 플랫폼에 접속하며, 진주성 및 역사대첩문화공원 내 지정된 장소를 이동하며 미션을 수행한다. 행사 콘텐츠는 총 3편의 시리즈로 구성되어 있다. 1편은 진주성의 역사적 사건을 바탕으로 한 서사 중심 미션이며, 2편은 세명의 등장인물을 중심으로 전개되는 추리 형식의 미션이다. 3편은 판타지 콘셉트로 설계되어 있으며, 국문 영문판을 운영할 예정이다. 단서를 모아 최종 문장을 완성하는 방식으로 진행된다. 행사는 국가유산미디어아트 진주성 및 국가유산 문화재 야행기간과 연계해 야간에 진행되며, 진주성 내 조명과 유등이 밝혀진 야경을 배경으로 체험할 수 있다. 참가는 진주성 공북문 안 잔디광장에서 시작되며 참가자는 미션 완료 시 기념품을 수령할 수 있다.', null, '0507-1393-7113', 'open', 'info', 'approved', 'TourAPI', null, '3542294', 35.1879338891, 128.0858237357, now()),
    (gen_random_uuid(), adm, '창경궁 야연', '축제', '창경궁 야연', '2026-09-24', '2026-10-04', '서울', '서울특별시 종로구 창경궁로 185 (와룡동)', null, null, 0, 0, null, false, false, false, false, '"창경궁 야연"은 효명세자가 아버지 순조에게 올렸던 지극한 효심의 연회를 현대적으로 재해석한 가족 친화적 야간 궁중 연회 프로그램이다. 참가자는 조선시대 문무백관과 외명부가 되어 궁중 복식을 갖춰 입고 연회에 참여하여, 동반한 가족과 함께 궁중 병과를 맛보고 전통 공연 관람과 다채로운 전통 체험 프로그램에 참여한다. 2026년 은 상반기 5월 7일(목)-5월 17일(일) / 하반기 9월 24일(목)-10월 4일(일) 총 20일간 진행된다. 어버이날과 추석 연휴, 사랑하는 가족들과 고궁의 밤을 거닐며 아름다운 시간을 기록할 수 있다.', null, '1522-2295', 'open', 'info', 'approved', 'TourAPI', 'https://www.kh.or.kr/short/h0Tn', '2818138', 37.5788809216, 126.9964488355, now()),
    (gen_random_uuid(), adm, '천안흥타령춤축제', '축제', '천안흥타령춤축제', '2026-10-01', '2026-10-05', '충남', '충청남도 천안시 서북구 번영로 208 (백석동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*천안흥타령춤축제는 참여와 소통을 중시하는 축제로, 관람객이 단순히 보는 데서 그치지 않고 직접 춤을 배우고 공연에 참여할수 있도록 기획한 축제이다. 또한, 지역 농특산물 홍보와 중소기업 제품 판매 부스 등을 운영해 지역경제 활성화에 기여한다.', null, '1566-0155', 'open', 'info', 'approved', 'TourAPI', 'https://cheonanfestival.com/ko/index.php', '506935', 36.819443033583454, 127.11145203614497, now()),
    (gen_random_uuid(), adm, '청백리의 집, 오늘을 비추다', '축제', '청백리의 집, 오늘을 비추다', '2026-09-05', '2026-11-07', '경기', '경기도 광명시 오리로347번길 5-6 (소하동)', null, null, 0, 0, null, false, false, false, false, '오리이원익 종택 및 관감당(충현박물관)에서 전통 문화 행사 ''청백리의 집, 오늘을 비추다''를 운영한다. 조선의 대표 청백리 오리 이원익 대감의 청렴한 삶과 인조 임금이 하사했던 관감당을 주제로 연극 관람과 오디 염색체험, 관감당 탐구생활 등 어린이와 가족이 함께 즐길 다채로운 프로그램으로 구성되었다. 9월 5일, 9월 19일, 10월 17일, 11월 7일 충현박물관에서 운영된다. ※ 상세 내용 확인 및 예약은 공식 홈페이지 참조 요망', null, '02-6015-2592', 'open', 'info', 'approved', 'TourAPI', null, '4056606', 37.4339272970, 126.8777258264, now()),
    (gen_random_uuid(), adm, '청송백자축제', '축제', '청송백자축제', '2026-09-11', '2026-09-13', '경북', '경상북도 청송군 주왕산면 청송백자로 36', null, null, 0, 0, null, false, false, false, false, '청송백자는 500여 년의 시간 동안 청송의 흙과 물, 불, 그리고 장인의 손끝을 통해 이어져 온 소중한 문화유산이다. 청송의 자연에서 얻은 재료에 장인의 정성과 기다림이 더해져 하나의 백자로 완성되는 과정에는 오랜 시간 이어져 온 청송만의 삶과 이야기가 담겨 있는 문화자산이다. 「역사 500년, 미래 500년 천년의 약속」은 지난 500년의 시간을 소중히 기억하고, 그 가치를 앞으로의 500년에도 이어가고자 하는 마음을 담은 슬로건이다. 지나온 전통을 바탕으로 오늘의 청송백자를 새롭게 바라보고, 다음 세대에게 그 아름다움과 의미를 자연스럽게 전하고자 하는 약속이다. 2026 청송백자축제는 청송백자가 걸어온 시간을 돌아보고, 지금의 청송백자를 만나며, 앞으로 이어질 새로운 이야기를 함께 만들어가는 축제이다. 전시와 판매, 체험과 다양한 문화 프로그램을 통해 청송백자의 아름다움을 가까이에서 만나고, 흙과 불, 장인의 손끝에서 탄생하는 백자의 특별한 가치를 경험하는 자리이다. 500년의 역사는 과거에 머무는 시간이 아니라 오늘을 지나 미래로 이어지는 시간이다. 이번 축제가 청송백자의 지나온 500년을 기억하고 앞으로의 500년을 함께 그려보는 시간이 되며, 마침내', null, '054-874-0101', 'open', 'info', 'approved', 'TourAPI', 'https://www.cctf.or.kr/', '3301271', 36.3781103102, 129.1086046475, now()),
    (gen_random_uuid(), adm, '청송사과축제', '축제', '청송사과축제', '2026-11-04', '2026-11-08', '경북', '경상북도 청송군 청송읍 월막리', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*청송사과축제는 경상북도 청송군에서 매년 가을에 개최되는 지역 대표 축제이다. 2025년 축제는 ‘청송~ 다시 푸르게, 다시 붉게’라는 주제로 진행되는 행사이다. 축제에서는 사과 풍선 속 황금사과를 찾는 ‘황금사과를 찾아라’, 사과 선별을 통해 로또 번호를 추첨하는 ‘도전-사과 선별 로또’, 만보기를 활용한 ‘꿀잼-사과난타’ 등 다양한 현장 참여형 프로그램이 운영된다. 이와 함께 청송사과 직거래 장터, 지역 농특산물 판매장, 문화공연이 함께 구성되어 있어 방문객이 청송사과의 우수성을 직접 체험할 수 있는 축제이다.', null, '054-870-6237', 'open', 'info', 'approved', 'TourAPI', 'https://csapplefestival.kr/', '921212', 36.432486, 129.055726, now()),
    (gen_random_uuid(), adm, '청양 고추 구기자 축제', '축제', '청양 고추 구기자 축제', '2026-09-11', '2026-09-13', '충남', '충청남도 청양군 청양읍 은천동길 16-6', null, null, 0, 0, null, false, false, false, false, '가을의 시작과 함께 열리는 청양 고추 구기자 축제는 전 연령층이 함께 할 수 있는 참여형 축제로, 청양군을 대표하는 농특산물인 고추, 구기자를 활용한 오감 만족 체험 프로그램과 여경래 셰프 초청 쿠킹쇼 및 전국 고등학생 요리 서바이벌, 대형 겉절이 담기, 구기자 떡 모자이크, 맵부심의 제왕 등 먹거리 볼거리쇼를 볼 수 있으며, 특화음식 체험마을존, 맵주&맵부심 도립대존, 푸드코트 식당존 등 다양한 먹거리 부스도 마련되어 있다. 특히, 캐치! 티니핑 공연과 포토존, 목재문화체험존, 청양이 친구들(청양이, 청초롱, 청홍이)로 확대하여 신설된 키즈존을 구성하여 가족과 어린이를 대상으로 한 프로그램을 확대하였으며, 송가인, 박지현, 박현빈, 솔지 등 가수 초청 공연, 청양의 흥을 알려라 및 주민자치 공연 등을 통해 볼거리 및 즐길거리를 풍성하게 준비한 충청남도 대표 지역축제이다.', null, '041-940-4852', 'open', 'info', 'approved', 'TourAPI', 'https://xn--539an7vgta625d.com/_festa', '1086249', 36.4459739924, 126.7975393964, now()),
    (gen_random_uuid(), adm, '청원생명축제', '축제', '청원생명축제', '2026-10-02', '2026-10-11', '충북', '충청북도 청주시 청원구 오창읍 미래지로 99', null, null, 0, 0, null, false, false, false, false, '청원생명축제는 2008년부터 친환경을 테마로 구성된 대표적인 축제이다. 순수자연으로 더욱 빛나는 명품농산물인 청원생명브랜드를 홍보하고, 테마가 있는 전시와 다양한 체험행사 및 문화공연을 통해 관람객의 다양한 볼거리를 제공하며, 자라나는 학생들에게는 농업의 현재와 미래, 다양한 문화를 느낄 수 있는 교육의 장을 마련하고자 노력하고 있다. 또한 지역 농업인과 소비자가 직접 만나 소통할 수 있는 교류의 장을 조성하여 지역 농산물의 우수성과 친환경 농업의 가치를 널리 알리고 있으며, 가족 단위 관람객이 함께 참여할 수 있는 다채로운 프로그램 운영을 통해 농업과 농촌에 대한 이해를 높이고 있다. 아울러 건강한 먹거리와 지속가능한 농업의 중요성을 체험할 수 있는 기회를 제공함으로써 농업의 공익적 가치를 확산하고, 지역경제 활성화와 농촌문화 발전에 기여하는 청주시 대표 축제로 자리매김하고 있다.', null, '043-201-0254', 'open', 'info', 'approved', 'TourAPI', null, '613316', 36.7332002013, 127.4073645226, now()),
    (gen_random_uuid(), adm, '춘천막국수닭갈비축제', '축제', '춘천막국수닭갈비축제', '2026-10-14', '2026-10-18', '강원', '강원 춘천시 온의동 586', null, null, 0, 0, null, false, false, false, false, '대한민국 대표 미식도시 춘천에서 2026 춘천막국수닭갈비축제가 개최된다. 춘천을 대표하는 두 가지 향토음식인 막국수와 닭갈비를 중심으로, 맛과 문화, 관광이 어우러지는 특별한 미식축제이다. 지역 대표 음식점과 다양한 먹거리, 로컬푸드, 체험 프로그램, 문화공연, 시민 참여 이벤트 등 남녀노소 모두가 함께 즐길 수 있는 풍성한 콘텐츠를 만나볼 수 있다. 아름다운 공지천을 따라 펼쳐지는 축제장에서 춘천의 맛과 멋, 그리고 따뜻한 정취를 오감으로 경험할 수 있다. 가족, 친구, 연인과 함께 특별한 추억을 만들 수 있는 이번 축제는 지역의 음식문화와 관광자원을 널리 알리고, 대한민국을 대표하는 K-미식축제로 한 걸음 더 도약하고자 한다. 춘천에서만 만날 수 있는 특별한 맛과 즐거움을 경험하며 잊지 못할 가을의 추억을 만들 수 있다.', null, '070-7576-1657', 'open', 'info', 'approved', 'TourAPI', 'https://mdfestival26.imweb.me/', '1230074', 37.8697694000, 127.7219052000, now()),
    (gen_random_uuid(), adm, '춘천애니토이페스티벌', '축제', '춘천애니토이페스티벌', '2026-10-03', '2026-10-05', '강원', '강원특별자치도 춘천시 서면 박사로 854', null, null, 0, 0, null, false, false, false, false, '2026 춘천애니토이페스티벌은 애니메이션, 캐릭터, 아트토이, 피규어, 굿즈, 크리에이터 콘텐츠 등 다양한 서브컬처 및 문화 상품이 한자리에 모이는 복합 문화 행사이다. 본 행사는 강원특별자치도 춘천시 서면 박사로에 위치한 애니메이션박물관 일대에서 개최된다. 공식 행사 일정은 2026년 10월 3일 토요일부터 10월 5일 월요일까지 총 3일간으로 예정되어 있다. 이 행사는 관련 산업의 주요 브랜드와 창작 아티스트, 그리고 팬과 컬렉터가 오프라인 공간에 모여 최신 트렌드를 교류하고 관련 시장의 동향을 파악할 수 있는 장을 형성한다. 행사장은 단순 관람 목적의 전시를 넘어, 참가자들이 각자의 취향과 관심사를 실질적으로 공유할 수 있는 여러 세부 프로그램으로 구성되어 있다. 애니메이션 및 완구 산업의 현재를 확인할 수 있는 기업 및 개인 전시 부스, 산업 관련 체험 프로그램, 그리고 브랜드별 상품을 직접 만나볼 수 있는 판매전이 동시에 진행된다.또한, 이 페스티벌은 지역을 대표하는 가족 참여형 행사로서 남녀노소 전 세대가 관람하고 참여할 수 있는 제반 시설과 프로그램 인프라를 갖추고 있다. 방문객은 현장에서 다수 아티스트의 창작물과 주요 브랜드의 신제품 실물을 직', null, '070-8672-0156', 'open', 'info', 'approved', 'TourAPI', 'https://anitoyfestival.co.kr/', '293131', 37.8929758061, 127.6918201030, now()),
    (gen_random_uuid(), adm, '충북 괴산 우주특별시：별별탐사대', '축제', '충북 괴산 우주특별시：별별탐사대', '2026-04-30', '2026-12-06', '충북', '충청북도 괴산군 괴산읍 충민로검승1길 6', null, null, 0, 0, null, false, false, false, false, '충북 괴산 우주특별시：별별탐사대 전시는 ''우주 생태''라는 상상 속 환경을 바탕으로 과일과 식물의 새로운 가능성을 탐험하는 체험형 전시이다. 보고, 만지고, 움직이며 이어지는 다양한 경험 속에서 아이들은 질문하고 상상하며 자신만의 이야기를 만들어 갈 수 있다. 보호자는 아이의 탐험에 함께하는 안내자가 되어 질문을 나누고 전시를 더욱 깊이 있게 경험할 수 있다.', null, '043-299-9314', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://wondermedium.com/woojoo-goesan/', '4062805', 36.8053358842675, 127.824356316082, now()),
    (gen_random_uuid(), adm, '충주 국가유산야행', '축제', '충주 국가유산야행', '2026-09-04', '2026-09-06', '충북', '충청북도 충주시 관아1길 21 (성내동)', null, null, 0, 0, null, false, false, false, false, '2026 충주 국가유산 야행은 충주시 관아공원 일원(충주시 관아1길 21)에서 2026년 9월 4일부터 9월 6일까지 3일간 개최되는 행사로 과거 중원경의 위상과 조선시대 충청감영의 상징성을 관아공원의 청녕헌, 제금당 등 문화유산과 연계하여 재해석함으로써 충주의 역사적 가치를 전달하고 원도심 지역 경제에 활력을 불어넣고자 기획되었다. 축제는 야경(夜景), 야로(夜路), 야사(夜史), 야화(夜畫), 야설(夜說), 야식(夜食), 야숙(夜宿), 야시(夜市)의 8가지 야간 테마(8야) 프로그램으로 다채롭게 구성된다. 밤빛으로 물든 관아공원의 야경 속에서 역사 거리 탐방과 각종 문화유산 체험활동이 펼쳐지며 장인과의 만남 및 역사 인물·민담을 활용한 마당극과 전통 공연이 행사장 곳곳에서 운영된다. 아울러 옛 장터를 재현한 먹거리존과 지역 공예 작가들이 참여하는 프리마켓, 관내 숙박시설 및 상권과 연계한 프로그램이 함께 어우러져 관람객들에게 중원문화의 멋과 야간 관광의 색다른 즐거움을 제공한다.', null, '043-723-1350', 'open', 'info', 'approved', 'TourAPI', null, '2738394', 36.9703324959, 127.9358523482, now()),
    (gen_random_uuid(), adm, '치악산 한우축제', '축제', '치악산 한우축제', '2026-10-22', '2026-10-25', '강원', '강원특별자치도 원주시 단구로 170', null, null, 0, 0, null, false, false, false, false, '치악산한우 축제는 원주축산농협에서 주관하는 지역 대표 축제로, 원주의 농업 가치와 삼토사상 중심 바탕으로 남녀노소 누구나 함께 참여하는 화합의 축제이다. 청정 자연속에서 자란 명품 치악산한우의 우수성을 널리 알리고, 지역 농축산물과 다양한 먹거리 체험 프로그램과 신선한 먹거리를 직접 구입할 수 있으며, 가족 단위 방문객을 위한 체험 프로그램도 같이 운영된다. 또한 치악산한우 시식과 할인 판매, 지역 예술 공연과 어울린 무대 행사가 마련되어 풍성한 볼거리를 제공한다. 제 12회 치악산 한우 축제는 삼토사상의 중심 원주에서 시민과 함께하는 축제이다.', null, '033-744-6801', 'open', 'info', 'approved', 'TourAPI', 'https://wonjulc.com/page/view.php/10sub5', '4046174', 37.3350920000, 127.9455500000, now()),
    (gen_random_uuid(), adm, '칠곡낙동강평화축제', '축제', '칠곡낙동강평화축제', '2026-10-15', '2026-10-18', '경북', '경상북도 칠곡군 석적읍 중지리', null, null, 0, 0, null, false, false, false, false, '칠곡낙동강평화축제는 한국전쟁 당시 최후의 방어선이었던 낙동강 전투의 역사적 의미를 기리고, 호국 정신을 되새기기 위한 축제다. 1950년 평범한 사람들이 목숨을 걸고 지켜낸 대한민국의 가치를 기억하고, 나라를 지킨 이들에게 감사를 전하기 위해 다양한 프로그램을 운영한다. 2026년 열세번째로 개최하는 축제에서는 평화를 주제로 즐길 수 있는 공연, 참여 체험, 먹거리 프로그램을 마련하는 한편 ''소년, 소년병이 되다''이라는 슬로건 아래 호국의 상징으로 조명된 학도병 서사 이면에서 상대적으로 주목받지 못했던 어린 소년병들의 존재를 알리고 그들의 넋을 기리기 위한 프로그램을 함께 기획하여 축제의 역사적, 평화적 메세지를 더욱 강화하였다.', null, '054-979-3215', 'open', 'info', 'approved', 'TourAPI', null, '1844150', 36.0184680000, 128.4010940000, now()),
    (gen_random_uuid(), adm, '컨템포러리 아티스트 프로젝트 《이완 - 나는 쓴다》', '축제', '컨템포러리 아티스트 프로젝트 《이완 - 나는 쓴다》', '2026-07-17', '2026-09-27', '서울', '서울특별시 서초구 남부순환로 2406 (서초동)', null, null, 0, 0, null, false, false, false, false, '예술의전당이 제작한 컨템포러리 아티스트 프로젝트 《이완 - 나는 쓴다》 전시는 한국 전통 서예를 현대미술의 언어로 새롭게 해석한 전시이다. 작가 이완은 붓과 먹을 바탕으로 문자, 이미지, 회화, 전각을 결합해 서예의 새로운 가능성을 탐구한다. 아름다운 글씨를 감상하는 데 그치지 않고, ''왜 쓰는가''라는 질문을 통해 쓰기가 자신을 표현하는 예술이 될 수 있음을 보여준다. 전통과 현대가 만나는 새로운 서예의 가능성을 경험할 수 있는 전시이다.', null, '02-580-1655', 'open', 'info', 'approved', 'TourAPI', 'https://www.sac.or.kr/', '4094595', 37.4802401962, 127.0142152392, now()),
    (gen_random_uuid(), adm, '컬처라운지 경기, 장(場)', '축제', '컬처라운지 경기, 장(場)', '2026-04-18', '2026-12-15', '경기', '경기도 수원시 영통구 도청로 지하36 (이의동)', null, null, 0, 0, null, false, false, false, false, '경기도 컬처라운지 ''경기, 장''은 경기도의 로컬 콘텐츠를 한자리에서 소개하는 복합 문화 공간이다. 해당 공간은 방문객이 지역 기반 콘텐츠를 직접 경험할 수 있도록 체험형 중심 구조로 구서오디어 있다. ''로컬레이더''는 개인의 취향에 따라 경기 여행을 설계할 수 있는 맞춤형 체험 프로그램이다. ''경기도자상점''은 도자공예치험과 차 시음을 통해 휴식과 체험을 동시에 제공하는 공간이다. 전체적으로 전시, 체험, 공연 기능이 결합된 복합 문화 플랫폼 형태이며, 방문객 참여를 기반으로 운영되는 것이 특징이다.', null, '031-259-4724', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/gyeonggi_jang', '4058556', 37.2879129895568, 127.054491044714, now()),
    (gen_random_uuid(), adm, '트레저헌터 in 진안', '축제', '트레저헌터 in 진안', '2026-08-29', '2026-08-29', '전북', '전북특별자치도 진안군 진안읍 외사양길 16-19', null, null, 0, 0, null, false, false, false, false, '트레저헌터 in 진안은 진안군 7개 권역을 탐험하며 숨겨진 여의주를 찾고, 로컬바이브 앱을 통해 QR 인증을 완료하는 지역탐방형 체험 축제이다. 참가자는 패스 구매 후 마이산 북부, 마이산 탑사, 용담댐, 주천생태공원, 고원화목원, 부귀 메타세쿼이사, 수선루 등 진안의 주요 관광지를 방문하며 현장 미션에 참여할 수 있다. 행사기간 중 매주 토요일에는 권역별 여의주가 공개되며, 일반 여의주 발견자는 현장 리워드를 받을 수 있고 빛나는 여의주 획득자는 최종 결선에 참여할 수 있다. 본 행사는 진안의 자연, 역사, 관광자원을 보물찾기 방식으로 연결하여 방문객의 체류와 권역별 탐방을 유도하는 행사이다.', null, '031-8035-3141', 'open', 'info', 'approved', 'TourAPI', 'https://localvibehub.com/treasure-hunter', '4096371', 35.7769952225, 127.4158812719, now()),
    (gen_random_uuid(), adm, '팔색찬란', '축제', '팔색찬란', '2026-06-04', '2026-12-31', '서울', '서울특별시 종로구 효자로13길 45 (효자동)', null, null, 0, 0, null, false, false, false, false, '문화체육관광부는 이달부터 12월까지 청와대 사랑채 1층에서 특별전 ''팔색찬란 : K로 가득한 지역''을 개최한다. 이번 전시는 ''우리가 이야기하는 케이(K)의 뿌리는 무엇인가?''라는 질문에서 출발한다. 한국의 역사와 문화예술, 지역 고유의 문화자산이 K-콘텐츠로 이어지고 확장되는 과정을 지역 콘텐츠 전시와 미디어아트를 통해 입체적으로 선보인다. 특히 대한민국의 다양한 지역에 축적된 문화적 자산이 오늘날 K-컬처의 기반이 됐음을 조명하는 데 초점을 맞췄다.', null, '02-723-0300', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://cwdsarangchae.kr', '4082595', 37.5825448754, 126.9730592833, now()),
    (gen_random_uuid(), adm, '페인터즈', '축제', '페인터즈', '2022-11-01', '2026-12-31', '서울', '서울특별시 중구 정동길 3 (정동)', null, null, 0, 0, null, false, false, false, false, '페인터즈는 관객과 소통하는 주요 매개가 춤과 연기, 미술이라는 점에서 독창성을 가지고 있다. 여기에 새로운 영상 기법인 프로젝션 맵핑까지 더해져 관객에게 다채로운 시각 경험을 선사한다. 무대에서 선보이는 주요 장면으로는 빛으로 조각하는 라이트 카빙, 4개의 화판에 담아내는 액션페인팅, 반전의 묘미가 돋보이는 더스트 드로잉, 놀라운 속도로 그려나가는 스피드 드로잉,물 위에 그려지는 마블링, 빛으로 담아내는 야광드로잉 등이 있다.', null, '02-766-7848', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.thepainters.co.kr/
공식 인스타그램 https://www.instagram.com/painters_official/', '3481597', 37.5681732680976, 126.969976113229, now()),
    (gen_random_uuid(), adm, '평창농악·산골푸드축제', '축제', '평창농악·산골푸드축제', '2026-09-18', '2026-09-20', '강원', '강원특별자치도 평창군 용평면 갈정지길 7', null, null, 0, 0, null, false, false, false, false, '평창농악산골푸드축제는 강원의 대표 무형문화재인 평창 둔전평 농악이 전승되고 있는 평창군 용평면에서 해마다 개최되고 있으며, 남녀노소 함께 어울려 즐길 수 있어 많은 관광객이 찾는 축제로 발전하고 있다. [평창愛 맛있는 소리! 신명나는 평창농악의 맛있는 산골푸드]를 주제로 펼쳐지는 올해 축제는 올해로 6회째를 맞는 만큼 평창 둔전평 농악의 신명나는 공연과 체험을 중심으로 지역의 산골푸드를 접목해 더욱 다양하고 풍성한 즐길거리를 선보인다. 항아리바베큐와 꼬치구이체험, 장터국밥을 비롯한 다양한 먹거리 프로그램과 전통문화체험, 마당극 등 다양한 공연과 체험들을 다채롭게 구성해 놓았으며 농악의 신명나는 리듬과 평창의 맛있고 넉넉한 인심이 어우러진 모두에게 잊지 못할 평창의 가을 정취를 선사하고 있다.', null, '033-332-4333', 'open', 'info', 'approved', 'TourAPI', '홈페이지 url', '2997256', 37.5893940252, 128.4160246596, now()),
    (gen_random_uuid(), adm, '평창효석문화제', '축제', '평창효석문화제', '2026-09-04', '2026-09-13', '강원', '강원특별자치도 평창군 봉평면 이효석길 157', null, null, 0, 0, null, false, false, false, false, '*하기 축제 먹거리 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*평창효석문화제는 강원특별자치도 평창군 봉평면 일원에서 개최되는 대한민국 대표 가을 문화 관광 축제이다. 이 축제는 1999년에 처음 시작되어 매년 9월경에 열리며, 현대 한국 단편소설의 수작인 가산 이효석의 소설 《메밀꽃 필 무렵》의 실제 무대인 봉평면을 배경으로 한다. 축제장의 주된 경관은 소금을 뿌린 듯 흐드러지게 피어나는 하얀 메밀꽃밭이며, 방문객들은 소설 속 배경인 봉평의 자연경관을 직접 체험할 수 있다. 주요 행사 내용으로는 이효석 문학을 기리는 문학 행사와 더불어 전통 민속놀이, 향토 음식 먹거리 장터 운영, 그리고 지역 주민과 예술가들이 참여하는 다양한 문화 예술 공연이 포함된다. 이를 통해 평창효석문화제는 지역의 문학적 자산과 농촌의 전통문화를 알리는 동시에 지역 경제 활성화에 기여하고 있다.', null, '033-335-2323', 'open', 'info', 'approved', 'TourAPI', 'https://www.hyoseok.com/', '507635', 37.6140421019, 128.3715953535, now()),
    (gen_random_uuid(), adm, '포항 10미(味) 야장축제', '축제', '포항 10미(味) 야장축제', '2026-09-04', '2026-09-05', '경북', '경상북도 포항시 남구 오천읍 문덕로 35', null, null, 0, 0, null, false, false, false, false, '포항 10미(味) 야장축제는 포항의 대표 미식인 포항 10미(味)와 골목상권을 연계하여 문덕 헬로부대거리 일원에서 개최되는 도심형 야간 미식 축제이다. 지역 경제 활성화와 상생을 목적으로 추진되며, 2026년 9월 4일부터 5일까지 이틀간 감성 알전구 조명 아래 펼쳐진다. 개막식과 축하공연을 시작으로 포항 10미(味) 및 야장 먹거리 부스, 미식 홍보관, DJ 클럽파티, 고고(GOGO)노래자랑, 소상공인 플리마켓, 어린이 소방차 체험존 등 전 세대가 즐길 수 있는 다채로운 콘텐츠를 운영한다. 친환경 다회용기를 활용한 클린 축제로 진행되며, 먹거리와 공연, 체험이 어우러진 특화된 야간 상웍 놯성화 및 포항의 미식 도시 브랜드 가치 제고를 목표로 추진된다. * 포항 10미(味) : 모리국수, 포항물회, 등푸른막회, 과메기, 대게, 소머리곰탕, 포항초산채비빔밥, 영일대조개구이, 아구탕, 해신탕', null, '054-270-8282', 'open', 'info', 'approved', 'TourAPI', null, '4100347', 35.9595568634, 129.4032436899, now()),
    (gen_random_uuid(), adm, '포항국제불빛축제', '축제', '포항국제불빛축제', '2026-11-20', '2026-11-22', '경북', '경상북도 포항시 북구 해안로 48 (항구동)', null, null, 0, 0, null, false, false, false, false, '*하기 축제 내용은 전년도(2025년) 축제 내용으로, 2026년도 축제 내용은 업데이트 중에 있습니다.*‘불과 빛의 도시’ 포항에서는 해마다 대표적인 문화관광축제 ''포항국제불빛축제''가 열린다. 포항국제불빛축제는 세계적인 철강 도시 포항을 상징하는 ‘빛’과 뜨거운 용광로를 상징하는 ‘불’의 이미지를 테마로 지난 2004년 포항시민의 날을 기념해 불꽃쇼를 개최한 것이 시작이다. 이후 국제규모 축제행사로 확대됐고 해외 유명한 불꽃팀들이 매년 참가하고 있다. 축제콘텐츠도 단순한 ‘불꽃’중심에서 탈피, 제작 공연과 불빛 퍼레이드 등 산업과 문화적 요소를 융합해 다채롭게 펼치는 화합의 축제이다.', null, '054-289-7852~5', 'open', 'info', 'approved', 'TourAPI', 'https://festival.phcf.or.kr/fireWorks/intro.do', '588175', 36.0530051077193, 129.377594275323, now()),
    (gen_random_uuid(), adm, '포항치맥페스티벌', '축제', '포항치맥페스티벌', '2026-08-21', '2026-08-22', '서울', '포항시 북구 두호동 1015-6번지', null, null, 0, 0, null, false, false, false, false, '포항 치맥페스티벌은 포항의 대표 관광자원인 영일대 해상누각 일원에서 개최되는 여름 축제이다. 본 축제는 지역경제 활성화와 관광객 유치를 목적으로 추진되며, 남녀노소 전 연령층이 함께 참여할 수 있는 참여형 문화축제로 운영된다. 축제는 2026년 8월 21일부터 22일까지 이틀간 진행되며, 기념식을 비롯해 초청공연, 시민 참여형 공연, EDM 파티, 노래경연대회, 체험 프로그램 등 다양한 콘텐츠를 운영한다. 행사장에는 치킨과 맥주 판매존을 중심으로 워터체험존, 아트체험존, 이벤트존 등이 조성되며, 먹거리와 공연, 체험, 해양관광을 연계한 체류형 관광콘텐츠를 제공한다. 또한 시민과 관광객이 직접 참여하는 치맥스타K, 치맥왕 선발대회, 영수증 럭키드로우 등 참여형 프로그램을 운영하여 현장 참여를 확대한다. 축제는 야간 공연과 EDM 프로그램을 통해 영일대의 야간 관광 활성화를 도모하고, 포항의 여름 관광 콘텐츠를 확충하여 도시관광 경쟁력과 도시 브랜드 가치를 높이는 것을 목표로 한다. 이를 통해 포항을 대표하는 여름 관광축제로 육성하고, 지역 상권과 관광산업의 활성화에 기여하는 축제로 추진된다.', null, '053-567-4497', 'open', 'info', 'approved', 'TourAPI', null, '4097059', 36.0623406000, 129.3820196000, now()),
    (gen_random_uuid(), adm, '한강 다리밑 영화관', '축제', '한강 다리밑 영화관', '2026-08-08', '2026-08-22', '서울', '서울특별시 영등포구 여의동로 330 (여의도동)', null, null, 0, 0, null, false, false, false, false, '「2026 한강 다리밑 영화관」이 8월 8일(토)부터 8월 22일(토)까지 3주간 매주 토요일 저녁 8시에 여의도 한강공원 원효대교, 뚝섬한강공원 청담대교, 광나루한강공원 천호대교 하부 3개소에서 개최된다. 특히 「한강 다리밑 영화관」은 무더운 여름 한강에서 만날 수 있는 가장 시원하고도 이색적인 야외 영화관으로 영화를 사랑하는 누구나 무료로 관람할 수 있으며 행사 당일 현장을 방문하면 된다. 저녁 7시 부터는 사전 행사로 진행한 한강 추억 사진, 영상 공모 이벤트 「한강 모먼트」의 수상작을 스크린에서 만나볼 수 있다.', null, '02-120', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://hangang.seoul.go.kr/', '3517184', 37.5263478533, 126.9335951931, now()),
    (gen_random_uuid(), adm, '한강야경투어', '축제', '한강야경투어', '2026-05-01', '2026-09-19', '서울', '서울특별시 영등포구 여의동로 330 (여의도동)', null, null, 0, 0, null, false, false, false, false, '''한강야경투어''는 한강에서 낭만도 즐기고 전문 해설사로부터 한강 야경에 얽힌 숨겨진 이야기도 들어볼 수 있는 휴식형 투어 프로그램으로, 한강 반포달빛길(반포한강공원)과 여의별빛길(여의도한강공원) 2개의 코스로 구성되어 있다. ''반포달빛길''은 반포한강공원의 ''서래섬'', ''세빛섬'', ''달빛무지개분수'', ''잠수교''를 걸으며 각기 다른 야간의 매력을 즐길 수 있다. 반면 ''여의별빛길''은 ''한강예술공원'', ''마포대교'', ''물빛무대'', ''물빛광장''을 걸으며 여의도 한강공원의 야경을 즐길 수 있다.', null, '02-6953-9239', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://visit-hangang.seoul.kr/', '3116066', 37.526347853294425, 126.93359519306124, now()),
    (gen_random_uuid(), adm, '한강역사탐방', '축제', '한강역사탐방', '2026-04-20', '2026-11-15', '서울', '서울특별시 영등포구 여의동로 330 (여의도동)', null, null, 0, 0, null, false, false, false, false, '''한강역사탐방'' 프로그램은 한강 경관 및 역사·문화자원을 감상·공유하는 매력적인 관광해설과 교육을 제공하여 시민 및 관광객에게 한강변을 체험·감상한다. 또한 체험활동 등 시민들이 능동적으로 참여하고 직접 경험할 수 있는 다양한 콘텐츠를 개발하여 일상 속에서 즐기는 한강 역사문화를 활성화하고자 한다. 탐방객은 정해진 코스를 따라 한강 유역 및 인근 문화유산을 거닐며 한강해설사의 해설을 듣는다. 한강역사탐방은 총 16개 코스로 운영되며, 탐방객은 해당 코스를 거닐며 해당 코스와 관련된 한강의 역사를 탐방할 수 있다.', null, '02-6953-9239', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 visit-hangang.seoul.kr', '3111722', 37.526347853294425, 126.93359519306124, now()),
    (gen_random_uuid(), adm, '한여름 밤의 신정호 별빛축제', '축제', '한여름 밤의 신정호 별빛축제', '2026-09-05', '2026-09-06', '충남', '충청남도 아산시 신정로 616 (방축동)', null, null, 0, 0, null, false, false, false, false, '제29회 한여름밤의 신정호 별빛축제는 아산시의 대표 관광자원인 신정호를 배경으로 개최되는 야간 문화관광축제로, 자연경관과 문화예술 콘텐츠를 연계하여 시민과 관광객에게 다양한 문화 향유 기회를 제공하고 지역 관광 활성화를 도모하는 축제이다. 축제는 공연, 체험, 전시, 별자리 관측, 영화 상영 등 남녀노소가 함께 참여할 수 있는 프로그램으로 구성되며, 신정호의 수변 경관을 활용한 야간 볼거리와 휴식 공간을 조성하여 여름밤의 정취를 즐길 수 있도록 운영된다. 또한 지역 예술인에게 공연 기회를 제공하는 별빛콘서트와 다양한 체험 프로그램을 통해 지역 문화예술의 참여 기반을 확대하고, 천체망원경을 활용한 별자리 관측 및 전문 해설 프로그램 등 차별화된 콘텐츠를 운영하여 교육적·문화적 가치를 함께 제공한다. 가족 단위 방문객부터 청년, 관광객까지 다양한 계층이 함께 즐길 수 있는 복합 문화축제로서 지역 문화예술 활성화와 관광객 유치, 지역경제 활성화에 기여하는 것을 목적으로 한다.', null, '041-534-2634', 'open', 'info', 'approved', 'TourAPI', 'https://culture.asan.go.kr/', '1689321', 36.7715293389, 126.9839038561, now()),
    (gen_random_uuid(), adm, '함양산삼축제', '축제', '함양산삼축제', '2026-10-07', '2026-10-11', '경남', '경상남도 함양군 함양읍 필봉산길 49', null, null, 0, 0, null, false, false, false, false, '500m 이상의 게르마늄 토양에서 자란 함양산삼은 치밀하고 단단한 조직, 높은 사포닌 함량 등 매우 뛰어난 품질로 명품산삼으로 불리고 있으며, 전국 최초 산삼이력제를 실시하여 소비자가 생산정보를 정확히 알 수 있고, 산양삼지킴이 활동으로 지속적인 품질 관리를 하여 명품산삼으로써 차별화된 특성을 유지하고 있다. 천년의 신비가 살아 숨 쉬는 천연기념물 제154호 함양 상림공원에서 잊혀져가는 산삼과 심마니의 역사문화 등을 계승할 수 있는 콘텐츠를 활용한 축제 프로그램 운영으로 산삼의 의미와 역사적 가치를 재조명 하고, 군의 대표 브랜드인 청정임산물 산삼의 이미지를 활용하여 지역농특산물의 판로를 확대, 산림·문화·관광 자원과의 연계 프로그램 운영으로 지역경제를 활성화하고자 마련되었으며, 매년 9~10월경 개최되고 있다.', null, '055-960-6432', 'open', 'info', 'approved', 'TourAPI', 'www.sansamfestival.or.kr', '563458', 35.5236812446, 127.7218508587, now()),
    (gen_random_uuid(), adm, '함평모악산 꽃무릇축제', '축제', '함평모악산 꽃무릇축제', '2026-09-16', '2026-09-20', '서울', '전남광주통합특별시 함평군 해보면 용천사길 209', null, null, 0, 0, null, false, false, false, false, '제27회 함평 모악산 꽃무릇축제는 붉게 물든 꽃무릇 군락지와 모악산의 아름다운 자연환경을 배경으로 개최된다. 이번 축제는 꽃무릇과 숲이 어우러진 가을 풍경 속에서 일상의 피로를 내려놓고 여유를 즐길 수 있는 감성 치유형 축제로 마련된다. 특히 모악산 숲길을 활용한 명상·산림 치유 프로그램과 꽃무릇 및 지역의 특색을 살린 다채로운 콘텐츠를 통해 자연 속에서 걷고 쉬며 몸과 마음을 재충전할 수 있는 특별하고 소중한 가을의 시간을 선사한다. 자연과 사람, 쉼이 어우러지는 축제를 통해 모악산 꽃무릇의 아름다움과 생태적 가치를 널리 알릴 예정이다.', null, '061-320-2247', 'open', 'info', 'approved', 'TourAPI', 'www.hpftf.or.kr', '1700219', 35.1835271438, 126.5452777706, now()),
    (gen_random_uuid(), adm, '홍성남당항 대하축제', '축제', '홍성남당항 대하축제', '2026-09-04', '2026-11-08', '충남', '충청남도 홍성군 서부면 남당항로213번길 1-1', null, null, 0, 0, null, false, false, false, false, '제31회 홍성남당항 대하축제는 천수만의 청정한 바다와 싱싱한 제철 대하를 만날 수 있는 홍성의 대표적인 가을 먹거리 축제이다. 서해안 대표 미식 관광지인 남당항에서 열리는 이번 축제에서는 제철을 맞아 살이 통통하게 오른 대하를 맛볼 수 있으며, 남당항의 아름다운 바다 풍경과 함께 다양한 공연과 즐길거리를 만나볼 수 있다. 2026년 축제는 9월 4일부터 11월 8일까지 남당항 일원에서 개최되며, 9월 4일부터 6일까지 개막공연이 펼쳐지고 9월 25일부터 26일까지는 추석공연이 마련된다. 개막 및 추석공연에는 빈예서, 박현빈을 비롯해 장도현, 유도현, 김정아, 김서연 등 다양한 출연진이 참여해 축제의 흥을 더한다. 남당항은 대하뿐 아니라 전어 등 다양한 수산물이 풍부한 천수만의 대표적인 관광지로, 축제 기간 신선한 해산물과 지역의 먹거리를 즐기며 서해의 아름다운 낙조까지 함께 감상할 수 있다. 가족, 연인, 친구와 함께 먹거리와 공연, 바다 풍경을 한자리에서 즐길 수 있는 홍성의 대표 가을 축제이다.', null, '010-5433-8196', 'open', 'info', 'approved', 'TourAPI', 'https://blog.naver.com/official_namdang', '140911', 36.5388309018, 126.4722831164, now()),
    (gen_random_uuid(), adm, '화성송산포도축제', '축제', '화성송산포도축제', '2026-09-05', '2026-09-06', '경기', '경기도 화성시 만세구 서신면 영종로안길 24', null, null, 0, 0, null, false, false, false, false, '화성송산포도축제는 화성시의 대표 농특산물인 송산포도를 주제로 개최되는 지역 농특산물 축제이다. 2026년 제12회 화성송산포도축제는 9월 5일부터 9월 6일까지 이틀간 화성에코팜테마파크 일원에서 개최되는 행사이다. 축제에서는 지역에서 생산된 포도를 직접 만나볼 수 있으며, 포도를 활용한 다양한 체험 프로그램과 포도밟기 체험 등이 운영될 예정이다. 또한 방문객이 참여하고 관람할 수 있는 공연 프로그램과 포도 관련 체험·홍보 부스, 다양한 먹거리를 판매하는 부스가 함께 운영될 예정이다. 생산농가와 소비자가 축제 현장에서 만나 화성 지역에서 생산되는 포도와 농특산물을 접할 수 있는 행사로, 화성송산포도와 지역 농업을 알리기 위해 마련된 축제이다.', null, '070-8983-6897', 'open', 'info', 'approved', 'TourAPI', 'https://www.xn--hq1b18vblaoou1yfqitqlyye.com/', '1840914', 37.1198280836, 126.6935938569, now()),
    (gen_random_uuid(), adm, '횡성더덕축제', '축제', '횡성더덕축제', '2026-09-11', '2026-09-13', '강원', '강원특별자치도 횡성군 청일면 유동리', null, null, 0, 0, null, false, false, false, false, '제13회 횡성더덕축제는 2026년 9월 11일부터 13일까지 3일간 횡성군 청일면 농거리 축제장에서 개최된다. 이번 축제는 ‘더덕향기 솔솔, 웃음소리 가득!’을 주제로 진행되며, 청정한 자연에서 자란 횡성 더덕과 지역 농산물이 한자리에 모인다. 축제 기간에는 더덕을 활용한 음식 체험과 다양한 먹거리 부스가 운영되고, 지역 농가가 직접 참여하는 전시·판매장이 마련된다. 또한 농거리 댄스 경연대회와, 체험 프로그램이 준비되어 있어 방문객들이 직접 참여하고 즐길 수 있는 기회를 제공한다. 횡성의 대표 농산물인 더덕을 중심으로 지역 문화와 공동체가 함께 어우러지는 축제이다.', null, '033-340-2831~5', 'open', 'info', 'approved', 'TourAPI', 'https://deodeok.info/', '2027280', 37.5790750000, 128.1433610000, now()),
    (gen_random_uuid(), adm, '횡성한우축제', '축제', '횡성한우축제', '2026-10-07', '2026-10-11', '강원', '강원특별자치도 횡성군 횡성읍 북천리', null, null, 0, 0, null, false, false, false, false, '제22회 횡성한우축제는 강원특별자치도 횡성군 섬강둔치 일원에서 2026년 10월 7일부터 11일까지 5일간 개최되는 대한민국 대표 체류형 관광축제이다. 본 축제는 ''맛있다, 머물다, 빛나다''를 슬로건으로 ''머무르는 가을, 빛나는 맛의 도시 횡성!''을 주제로 운영된다. 횡성한우의 우수성과 브랜드 경쟁력을 전국에 알리고 지역경제 활성화를 도모하는 것을 목적으로 하며, (재)횡성문화관광재단이 추최 주관한다. 축제는 먹거리·문화예술·체험 3개 테마, 14개 프로그램으로 구성된다. 주간(10:00~18:00)과 야간(18:00~21:00) 프로그램을 연계하여 체류시간을 확대하는 시간 확장형 축제로 운영되며, 지역 상인·농가·주민이 함께 참여하는 상생형 축제이다.', null, '033-808-8007033-808-8009', 'open', 'info', 'approved', 'TourAPI', null, '232325', 37.500463, 127.992519, now()),
    (gen_random_uuid(), adm, '2026 GHOST(경기 한류 OST) 페스티벌', '축제', '2026 GHOST(경기 한류 OST) 페스티벌', '2026-10-09', '2026-10-11', '경기', '경기도 파주시 문산읍 임진각로 148-40', null, null, 0, 0, null, false, false, false, false, '올 가을, 음악으로 떠나는 가장 특별한 한류 여행이 시작된다. 2026 GHOST(Gyeonggi Hallyu OST) 뮤직 페스티벌은 K-드라마와 영화, 애니메이션의 감동을 담은 OST와 대한민국을 대표하는 K-POP 아티스트들이 함께하는 국내 최초 한류 OST 뮤직 페스티벌이다. 3일간 펼쳐지는 공연은 로맨스, SF, 판타지 등 매일 다른 테마로 구성되어 감미로운 발라드부터 강렬한 밴드 사운드, 웅장한 오케스트라 까지 다채로운 무대를 선보인다. 여기에 초대형 미디어아트와 화려한 무대 연출이 더해져 한 편의 영화 속 주인공이 된 듯한 특별한 감동을 선한다. 공연뿐만 아니라 K-콘텐츠 체험, 한류 문화 프로그램, 먹거리, 캠핑까지 함께 즐길 수 있어 가족, 친구, 연인 모두가 하루 종일 머물며 즐기는 새로운 문화축제를 경험할 수 있다.', null, '070-7733-0390', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램', '4087092', 37.8920434573, 126.7447928585, now()),
    (gen_random_uuid(), adm, '2026 경기도자비엔날레', '축제', '2026 경기도자비엔날레', '2026-09-18', '2026-11-01', '경기', '경기도 이천시 경충대로2697번길 263', null, null, 0, 0, null, false, false, false, false, '2026 경기도자비엔날레는 한국 도자재단이 주최하는 국내 대표 국제 도자문화예술 행사로, 2026년 9월 18일 부터 11월 1일까지 경기도 이천·여주·광주 일원에서 개최되는 문화축제이다. 이번 비엔날레는 ''땅이 만든다(Earth Makes)''를 주제로, 흙과 자연, 기술과 예술이 만들어내는 도자의 새로운 가능성과 가치를 선보이는 행사이다. 국제 전시와 공모전, 학술 프로그램, 국제 워크숍뿐만 아니라 키즈 비엔날레, 체험 프로그램, 공예 페스타, 도자마켓, 찾아가는 비엔날레 등 다양한 콘텐츠가 함께 운영될 예정이다. 또한 도민과 국내 작가, 관광객이 함께 참여하는 문화 예술 축제로 경기도 곳곳에서 도자 문화를 경험할 수 있도록 추진되는 행사이다.', null, '031-631-6501', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.gcbiennale.org', '1250585', 37.276920816247, 127.423725332612, now()),
    (gen_random_uuid(), adm, '2026 경북 K-스토리 페스티벌', '축제', '2026 경북 K-스토리 페스티벌', '2026-09-17', '2026-09-18', '경북', '경상북도 안동시 축제장길 66 (안흥동)', null, null, 0, 0, null, false, false, false, false, '2026 경북 K-스토리 페스티벌은 ''K-스토리, 콘텐츠의 시작''을 주제로 열리는 경북의 대표 스토리 콘텐츠 행사이다. 경상북도의 역사와 문화, 지역 창작자들의 감각적인 이야기를 바탕으로, 웹툰·영상·공연·출판 등 다양한 형태의 콘텐츠가 연결되는 현장을 만날 수 있다. 창작자와 바이어를 잇는 스토리 IP 피칭, 저명 연사의 강연과 컨퍼런스, 체험 중심의 가족형 콘텐츠, 전시와 공연 등 다채로운 강연, 공연, 체험 프로그램을 통해 스토리 산업의 현재와 미래를 조망한다. 경북문화재단 콘텐츠진흥원에서 열리는 이번 페스티벌은 이야기의 가능성과 콘텐츠 산업의 가치를 함께 생각하는 창작자·산업관계자·일반 관람객 모두를 위한 연결의 장이다.', null, '054-840-7044', 'open', 'info', 'approved', 'TourAPI', 'https://www.storyg.or.kr/', '2867141', 36.5594898897, 128.7253821840, now()),
    (gen_random_uuid(), adm, '2026 경주 e스포츠 페스티벌', '축제', '2026 경주 e스포츠 페스티벌', '2026-08-15', '2026-08-23', '경북', '경상북도 경주시 황성공원로 29 (황성동)', null, null, 0, 0, null, false, false, false, false, '2026 경주 e스포츠 페스티벌은 2007년부터 시작된 국내 최대 규모의 아마추어 대회인 제18회 대통령배 아마추어 이스포츠 대회와 전국 장애인 선수들이 참여하는 국내 대표 장애인 이스포츠 대회인 제4회 전국 장애인 이스포츠 대회 및 초대형 풀장과 워터바운스에서 즐기는 짜릿한 경주 워터풀 페스티벌을 결합하여 이스포츠와 물놀이를 함께 즐길 수 있는 시원한 여름 축제로 개최된다.', null, '054-776-5956', 'open', 'info', 'approved', 'TourAPI', 'https://garts.kr/', '4087207', 35.8606451724, 129.2090805222, now()),
    (gen_random_uuid(), adm, '2026 고흥 녹동항 드론쇼', '축제', '2026 고흥 녹동항 드론쇼', '2026-04-04', '2026-10-31', '서울', '전남광주통합특별시 고흥군 도양읍 봉암리', null, null, 0, 0, null, false, false, false, false, '천혜의 경관을 가진 고흥에서 밤 하늘을 비출 드론쇼가 진행된다. 고흥 녹동항 드론쇼에서는 명절 특별공연과 유해조류 퇴치 드론 시연, 버스킹 공연 등 다양한 프로그램이 펼쳐진다. 고흥에서 반짝이는 드론이 특별한 순간과 여운을 선사한다. ※ 26. 4. 4.~ 10. 31. 매월 마지막주 금요일, 21시 / 고흥군청 앞 고흥군청광장 900대 규모 드론쇼 / 군민과 하나되는 별밤 버스킹 공연(20시) 연계 진행 ※ 상설공연 종료 후, 해맞이 / 설 명절 특별공연 등 ※ 기상상황 등에 따라 공연 일정 변경 가능', null, '061-830-5902', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://nokdongdrone.co.kr', '2987489', 34.5256000000, 127.1341000000, now()),
    (gen_random_uuid(), adm, '2026 광주 ACE Fair', '축제', '2026 광주 ACE Fair', '2026-09-10', '2026-09-10', '서울', '전남광주통합특별시 서구 상무누리로 30', null, null, 0, 0, null, false, false, false, false, '''김대중컨벤션센터 일원에서 개최되는 문화콘텐츠 종합 전시·축제로, 방송·영상, 애니메이션, 캐릭터, 게임, 웹툰 등 다양한 콘텐츠를 한자리에서 만날 수 있는 행사이다. 산업 관계자를 위한 비즈니스 프로그램과 함께 일반 참관객을 위한 일러스트레이션페어, 무대이벤트, 보드게임존, 세모귀 마켓 등 B2C 행사를 운영하여 보고 즐기며 체험할 수 있는 콘텐츠 축제의 장을 선보인다. 2026 광주 ACE Fair는 방송·영상, 애니메이션, 캐릭터, 게임, 웹툰, 뉴미디어 등 다양한 문화콘텐츠를 아우르는 종합 행사로, 전시와 함께 풍성한 부대행사와 참여형 프로그램을 운영한다. 행사 기간 동안 국내외 콘텐츠 기업과 창작자가 참여하는 전시관을 통해 최신 콘텐츠와 산업 동향을 소개하고, 비즈니스 상담회와 네트워킹 프로그램을 통해 실질적인 교류와 협력 기회를 제공한다. 부대행사 및 프로그램으로는 일반 참관객을 위한 일러스트레이션페어를 운영하여 개성 있는 작가들의 작품과 굿즈를 만날 수 있으며, 크리에이터·아티스트가 참여하는 무대 이벤트, 코스프레 경연대회 등을 통해 현장 소통을 강화한다. 또한 가족과 친구가 함께 즐길 수 있는 보드게임존, 버블쇼를 진행하여 다양한 게임 체험과 ', null, '062-611-2242', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 www.acefair.or.kr
공식 인스타그램 https://www.instagram.com/acefair_gwangjur', '2614198', 35.1468884464, 126.8405217823, now()),
    (gen_random_uuid(), adm, '2026 구미 로컬푸드 페스타', '축제', '2026 구미 로컬푸드 페스타', '2026-09-09', '2026-09-10', '서울', '서울특별시 중구 을지로 지하12 (을지로1가)', null, null, 0, 0, null, false, false, false, false, '2026 구미 로컬푸드 페스탄즌 구미에서 생산하는 농·축산물, G푸드의 우수성을 홍보하고 농가의 판로개척과 소득창출에 기여하며, 서울 도심 속에 구미의 로컬푸드 및 시정을 홍보하고자 추진하는 행사이다. 판매부스 뿐만 아니라 구미시 홍보관, 농식품 수출상담회, 체험행사 등 방문객들이 즐길 수 있는 다양한 프로그램이 마련되며 구니 농특산물 경매 프로그램도 참여할 수 있다.', null, '054-480-6762', 'open', 'info', 'approved', 'TourAPI', 'https://gmmall.cyso.co.kr/', '4093222', 37.5655671650, 126.9783328596, now()),
    (gen_random_uuid(), adm, '2026 국립극장 쏙쏙들이페스티벌', '축제', '2026 국립극장 쏙쏙들이페스티벌', '2026-03-14', '2026-12-26', '경기', '경기도 파주시 탄현면 헤이리로 16', null, null, 0, 0, null, false, false, false, false, '2026 국립극장 쏙쏙들이 페스티벌은 국립극장 무대예술지원센터에서 진행하는 축제 프로그램이다. 본 행사는 시민들이 일상 속에서 공연예술을 쉽게 접할 수 있도록 기획된 행사이다. 해당 페스티벌은 매월 둘째 주와 넷째 주 토요일마다 정기적으로 운영되며 본 축제에서 선보이는 다양한 공연예술 프로그램의 관람료는 전액 무료이다. 이는 지역 시민들의 문화 향유 기회를 확대하기 위한 목적으로 운영된다. 페스티벌의 공연이 개최되는 장소는 국립극장 무대예술지원센터 1층에 위치한 체험극장 "쏙"이다. 축제 공연의 입장권은 공연 당일 오후 12시부터 현장 안내 데스크에서 선착순으로 배부된다. 해당 입장권은 객석의 좌석수에 따라 조기 마감 될 수 있다. 본 축제는 남녀노소 누구나 익숙하고 편안하게 감상하며 모든 세대가 함께 호흡하고 즐길 수 있는 역동적인 무대들로 구성된다. 축제 참여 아티스트들은 대중적인 장르를 기반으로 자신들만의 독창적인 스타일을 선보인다.', null, '031-870-9110', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.ntok.go.kr/sasc', '3488421', 37.7832839326, 126.6946859929, now()),
    (gen_random_uuid(), adm, '2026 국제선명상대회', '축제', '2026 국제선명상대회', '2026-04-03', '2026-11-12', '서울', '서울특별시 강남구 봉은사로 531 (삼성동)', null, null, 0, 0, null, false, false, false, false, '대한불교조계종이 주최하는 국제선명상대회와 선명상축제는 국민 정신건강 증진을 위하여 진행하고 있으며, 지난 2024년부터 시작하여 올해로 3회를 맞이하였다. 올해는 [AI시대의 선명상]이라는 주제하에 선명상이 국민의 정신건강에 도움을 줄 수 있는 방법을 모색하며, 연계된 선명상 축제를 통해 국민들이 직접 다양한 분야의 선명상을 체험할 수 있는 기회를 제공한다.', null, '010-8441-2371', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://seonmeditationsummit.kr/', '3377038', 37.5158257049833, 127.057734484281, now()),
    (gen_random_uuid(), adm, '2026 금남로 차 없는 거리 ‘걷자잉’', '축제', '2026 금남로 차 없는 거리 ‘걷자잉’', '2026-04-04', '2026-11-07', '서울', '전남광주통합특별시 동구 금남로 245 (금남로1가)', null, null, 0, 0, null, false, false, false, false, '''걷자잉''은 사투리와 현재진행형 ''ing''를 접목하여, 금남로를 함께 걸으면서 즐겨보자는 의미이다. 광주의 ‘대·자·보 도시''(대중교통·자전거·보행) 전환 선언에 맞추어 기후 위기를 극복하고, 대자보 활성화 등 도심 속 쉼과 소통이 어우러진 거리를 만드는 행사이다. 2026년에는 4월부터 11월까지 매월 첫째 주 토요일에 진행되고 행사에서는 시민들이 자유롭게 걸을 수 있는 환경을 제공하며, 다양한 체험 프로그램과 문화 공연이 함께 운영된다.', null, '062-413-2535', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/walkinging_festa', '3478890', 35.14836487617714, 126.91873155733187, now()),
    (gen_random_uuid(), adm, '2026 남도 K-가든 페스티벌', '축제', '2026 남도 K-가든 페스티벌', '2026-09-11', '2026-10-31', '서울', '전남광주통합특별시 여수시 문수로 124 (여서동)', null, null, 0, 0, null, false, false, false, false, '2026 남도 K-가든 페스티벌은 여수시 여문문화의거리와 여서미관광장 일원에서 개최되는 야간 정원축제이다. 축제 주제는 「섬 품은 여수 밤정원」이며, 행사기간은 2026년 9월 11일부터 10월 31일까지 총 51일간 진행된다. 축제는 정원과 야간경관을 연계한 콘텐츠를 통해 원도심의 공간적 특성을 활용하고, 시민과 관광객에게 정원문화 향유 기회를 제공하는 것을 목적으로 한다. 행사장에는 대표정원, 작가정원, 시민참여정원 등 약 40여 개의 정원이 조성되며, 다양한 식물과 경관 연출을 통해 주·야간 모두 관람이 가능한 공간으로 운영된다. 야간에는 조명 연출을 적용하여 정원의 경관을 강조하고, 여수의 야간 관광자원과 연계한 관람환경을 제공한다. 행사기간동안 정원해설 프로그램, 문화공연, 체험프로그램, 시민참여프로그램 등 다양한 콘텐츠를 운영하며, 지연상권 및 관광자원과 연계한 프로그램도 함께 추진한다. 2026 남도 K-가든 페스티벌은 정원문화 확산과 원도심 활성화를 도모하고, 여수의 정원도시 기반을 구축하기 위한 행사이다. 시민과 관광객이 함께 참여하고 향유할 수 있는 정원축제를 통해 지역의 문화·관광 자원을 활용하여 지속가능한 정원문화 확산을 추진하는 것을 ', null, '010-5865-2532', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://ysgarden.kr/', '4095228', 34.7555508881, 127.7081166574, now()),
    (gen_random_uuid(), adm, '2026 달성 대구현대미술제  Movement: Flow-Ringer-Flux', '축제', '2026 달성 대구현대미술제  Movement: Flow-Ringer-Flux', '2026-09-11', '2026-10-11', '대구', '대구광역시 달성군 다사읍 강정본길 57', null, null, 0, 0, null, false, false, false, false, '달성 대구현대미술제는 1970년대 젊은 작가들이 기성 미술계의 경직성에 도전하며 다양한 미술 실험을 펼쳤던 ''대구 현대 미술제''의 정신을 계승하여 강정보 일원에서 열리는 현대미술축제이다. 달성 대구 현대 미술제가 개최되는 장소인 강정은 1977년 ''제3회 대구 현대 미술제'' 당시, 역대 최대 규모인 200여 명의 작가가 참여한 한국 최초의 집단적 이벤트가 펼쳐진 장소로 그 의의를 가진다.', null, '053-668-4245', 'open', 'info', 'approved', 'TourAPI', 'http://www.dalseongart.com/', '2392105', 35.8412414475, 128.4649553312, now()),
