    (gen_random_uuid(), adm, '2026 라온페스타', '축제', '2026 라온페스타', '2026-04-04', '2026-11-07', '서울', '전남광주통합특별시 동구 충장로 94 (충장로2가)', null, null, 0, 0, null, false, false, false, false, '충장 라온페스타는 지난 2022년부터 충장상권활성화 사업 일환으로 충장로와 지하 상점가의 소비 촉진과 상권 내 방문객을 유도해 지역경제를 활성화 하기 위해 마련된 상권페스타이다. 남녀노소 누구나 함께 즐길 수 있는다양한 문화·체험 프로그램이 준비되어 있다. 라온페스타는 4월부터 매달 첫째 주 토요일에 진행되며 시간은 프로그램 별로 상이하다.', null, '062-413-1274', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/chungjang_zip/', '2865136', 35.1474235264676, 126.91694835998, now()),
    (gen_random_uuid(), adm, '2026 로컬 그라운드 연남', '축제', '2026 로컬 그라운드 연남', '2026-08-29', '2026-08-29', '서울', '서울특별시 마포구 동교로 264 (연남동)', null, null, 0, 0, null, false, false, false, false, '로컬 그라운드 연남은 연남동 골목과 지역 상권을 무대로 펼쳐지는 로컬 문화축제이다. 연남동만의 개성 있는 공간과 상점, 문화 콘텐츠를 하나의 축제로 연결하여 방문객에게 골목 곳곳을 걷고 머물며 즐기는 새로운 경험을 제공하는 행사이다. 단순히 관람하는 축제를 넘어 지역 상점과 방문객이 자연스럽게 만나고 소통할 수 있도록 플리마켓, 버스킹 공연, 체험 프로그램, 이벤트 등 다채로운 콘텐츠를 운여하는 것이 특징이다. 특히 연남동의 자유롭고 감각적이 분위기와 경의선 숲길을 중심으로 형성된 피크닉 문화를 축제 콘텐츠와 결합하여 누구나 편안하게 즐길 수 있는 도심속 골목축제를 조성하고자 한다. 이를 통해 방문객에게는 연남동의 새로운 매력을 발견하는 기회를 제공하고, 지역 상점에는 새로운 방문과 소비로 이어지는 접점을 마련하는 행사이다. 지역의 공간과 사람, 상권과 문화가 함께 어우러지는 축제를 통해 연남동만의 차별화 된 로컬 문화를 알리고 골목 상권에 새로운 활력을 더하고자 하는 행사이다.', null, '010-7621-3714', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/yeonnam_union', '4099133', 37.5630499816, 126.9253625142, now()),
    (gen_random_uuid(), adm, '2026 목포해상W쇼', '축제', '2026 목포해상W쇼', '2026-05-09', '2026-09-19', '서울', '전남광주통합특별시 목포시 평화로 82 (상동)', null, null, 0, 0, null, false, false, false, false, '대한민국 4대 관광거점도시 목포의 야간 상설 대표 콘텐츠 ‘목포해상W쇼’는 국내 유일 멀티미디어 융합 쇼 콘텐츠로서 해상무대 공연, 국내최대 해상분수, 불꽃쇼 등이 결합한 공연이다. 5년간 총 51회의 공연과 누적 관객수 105만명이 즐긴 대한민국 대표 체류형 야간문화 자산이다. 2026 목포해상W쇼는 더욱 풍성한 해상공연과 화려한 불꽃, 역동적인 바다분수가 연출된다.', null, '061-270-8431', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://mokpowshow.co.kr/', '2774275', 34.79666213605975, 126.43379088761164, now()),
    (gen_random_uuid(), adm, '2026 문화가 있는 날', '축제', '2026 문화가 있는 날', '2026-04-01', '2026-11-29', '인천', '인천광역시 제물포구 송현동', null, null, 0, 0, null, false, false, false, false, '청춘마이크 수도·강원권은 다양한 관객의 취향을 추적하며 방방곡곡을 누빈다. 문화가 있는 날 청년·실버 공연팀이 만들어내는 특별한 거리공연이 수도·강원권 전역을 무대로 펼쳐진다. 지금 이 순간 무대에 서고 싶은 마음이 모여 하나가 되는 청춘의 무대, ''I.M 청춘마이크''가 4월부터 11월까지 진행된다.', null, '032-575-2526, 070-5001-0265', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/sg_youngmic/', '3492276', 37.476334, 126.632619, now()),
    (gen_random_uuid(), adm, '2026 문화가 있는 날 청춘마이크', '축제', '2026 문화가 있는 날 청춘마이크', '2026-03-12', '2026-12-11', '서울', '전남광주통합특별시 북구 하서로 50 (운암동)', null, null, 0, 0, null, false, false, false, false, '[청춘어람, ''전통을 따르는 청년 새로움을 찾는 노년''] ''청춘어람''은 청년과 신노년세대의 공명을 통해 세대의 벽을 허물고, 경험과 새로움을 나누며 동반성장하는 문화플랫폼이다. ​2026 문화요일 청춘마이크 전라·제주권은 지역공연팀에게 일상 속 공연 기회와 교류·협력의 장을 제공하여 성장의 발판을 마련하고, 이를 통해 지역 간 균형 있는 문화 참여 기회를 확대함으로써 모든 국민이 일상에서 예술을 누리는 지역 문화 균형 발전을 실현한다.', null, '062-412-1197', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://youngmic.com', '3488655', 35.1814560887758, 126.884278856104, now()),
    (gen_random_uuid(), adm, '2026 문화가 있는날  - 문화배달', '축제', '2026 문화가 있는날  - 문화배달', '2026-06-24', '2026-10-31', '경기', '경기도 연천군 중면 군중로 324-1', null, null, 0, 0, null, false, false, false, false, '문화가 있는 날 는 도서·벽지·접경지역, 산업단지, 문화환경취약지역 등 문화접근성이 낮은 지역을 찾아가는 문화 예술 지원사업이다. 청년·실버 공연팀이 일상 가까운 공간에서 다양한 거리공연을 선보이며, 누구나 지역에서 쉽게 문화를 경험하고 즐길 수 있는 기회를 만든다. 예술이 필요한 곳으로 직접 찾아가 문화의 가치를 나누는 는 6월부터 10월까지 수도·강원권 곳곳에서 시민들의 일상에 특별한 문화 경험을 전하는 사업이다.', null, '033-253-7111', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://ccmicsynergy2026.imweb.me/index', '3495437', 38.1345233861, 127.0274821632, now()),
    (gen_random_uuid(), adm, '2026 별바다부산 「나이트 캠크닉」', '축제', '2026 별바다부산 「나이트 캠크닉」', '2026-09-04', '2026-09-19', '부산', '부산광역시 사하구 다대동 1674', null, null, 0, 0, null, false, false, false, false, '2026년 9월, 다대포 해변공원이 감성 가득한 축제의 장으로 변신한다. ‘2026 별바다부산 나이트 뮤직 캠크닉’은 노을 맛집으로 유명한 다대포의 매력을 한껏 살린 특별한 행사이다. 이번 행사는 단순히 즐기는 것을 넘어 다채로운 프로그램으로 구성되어 있다. 먼저 아름다운 노을을 배경으로 맛있는 음식을 즐기는 ‘선셋 잇크닉’이 준비되어 있으며, 별빛 아래 흐르는 라이브 음악과 함께 캠핑 감성을 만끽하는 ‘나이트 뮤직 캠크닉’이 방문객을 맞이한다. 또한, 반려견과 함께 소중한 추억을 남길 수 있는 ‘플레이 멍크닉’과 지친 일상에 활력을 불어넣어 줄 ‘웰니스 프로그램’까지 마련되어 있다. 행사는 9월 4일부터 19일까지, 매주 금요일과 토요일 저녁 5시부터 10시까지 다대포 해변공원 제1~3광장에서 진행된다.', null, '051-626-8816', 'open', 'info', 'approved', 'TourAPI', 'https://www.visitbusan.net', '4099532', 35.0460822222, 128.9666308248, now()),
    (gen_random_uuid(), adm, '2026 부산국제공연예술마켓(BPAM)', '축제', '2026 부산국제공연예술마켓(BPAM)', '2026-10-01', '2026-10-07', '부산', '부산광역시 해운대구 센텀중앙로 55 (우동)', null, null, 0, 0, null, false, false, false, false, '부산국제공연예술마켓(Busan International Performing Arts Market·BPAM·비팜)은 2023년 첫 개최를 시작으로 올해 4회차를 맞이한, 글로벌 허브도시 부산에서 열리는 축제형 공연예술마켓이다. 예술가, 기획자, 프로듀서 등 국내외 공연예술 전문가들이 한자리에 모여 작품을 소개하고 네트워크를 구축하며 협업과 유통의 가능성을 모색하는 국제 교류의 장이자, 공연예술 관계자 뿐 아니라 시민 누구나 함께 즐길 수 있는 행사이다.', null, '051-745-7298', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://bpam.kr/
