    (gen_random_uuid(), adm, '2026 서귀포 원도심 문화페스티벌', '축제', '2026 서귀포 원도심 문화페스티벌', '2026-04-11', '2026-10-30', '제주', '제주특별자치도 서귀포시 이중섭로 11 (서귀동)', null, null, 0, 0, null, false, false, false, false, '2026 서귀포 원도심 문화페스티벌’은 서귀포 이중섭로에서 펼쳐지는 야간 문화공연이다. 화려한 조명 아래 음악, 댄스, 퍼포먼스 등 다양한 장르의 공연이 관객들들에게 다양한 볼거리를 제공한다. 일상에서 벗어나 예술과 여유가 어우러진 특별한 추억을 남기고 싶은 이들에게 적극 추천하는 행사이다. ‘2026 서귀포 원도심 문화페스티벌’은 4월 11일부터 매주 금~일요일 저녁 7시에 운영되며, 10월 30일까지 이어진다. 서귀포 원도심의 감성적인 밤, ‘2026 서귀포 원도심 문화페스티벌’이 당신을 기다리고 있다. ※ 단, 기상악화 및 우천시 공연이 취소될 수 있으므로 사전 문의 요망', null, '064-760-2572', 'open', 'info', 'approved', 'TourAPI', null, '3512205', 33.24708081676599, 126.56445889201075, now()),
