    (gen_random_uuid(), adm, '2026 섬 방문의 해', '축제', '2026 섬 방문의 해', '2026-03-01', '2026-12-31', '서울', '전남광주통합특별시 여수시 선어시장길 6 (중앙동)', null, null, 0, 0, null, false, false, false, false, '2026 섬 방문의 해는 대한민국 섬이 지닌 생태·문화적 자산을 새롭게 조명하고, 대한민국을 세계가 주목하는 섬 관광 강국으로의 도약을 본격화한다. 특히, 2026년은 세계 최초로 섬을 주제로 개최되는 ''2026 여수세계섬박람회''와 연계하여 더욱 풍성한 볼거리와 즐길거리를 제공한다. 박람회의 열기를 전국 섬으로 확산시키고, 섬 여행비 지원 프로모션부터 문화 주간 행사 등 2026년 한 해 동안 펼쳐지는 다채로운 프로그램을 통해 섬이 선사하는 진정한 휴식과 새로운 활력을 직접 경험할 수 있다.', null, '070-4337-5058', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.visitisland.kr', '4067214', 34.7395781561546, 127.736371787128, now()),
    (gen_random_uuid(), adm, '2026 숭례문 파수의식', '축제', '2026 숭례문 파수의식', '2026-01-01', '2026-12-31', '서울', '서울특별시 중구 세종대로 40 (남대문로4가)', null, null, 0, 0, null, false, false, false, false, '숭례문을 지키는 ''숭례문 파수의식'' 은 월요일은 공식 휴무일이며, 월요일 제외 매일 10:00~15:40 운영된다. 파수(把守)란 도성(都城)을 수비하는 것으로 조선시대 중요한 군례의식의 하나이다. 조선시대 도성수비는 가장 중요한 문제였으며, 특히 선조 때 임진왜란과 병자호란 등을 겪으면서 심각한 문제로 대두되었다. 파수의식은 인정과 파루에 도성문을 열고 닫는 도성문 개폐의식과 순라의식 등을 연결하는 조선시대 군례의식으로 중앙군제 중 그 위치와 역할 등을 고려해보면 궁성을 수위하는 것 못지않게 중요한 의식이다. ''숭례문 파수의식'' 행사 절차는 파수군들이 근무지인 숭례문 앞에 도열, 파루를 알리는 금루관이 등장하며 이후 나각과 나발의 신호가 울린다. 호군의 명령에 따라 파수군은 숭례문 개문의식을 진행한다. 이후 숭례문을 수위하는 파수의식이 시작되며 1대파수군과 2대파수군의 근무교대 후 파수의식을 진행한다. 이후 6회의 교대의식 및 파수의식을 진행하며 이후 호군의 명령에 따라 파수군은 숭례문 폐문의식을 진행한다.', null, '02-3789-7402', 'open', 'info', 'approved', 'TourAPI', 'https://www.royalguard.kr', '3107059', 37.55992837962214, 126.97536090852309, now()),
    (gen_random_uuid(), adm, '2026 안산 e스포츠 페스티벌', '축제', '2026 안산 e스포츠 페스티벌', '2026-08-29', '2026-08-29', '경기', '경기도 안산시 상록구 용신로 422 (본오동)', null, null, 0, 0, null, false, false, false, false, '2026 안산 e스포츠 페스티벌은 안산시가 주최하는 지역 e스포츠 축제로, 2026년 8월 29일 상록수김연경체육관에서 열린다. 2023년에 시작해 올해로 4회째를 맞는다. 이날 e스포츠 대회 결선으로 리그오브레전드 관내 대회와 테일즈런너 전국 대회가 치러지고, 코스프레 퍼포먼스 경연도 함께 열린다. 테일즈런너부스, 브롤스타즈 랜파티, 코스프레 존, 레트로 게임 존에서는 관람객이 직접 게임을 즐길 수 있다. 인플루언서 밍모와 코스어 정재니·온양갱·노에·캡스파가 현장을 찾아 팬들과 만난다. 청년부터 가족 단위 방문객까지 게임을 즐기며 하루를 보낼 수 있는 축제이다.', null, '031-369-1787', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/ansan_esports', '4090802', 37.3009563527, 126.8685769631, now()),
    (gen_random_uuid(), adm, '2026 전국 장애학생 e페스티벌', '축제', '2026 전국 장애학생 e페스티벌', '2026-09-08', '2026-09-09', '강원', '강원특별자치도 홍천군 서면 한치골길 262', null, null, 0, 0, null, false, false, false, false, '2026 전국 장애학생 e페스티벌은 국립특수교육원, 한국콘텐츠진흥원, 넷마블문화재단이 공동 주최하는 전국 단위의 장애학생 대상 행사이다. 2026년 행사는 ''AI로 여는 세상e, 무한한 가능성e''를 주제로 개최되며, 전국 17개 시·도에서 선발된 장애학생과 지도교사, 관계자 등이 참가한다. 행사는 e스포츠대회와 정보경진대회를 중심으로 운영되며, 인공지능(AI) 및 디지털 기술 체험 프로그램, 문화공연, 전시 및 체험부스, 교류 프로그램 등 다양한 콘텐츠로 구성된다. 참가 학생들은 5월 27일부터 진행되는 지역예선대회를 거쳐 본·결선 대회에 참가하며, e스포츠와 정보경진 분야에서 기량을 발휘하고 다양한 디지털 기술과 문화 콘텐츠를 체험하게 된다. 또한 행사 기간 동안 참가 학생 간 교류와 소통을 위한 프로그램이 함께 운영되며, 장애학생의 디지털 활용 역량 향상과 정보 문화 참여 기회 확대를 지원하는 교육·문화 행사이다.', null, '010-2751-1082', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 http://www.2026전국장애학생e페스티벌.com/
공식 인스타그램 https://www.instagram.com/efestival_official/', '4075091', 37.6521031527, 127.6871063500, now()),
    (gen_random_uuid(), adm, '2026 제14회 경기정원문화박람회', '축제', '2026 제14회 경기정원문화박람회', '2026-10-16', '2026-10-19', '경기', '경기도 양평군 양서면 양수로 93', null, null, 0, 0, null, false, false, false, false, '2026 제14회 경기정원문화박람회는 남한강과 북한강이 만나는 두물머리와 지방정원 1호 세미원을 배경으로 펼쳐지는 정원문화 축제이다. 이번 박람회의 주제는 ''두물머리 사:색''으로, 사계절을 담은 네 가지 색을 통해 자연의 순환을 보여주고, 동시에 삶의 본질을 사색하는 의미를 담고 있다. 두물머리와 세미원을 잇는 정원 속에서 계절의 색을 느끼며 머무르고, 스스로를 돌아보는 특별한 시간을 경험할 수 있다.', null, '031-770-2572', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://www.gggarden.kr', '2667707', 37.5409386578, 127.3239607947, now()),
    (gen_random_uuid(), adm, '2026 제5회 제주비엔날레 허끄곡 모닥치곡 이야홍 : 변용의 기술', '축제', '2026 제5회 제주비엔날레 허끄곡 모닥치곡 이야홍 : 변용의 기술', '2026-08-25', '2026-11-15', '제주', '제주특별자치도 제주시 1100로 2894-78 (연동)', null, null, 0, 0, null, false, false, false, false, '유라시아판의 화산섬 제주에서 꽃 핀 문명은 바다로부터 흘러들었을 뿐만 아니라 북방 육지 문영으로부터 도래하였다. 온갖 요소들이 흩어져 제주로 모여 들고 한데 섞여 변용되며 오늘의 제주라는 생태와 지리, 그리고 삶의 모양을 만들었다. 올 해로 10년 째로 접어든 제5회 제주비엔날레는 북방문명과 만나 흩어지고(허끄다), 모이고(모닥치다), 변용(이야홍)되어 제주의 역독적 과정에 주목한다. 이를 위해 비엔날레에서는 육지에서 흘러들어 제주의 또 다른 토착 민요가 된 이야홍 타령의 후렴구 ''이야홍(Iyahong)''을 주제어이자 핵심 개념으로 삼는다. 기후와 섭생의 원리가 깃든 제주를 통해, 제주비엔날레는 사물과 자연, 인간의 삶과 신성(神性)이 함께 빚어온 생존의 방식과 그 미학을 제시하고자 한다.', null, '064-710-4300', 'open', 'info', 'approved', 'TourAPI', '홈페이지 : http://www.jejubiennale.org/', '3399432', 33.4525500193, 126.4896860910, now()),
    (gen_random_uuid(), adm, '2026 제물포웨이브 마켓', '축제', '2026 제물포웨이브 마켓', '2026-08-29', '2026-08-30', '인천', '인천광역시 제물포구 월미로 33 (북성동1가)', null, null, 0, 0, null, false, false, false, false, '8월 29일(토)부터 30일(일)까지, 인천을 대표하는 로컬 브랜드들과 즐기는 미식 투어. F&B, 문화, 공예, 뷰티, 패션 등 다양한 분야의 자체 제작 및 브랜드 상품들을 직접 보고, 맛보고, 골라 갈 수 있는 플리마켓으로, 캔들, 향수, 러그 등의 다양한 핸드메이드 소품과 전시도 준비되어 있다. 2026년 2회차 제물포웨이브마켓의 콘셉트는 “미식”으로, 약 50개의 인천 카페 및 맛집 브랜드들이 참여할 예정이다. 행사 당일에는 플리마켓 뿐만 아니라, ''미식 블라인드 테스트'', ''영수증 럭키드로우'', ''오늘의 마켓 위너는?'' 등의 게릴라 이벤트와 ''워리스톤 만들기'', ''라탄 바구니 만들기'', ''캐리커처'', ''커피박 키링 만들기''와 같은 상시 체험존, 버스킹 공연도 준비되어 있다.', null, '010-9331-3760', 'open', 'info', 'approved', 'TourAPI', '공식 인스타그램 https://www.instagram.com/jemulpowav_official', '3315407', 37.4760834131, 126.6146527143, now()),
    (gen_random_uuid(), adm, '2026 제주올레걷기축제', '축제', '2026 제주올레걷기축제', '2026-11-05', '2026-11-07', '제주', '제주특별자치도 제주시 조천읍 조천리 1141', null, null, 0, 0, null, false, false, false, false, '제주의 자연이 가장 빛나는 가을, 제주올레 길 위에서 특별한 축제가 펼쳐진다. 매년 11월 열리는 제주올레걷기축제는 3일 동안 제주 올레 길을 걸으며 다양한 문화예술공연과 전통놀이 및 마을 프로그램, 제주 먹거리를 즐기는 이동형 축제이다. 때로는 파도소리를 배경으로 음악회가, 때로는 축제 들판을 배경으로 한 제주 전통공연이 펼쳐지며, 축제가 열리는 지역 농수산물로 만든 오감만족 먹거리 또한 즐길 수 있다. 매년 1만여 명의 올레꾼이 참가하는 제주올레걷기축제는 해를 거듭할수록 중국, 대만, 일본, 미국, 영국,캐나다 등에서 온 외국인 참가자가 늘어나며 세계인의 걷기 축제로 거듭나고 있다.', null, '064-762-2190', 'open', 'info', 'approved', 'TourAPI', '공식 홈페이지 https://contents.ollepass.org/
